// Define max chunk size based on available system memory
#define MAX_CHUNK_SIZE (1 << 20) // 1MB

int main(int argc, char *argv[]) {
    int c;
    FILE *fp = NULL;
    char *input_file = NULL;
    char *output_format = NULL;
    int output_flag = 0;

    while ((c = getopt(argc, argv, "f:o:")) != -1) {
        switch (c) {
            case 'f':
                output_format = optarg;
                break;
            case 'o':
                output_flag = 1;
                input_file = optarg;
                break;
            default:
                printf("Usage: %s [-f format] [-o output_file] [input_file]\n", argv[0]);
                exit(1);
        }
    }

    if (optind < argc) {
        input_file = argv[optind];
    }

    // Check for --manpage option
    for (int i = 1; i < argc; ++i) {
        if (!strcmp(argv[i], "--manpage")) {
            printf("This program prints the number of lines in a given input file.\n");
            printf("Usage: %s [-f format] [-o output_file] [input_file]\n", argv[0]);
            exit(0);
        }
    }

    // Validate output format string
    if (output_format) {
        for (char *p = output_format; *p; ++p) {
            if (!isalnum(*p) && !strchr(".%s", *p)) {
                printf("Invalid character in output format: %c\n", *p);
                exit(1);
            }
        }
    }

    int fd = -1;
    char *chunk = NULL;

    // Open input file
    if (input_file) {
        fp = fopen(input_file, "r");
        if (!fp) {
            perror("Error opening input file");
            exit(1);
        }

        // Set chunk size based on available system memory
        size_t total_memory = sysconf(_SC_PHYS_PAGES) * sysconf(_SC_PAGE_SIZE);
        size_t max_chunk_size = MIN((size_t)MAX_CHUNK_SIZE, total_memory / 16); // Adjust for overhead
        size_t chunk_size = min(max_chunk_size, (size_t)1 << 20); // Start with a smaller chunk size

        while (1) {
            // Read chunk from file
            if ((fd = open(input_file, O_RDONLY)) == -1) {
                perror("Error opening input file");
                exit(1);
            }

            chunk_size = min(chunk_size, (size_t)(1 << 20)); // Limit chunk size to avoid excessive memory usage
            char *buffer = malloc(chunk_size);
            if (!buffer) {
                perror("Error allocating memory for chunk");
                exit(1);
            }

            ssize_t bytes_read = pread(fd, buffer, chunk_size, ftell(fp));
            if (bytes_read == -1) {
                perror("Error reading from file");
                exit(1);
            }

            // Process chunk
            size_t lines = 0;
            char *line = buffer;
            while (*line) {
                line += strlen(line) + 1; // Advance to next line
                ++lines;
            }

            free(buffer);

            if (output_flag && output_format) {
                printf(output_format, lines);
            } else {
                printf("Total lines: %zu\n", lines);
            }

            // Release resources before possible interruption
            close(fd);
            fd = -1;

            // Resume from where we left off if interrupted
            if (fseek(fp, ftell(fp) + bytes_read, SEEK_SET) == -1) {
                perror("Error seeking to previous position");
                exit(1);
            }
        }

        fclose(fp);
    } else {
        printf("Usage: %s [-f format] [-o output_file] [input_file]\n", argv[0]);
        exit(1);
    }

    return 0;
}
