        perror("Error opening input file");
        return -1;
    }

    // Read the binary file
    fseek(file, 0L, SEEK_END);
    long size = ftell(file);
    rewind(file);

    unsigned char* buffer = (unsigned char*)malloc(size);
    fread(buffer, 1, size, file);
    fclose(file);

    // Parse the contents of the binary file based on the rules
    ParsingRule* rules = malloc(sizeof(ParsingRule));
    int num_rules = sscanf(rules_str, "%d %s", &rules->id, rules->rule);
    if (num_rules != 2) {
        free(buffer);
        free(rules);
        return -1;
    }

    // Load additional parsing rules from the configuration file
    FILE* config_file = fopen(config_path, "r");
    if (!config_file) {
        perror("Error opening configuration file");
        free(buffer);
        free(rules);
        return -1;
    }

    ParsingRule* config_rules = malloc(sizeof(ParsingRule));
    int num_config_rules = sscanf(config_file, "%d %s", &config_rules->id, config_rules->rule);
    if (num_config_rules != 2) {
        fclose(config_file);
        free(buffer);
        free(rules);
        return -1;
