#include <stdio.h>
#include <stdlib.h>

// Function to find the maximum integer in an array
int maxInt(int* arr, int size) {
    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max)
            max = arr[i];
    }
    return max;
}

// Function to read integers from standard input and find the maximum
void readAndPrintMax() {
    int* array = NULL;
    int size = 0;

    // Read integers from standard input until a blank line is encountered
    while (1) {
        char buffer[256];
        fgets(buffer, sizeof(buffer), stdin);

        // Check if the current line is empty or contains only whitespace characters
        if (buffer[0] == '\n' || buffer[0] == ' ') {
            break;
        }

        // Parse the integer from the current line
        int num = atoi(buffer);
        size++;

        // Dynamically allocate memory for the array based on user input
        if (size > 1000) {
            printf("Error: Maximum allowed size exceeded.\n");
            exit(EXIT_FAILURE);
        }
        array = (int*) realloc(array, sizeof(int) * size);

        // Store the integer in the array
        array[size - 1] = num;
    }

    // Check if any integers were read
    if (size == 0) {
        printf("Error: No valid input.\n");
        exit(EXIT_FAILURE);
    }

    // Find and print the maximum integer in the array
    int max = maxInt(array, size);
    printf("The largest integer is %d.\n", max);

    // Free dynamically allocated memory for the array
    free(array);
}
