#define LOG_FILE_MAX_SIZE 1024
#define MAX_LOG_MESSAGES 1000
#define TIME_FRAME_SEC 60 // in seconds

int log_file_fd = -1;
int log_count = 0;
time_t last_log_time = 0;

void log_message(const char *level, const char *format, ...) {
    time_t current_time = time(NULL);
    if (current_time - last_log_time < TIME_FRAME_SEC) {
        // Limit log messages within a certain time frame
        return;
    }

    last_log_time = current_time;

    va_list args;
    va_start(args, format);

    if (log_file_fd != -1) {
        char message[LOG_FILE_MAX_SIZE];
        vsnprintf(message, LOG_FILE_MAX_SIZE, "%s: %s", level, format);
        write(log_file_fd, message, strlen(message));
    }

    // Log to system error log
    syslog(level, "%s", format);

    va_end(args);

    if (++log_count >= MAX_LOG_MESSAGES) {
        // Rotate log file
        close(log_file_fd);
        log_file_fd = open("log.txt", O_WRONLY | O_CREAT, 0644);
    }
}
