import hashlib
import chardet
from io import BytesIO
from urllib.request import urlopen, Request


def calculate_sha256_hash(file_url=None, file_path=None, buffer_size=2**20, encoding='utf-8'):
    if not (file_url or file_path):
        raise ValueError("Either file_url or file_path must be provided")

    if file_url:
        request = Request(file_url)
        response = urlopen(request)
        file_content = BytesIO(response.read())
    elif file_path:
        with open(file_path, 'rb') as f:
            file_content = BytesIO(f.read())

    sha256_hash = hashlib.sha256()

    while True:
        chunk = file_content.read(min(buffer_size, 2**20))
        if not chunk:
            break

        chunk = chunk.decode(encoding).encode()
        if encoding != 'utf-8':
            chunk = chunk.decode('utf-8', errors='replace').encode()

        sha256_hash.update(chunk)

    return sha256_hash.hexdigest()
