#include <openssl/aes.h>
#include <openssl/err.h>

EVP_CIPHER_CTX* aes_set_key_schedule(unsigned char* key) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        ERR_error_fp(stderr, NULL);
        return NULL;
    }

    int key_len = strlen((char*)key);
    if (key_len < 32) {
        // Handle invalid key length
        ERR_error_fp(stderr, "Invalid AES-256 key length");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    if (!EVP_CipherInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, key_len, 1)) {
        // Handle initialization error
        ERR_error_fp(stderr, "Initialization error while setting AES-256 key schedule");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}

EVP_CIPHER_CTX* aes_encrypt(char* plaintext, size_t plaintext_len, unsigned char** ciphertext) {
    EVP_CIPHER_CTX* ctx = aes_set_key_schedule("your_secret_key_here"); // Set your secret key here
    if (!ctx) {
        return NULL;
    }

    int ct_len;
    int pt_len = strlen((char*)plaintext);

    if (!EVP_CipherUpdate(ctx, *ciphertext, &ct_len, (unsigned char*)plaintext, pt_len)) {
        ERR_error_fp(stderr, "Error while encrypting");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    EVP_CIPHER_CTX_set_padding(ctx, 1);

    if (!EVP_CipherFinal_ex(ctx, *ciphertext + ct_len, &ct_len)) {
        ERR_error_fp(stderr, "Error while finalizing encryption");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    EVP_CIPHER_CTX_free(ctx);

    // Return the encrypted data
    *ciphertext = realloc(*ciphertext, (size_t)(ct_len + pt_len));
    if (!*ciphertext) {
        ERR_error_fp(stderr, "Memory allocation error");
        return NULL;
    }

    return ctx; // Return the cipher context for further operations
}

EVP_CIPHER_CTX* aes_decrypt(unsigned char* ciphertext, size_t ciphertext_len, unsigned char** plaintext) {
    EVP_CIPHER_CTX* ctx = aes_set_key_schedule("your_secret_key_here"); // Set your secret key here
    if (!ctx) {
        return NULL;
    }

    int pt_len;
    int ct_len = ciphertext_len;

    if (!EVP_CipherUpdate(ctx, *plaintext, &pt_len, (unsigned char*)ciphertext, ct_len)) {
        ERR_error_fp(stderr, "Error while decrypting");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    EVP_CIPHER_CTX_set_padding(ctx, 0);

    if (!EVP_CipherFinal_ex(ctx, *plaintext + pt_len, &pt_len)) {
        ERR_error_fp(stderr, "Error while finalizing decryption");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    EVP_CIPHER_CTX_free(ctx);

    // Return the decrypted data
    *plaintext = realloc(*plaintext, (size_t)(ciphertext_len - pt_len));
    if (!*plaintext) {
        ERR_error_fp(stderr, "Memory allocation error");
        return NULL;
    }

    return ctx; // Return the cipher context for further operations
}
```

Remember to replace `"your_secret_key_here"` with your actual secret key. The code above handles the setup of an AES-256 encryption/decryption process using different modes (ECB, CBC, CTR) and includes padding/unpadding mechanisms for data blocks.']

