#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dlfcn.h>
#include <pthread.h>

// Define the cipher structure to hold module info and functionality
typedef struct {
    void* handle;
    int (*encrypt)(const char*, size_t);
    int (*decrypt)(const char*, size_t);
} Cipher;

// Load a cipher module from a file path and initialize it
Cipher* load_cipher_module(const char* file_path) {
    // Dynamically load the shared library
    void* lib_handle = dlopen(file_path, RTLD_LAZY);
    if (!lib_handle) {
        fprintf(stderr, "Error loading library: %s\n", dlerror());
        return NULL;
    }

    // Initialize the cipher structure with the loaded module's handles and functions
    Cipher* cipher = malloc(sizeof(Cipher));
    cipher->handle = lib_handle;

    // Get the encryption and decryption function pointers from the loaded module
    int (*encrypt_ptr)(const char*, size_t) = dlsym(lib_handle, "encrypt");
    int (*decrypt_ptr)(const char*, size_t) = dlsym(lib_handle, "decrypt");

    if (!encrypt_ptr || !decrypt_ptr) {
        fprintf(stderr, "Error getting function pointers: %s\n", dlerror());
        dlclose(lib_handle);
        free(cipher);
        return NULL;
    }

    cipher->encrypt = encrypt_ptr;
    cipher->decrypt = decrypt_ptr;

    return cipher;
}

// Perform encryption or decryption using the loaded cipher module
int perform_cipher_operation(Cipher* cipher, const char* input_string) {
    size_t input_len = strlen(input_string);

    if (cipher == NULL || input_string == NULL) {
        return -1; // Invalid input
    }

    // Use the cipher functions based on the operation type
    int result;
    if (strcmp(cipher->handle, "my_cipher_encrypt") == 0) {
        result = cipher->encrypt(input_string, input_len);
    } else if (strcmp(cipher->handle, "my_cipher_decrypt") == 0) {
        result = cipher->decrypt(input_string, input_len);
    } else {
        // Invalid cipher module
        fprintf(stderr, "Error: Unknown cipher module.\n");
        return -1;
    }

    return result;
}

// Free resources and close the cipher module handle when no longer needed
void free_cipher_module(Cipher* cipher) {
    if (cipher == NULL) {
        return; // Nothing to do
    }

    dlclose(cipher->handle);
    free(cipher);
}
