    // For example:
    FILE *log_file = fopen("semaphore_log.txt", "a+");
    if (log_file == NULL) {
        sem_destroy(sem);
        free(sem);
        return NULL;
    }

    // Return the created semaphore
    return sem;
}

void delete_semaphore(sem_t *sem) {
    sem_destroy(sem);
    free(sem);
}

// Example usage:
int main() {
    sem_t *sem = create_and_manage_semaphore(5);
    if (sem == NULL) {
        printf("Semaphore creation failed.\n");
        return 1;
    }

    // Use the semaphore here
    pthread_mutex_lock(&sem->mutex);
    int value = sem_getvalue(sem);
    pthread_mutex_unlock(&sem->mutex);

    delete_semaphore(sem);
    return 0;
}
