namespace NetworkMonitoring {
    class ConfigurationManager {
    public:
        ConfigurationManager() : configMap_(std::unordered_map<std::string, std::any>()) {}

        ~ConfigurationManager() = default;

        static void readConfigurationsFromFile(const std::string& filename) {
            std::ifstream file(filename);
            if (!file.is_open()) {
                throw std::runtime_error("Failed to open configuration file");
            }

            Json::Value jsonConfig;
            file >> jsonConfig;

            for (const auto& [key, value] : jsonConfig.getMemberNames()) {
                configMap_[key] = value.asString();
            }
        }

        template <typename T>
        void updateConfiguration(const std::string& key, const T& value) {
            static std::mutex lock;
            lock.lock();
            try {
                configMap_[key] = value;
            } catch (...) {
                // Handle exceptions safely
            } finally {
                lock.unlock();
            }
        }

    private:
        std::unordered_map<std::string, std::any> configMap_;
    };
}
