using System;
using System.Data;
using System.Data.SqlClient;
using System.Linq;

public class DbProcessor
{
    public IDataReader InsertData(List<MyObject> data, SqlConnection connection, string tableName)
    {
        // Generate the SQL query with parameterized values
        var sqlQuery = "INSERT INTO " + tableName + " (";
        foreach (var property in typeof(MyObject).GetProperties())
        {
            sqlQuery += property.Name + ", ";
        }
        sqlQuery = sqlQuery.TrimEnd(',', ' ') + ") VALUES (";
        foreach (var property in typeof(MyObject).GetProperties())
        {
            sqlQuery += "@" + property.Name + ", ";
        }
        sqlQuery = sqlQuery.TrimEnd(',', ' ') + ");";

        // Prepare the SQL command
        var sqlCommand = new SqlCommand(sqlQuery, connection);
        foreach (var property in typeof(MyObject).GetProperties())
        {
            sqlCommand.Parameters.AddWithValue("@$" + property.Name, data.Select(x => x.GetType().GetProperty(property.Name).GetValue(x)).Cast<object>().ToArray());
        }

        try
        {
            // Execute the SQL command and get the result set
            using var reader = sqlCommand.ExecuteReader();
            return reader;
        }
        catch (Exception ex)
        {
            // Handle potential exceptions gracefully
            Console.WriteLine("Error inserting data: " + ex.Message);
            return null;
        }
    }
}
