using System;
using System.IO;
using System.Xml.Linq;

public class XmlParser
{
    public static string ParseXmlAndCreateDir(string xmlPath, string elementName)
    {
        // Check if environment variable "XML_DIR" is set
        string xmlDir = Environment.GetEnvironmentVariable("XML_DIR");

        // If "XML_DIR" is not set, create a new directory and set the environment variable
        if (string.IsNullOrEmpty(xmlDir))
        {
            // Generate a unique directory name based on the current time
            string dirName = DateTime.Now.ToString("yyyy-MM-dd_HH-mm-ss");
            xmlDir = Path.Combine(Path.GetTempPath(), dirName);

            try
            {
                Directory.CreateDirectory(xmlDir);
            }
            catch (IOException ex)
            {
                throw new Exception($"Failed to create directory: {ex.Message}", ex);
            }

            Environment.SetEnvironmentVariable("XML_DIR", xmlDir);
        }

        // Parse the XML document using XPath
        XDocument doc = XDocument.Load(xmlPath);
        XElement root = doc.Root;

        if (root == null)
        {
            throw new Exception("No elements found in the XML document");
        }

        var elements = root.Elements(elementName);

        if (elements.Count() > 1)
        {
            throw new Exception($"Multiple elements with name '{elementName}' found");
        }
        else if (elements.Count() == 0)
        {
            // If no element is found, create an empty directory
            return xmlDir;
        }

        // Return the path of the directory
        return xmlDir;
    }
}
