['```java
import javax.xml.bind.DatatypeConverter;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.io.*;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public String hashString(String input) {
    if (input == null || input.isEmpty()) {
        return null;
    }

    try {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] bytes = input.getBytes("UTF-8");
        byte[] hashBytes = md.digest(bytes);

        StringBuilder sb = new StringBuilder();
        for (byte b : hashBytes) {
            String hex = Integer.toHexString(b & 0xff);
            if (hex.length() == 1) {
                sb.append('0');
            }
            sb.append(hex);
        }

        return sb.toString();
    } catch (NoSuchAlgorithmException e) {
        Logger logger = LoggerFactory.getLogger("hashString");
        logger.error("Error during MD5 hash calculation: ", e);
    } catch (IOException e) {
        Logger logger = LoggerFactory.getLogger("hashString");
        logger.error("Error converting string to UTF-8: ", e);

        // Write error message to file
        try (FileWriter fw = new FileWriter(new File("hash_errors.log"), true)) {
            fw.write(e.getMessage() + "\n");
        } catch (IOException ex) {
            Logger logger1 = LoggerFactory.getLogger("hashString");
            logger1.error("Error writing error message to file: ", ex);
        }

        return null;
    }
}
