public class MoSTStateLoader {
    public static MoSTState loadMoSTState(String filePath) {
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(filePath))) {
            Object obj = ois.readObject();
            if (obj instanceof MoSTState) {
                MoSTState state = (MoSTState) obj;
                // Manage theme caching
                recycleBitmaps(state.getThemeBitmaps());
                setDefaultThemeDirectory(state);
                parsePNGFileAndCache(state);
                return state;
            } else {
                return null;
            }
        } catch (IOException | ClassNotFoundException e) {
            // Handle file reading exceptions and corrupted data
            System.err.println("Error loading MoSTState: " + e.getMessage());
            return null;
        } finally {
            try {
                ois.close();
            } catch (IOException ignored) {}
        }
    }

    private static void recycleBitmaps(ThemeBitmap[] themeBitmaps) {
        for (ThemeBitmap bitmap : themeBitmaps) {
            if (!bitmap.isRecycled()) {
                bitmap.recycle();
                bitmap = null;
            }
        }
    }

    private static void setDefaultThemeDirectory(MoSTState state) {
        // Set default theme directory based on deployment environment
        String defaultDir = System.getProperty("theme.cache.dir");
        if (defaultDir == null) {
