            {
                options.Password.RequireDigit = true;
                options.Password.RequireLowercase = true;
                options.Password.RequireNonAlphanumeric = true;
                options.Password.RequireUppercase = true;
                options.Password.RequireUniqueChar = true;
                options.Password.Length = 10;

                // Password History
                options.Password.SaveFailedLoginAttempts = true;
                options.Password.HistoryLength = 5;
                options.Password.HistoryExpireDays = 30;

                // User Lockout Management
                options.Lockout.MaxAttempts = 3;
                options.Lockout.DefaultLockoutTimeSpan = TimeSpan.FromMinutes(10);

                services.AddRoleManager();
            })
            .AddEntityFrameworkDbContext<MyAppContext>();
        }

        public void Configure(MyAppOptions appSettings, IWebHostEnvironment env)
