function runTests(label, f, timeout) {
  const { require } = global;
  const blueslip = require('blueslip');

  function test(name, fn) {
    console.log(`Testing ${name}...`);

    return new Promise((resolve, reject) => {
      let startTime;

      setTimeout(() => {
        startTime = Date.now();

        try {
          fn(blueslip);

          const endTime = Date.now();
          const duration = endTime - startTime;

          console.log(`Test ${name} passed in ${duration}ms`);
          resolve();
        } catch (error) {
          const endTime = Date.now();
          const duration = endTime - startTime;
          const errorMessage = `Test ${name} failed: ${error.message}`;

          console.error(errorMessage);
          reject(error);
        } finally {
          if (blueslip) blueslip.reset();
        }

        setTimeout(() => {
          if (Date.now() - startTime > timeout) {
            throw new Error(`Timeout exceeded for test ${name}`);
          }
        }, timeout);
      });
    }).catch((error) => {
      console.error(error);
      process.exit(1);
    });
  }

  require(label, (module) => {
    try {
      module = require(module);

      Object.keys(module).forEach((testName) => {
        test(testName, module[testName]);
      });
    } catch (error) {
      console.error(`Error loading module ${label}: ${error.message}`);
      process.exit(1);
    }
  });
}
