const programmingLanguages = new Map();

function extractProgrammingLanguages(text) {
  const languageList = ['java', 'python', 'csharp', 'kotlin', 'swift', 'ruby', 'php', 'javascript', 'typescript', 'go', 'rust'];

  text.toLowerCase()
    .replace(/[^\w\s]/g, '') // remove punctuation and special characters
    .split(/\b(?!\bjava\b|...)\b\w+\b/g) // split by word boundaries
    .filter(word => languageList.includes(word)) // filter out non-programming languages
    .forEach(language => {
      if (programmingLanguages.has(language)) {
        programmingLanguages.set(language, programmingLanguages.get(language) + 1);
      } else {
        programmingLanguages.set(language, 1);
      }
    });

  return Array.from(programmingLanguages.entries());
}
