function renderFooterScripts(scripts) {
  const footer = document.getElementById('footer');
  if (!footer) return;

  scripts.forEach((script, index) => {
    const scriptTag = document.createElement('script');
    scriptTag.src = script.url;
    scriptTag.onload = () => {
      try {
        // Execute the script and capture any potential errors
        (function() { eval(script.content); })();
      } catch (error) {
        console.error(`Script ${script.name} failed to execute:`, error);
      }
    };
    footer.appendChild(scriptTag);

    if (script.dependencies && Array.isArray(script.dependencies)) {
      // Load dependent scripts in the correct order
      script.dependencies.forEach((dep) => {
        const depScript = scripts.find((s) => s.name === dep);
        if (depScript) {
          renderFooterScripts([depScript]);
        }
      });
    }
  });

  // Cache external script content to minimize network requests
  Object.keys(scripts).forEach((scriptName) => {
    const cachedContent = localStorage.getItem(scriptName);
    if (cachedContent) {
      scripts[scriptName].content = cachedContent;
    }
  });
}
