    private final int PAUSE_DURATION_MILLISECONDS = 1000;

    public void startService() throws InterruptedException, IOException {
        Random random = new Random();
        while (true) {
            // Simulate data collection from real-time sensor stream
            double newDataPoint = Math.random() * 100.0;
            sensorDataBuffer.add(newDataPoint);

            if (!isPaused) {
                // Send data to external messaging system
                try {
                    Socket socket = new Socket("messaging-system-host", 8080);
                    java.io.DataOutputStream dos = new DataOutputStream(socket.getOutputStream());
                    dos.writeDouble(newDataPoint);
                    socket.close();
                } catch (IOException e) {
                    System.out.println("Failed to send data: " + e.getMessage());
                }
            }

            // Pause and resume service randomly
            if (!isPaused && random.nextInt(10) < 3) {
                isPaused = true;
                Thread.sleep(PAUSE_DURATION_MILLISECONDS);
                isPaused = false;
            }

            Thread.sleep(random.nextInt(500)); // Simulate variable loads
        }
    }

    public void pauseService() {
        isPaused = true;
    }

    public void resumeService() {
        isPaused = false;
    }
