function concatBuffers(bufferArray, targetBytes) {
  let result = Buffer.alloc(0);
  let remainingBytes = targetBytes;

  for (const buffer of bufferArray) {
    const length = buffer.length;
    if (length <= remainingBytes) {
      result = Buffer.concat([result, buffer.slice(0, length)]);
      remainingBytes -= length;
    } else {
      result = Buffer.concat([result, buffer.slice(0, remainingBytes)]);
      break;
    }
  }

  return remainingBytes >= targetBytes ? result : [Buffer.alloc(0), `Insufficient data. Required: ${targetBytes}, Available: ${remainingBytes}`];
}
