function traverseDOM(selector, testFunction) {
  const cache = {};

  function recursiveTraversal(element) {
    if (!element) return [];

    const cachedMatchedElements = cache[selector];
    if (cachedMatchedElements) return cachedMatchedElements;

    let matchedElements = [];

    // Traverse the element's children
    for (let child of element.children) {
      const result = recursiveTraversal(child);

      // Filter and test elements based on the provided selector and function
      for (let el of result) {
        if (testFunction(el)) matchedElements.push(el);
      }
    }

    // Add the current element to the cache
    cache[selector] = matchedElements;

    return matchedElements;
  }

  return recursiveTraversal(document.body);
}
