**JavaScript Program for Dynamically Loading and Executing JavaScript Files**

```javascript
// Load files in order of priority (higher number means higher priority)
const filePriorities = {
  'lib1.js': 3,
  'lib2.js': 2,
  'lib3.js': 1
};

// Function to load and execute JavaScript files
function loadAndExecuteFiles(files, callback) {
  const promises = [];

  for (const file of Object.keys(filePriorities)) {
    const promise = new Promise((resolve, reject) => {
      // Load the file
      const script = document.createElement('script');
      script.src = file;
      document.head.appendChild(script);

      // Wait for the file to load and execute
      setTimeout(() => {
        resolve();
      }, 2000); // adjust this time as needed
    });

    promises.push(promise);
  }

  Promise.all(promises).then(() => {
    callback(); // call the callback when all files have been loaded and executed
  }).catch((error) => {
    console.error('Error loading or executing files:', error);
  });
}

// Example usage:
loadAndExecuteFiles(['lib1.js', 'lib2.js'], () => {
  console.log('All files loaded and executed!');
});
