#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void modifyFileExtension(char* filename, int numDigits) {
    // Calculate the number of digits needed
    int length = strlen(filename);
    int newLength = length + (int)log10((double)numDigits) + 4; // add 4 for .xyz extension

    // Allocate memory for the new filename
    char* newFilename = malloc(newLength + 1);

    // Copy the original filename
    strcpy(newFilename, filename);

    // Add the number of digits to the end
    sprintf(&newFilename[length], "%0*d", numDigits, 0); // adjust this format as needed

    // Add the file type (e.g., .xyz)
    strcat(newFilename, ".xyz");

    printf("Modified filename: %s\n", newFilename);
}
