import java.util.*;

public class UniquePairs {
    public static long countUniquePairs(List<String> strings) {
        Map<String, Set<Character>> stringToChars = new HashMap<>();

        for (String s : strings) {
            Set<Character> chars = new HashSet<>();
            for (char c : s.toCharArray()) {
                chars.add(c);
            }
            stringToChars.put(s, chars);
        }

        long count = 0;
        long startTime;

        for (int i = 0; i < strings.size(); i++) {
            String s1 = strings.get(i);
            Set<Character> set1 = stringToChars.get(s1);

            for (int j = i + 1; j < strings.size(); j++) {
                String s2 = strings.get(j);
                Set<Character> set2 = stringToCharts.get(s2);

                startTime = System.currentTimeMillis();
                if (!set1.retainAll(set2)) {
                    count++;
                }
                System.out.println((System.currentTimeMillis() - startTime) + " milliseconds");
            }
        }

        return count;
    }
}
