package com.example.theme.cacher;

import android.graphics.Bitmap;
import android.os.Looper;
import android.util.Log;

import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.lang.ref.WeakReference;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.RejectedExecutionHandler;
import java.util.concurrent.ThreadPoolExecutor;

public class ThemeCacher {
    private static final String TAG = "ThemeCacher";
    private Map<String, WeakReference<Bitmap>> themeCacheMap = new HashMap<>();
    private ThreadPoolExecutor executor;
    private int maxOpenFileDescriptors;
    private long cacheExpirationTimeMs;
    private File cacheRootDir;

    public ThemeCacher(File cacheRootDir, int maxOpenFileDescriptors, long cacheExpirationTimeMs) {
        this.cacheRootDir = cacheRootDir;
        this.maxOpenFileDescriptors = maxOpenFileDescriptors;
        this.cacheExpirationTimeMs = cacheExpirationTimeMs;
        this.executor = new ThreadPoolExecutor(
                5, // Initial pool size
                10, // Maximum pool size
                1, TimeUnit.SECONDS,
                new LinkedBlockingQueue<Runnable>(),
                new RejectedExecutionHandler() {
                    @Override
                    public void rejectedExecution(Runnable r, ThreadPoolExecutor executor) {
                        Looper.prepare();
                        Log.w(TAG, "Rejected execution: " + r);
                        Looper.loop();
                    }
                });
    }

    public Bitmap getTheme(String themeName) throws IOException {
        WeakReference<Bitmap> bitmapRef = themeCacheMap.get(themeName);
        if (bitmapRef != null && bitmapRef.get() != null) {
            return bitmapRef.get();
        } else {
            File themeFile = new File(cacheRootDir, themeName + ".png");
            Bitmap bitmap = parsePNG(themeFile);
            if (bitmap != null) {
                themeCacheMap.put(themeName, new WeakReference<>(bitmap));
                executor.execute(() -> {
                    try {
                        Thread.sleep(cacheExpirationTimeMs);
                        recycleBitmap(bitmap);
                    } catch (InterruptedException e) {
                        Log.e(TAG, "Error recycling bitmap", e);
                    }
                });
            }
            return bitmap;
        }
    }

    private Bitmap parsePNG(File file) throws IOException {
        // Your PNG parsing logic goes here
    }

    private void recycleBitmap(Bitmap bitmap) {
        if (bitmap != null && !bitmap.isRecycled()) {
            bitmap.recycle();
            bitmap = null;
        }
    }

    public void cleanUpCache() {
        executor.execute(() -> {
            try {
                File[] files = cacheRootDir.listFiles();
                for (File file : files) {
                    if (!file.getName().endsWith(".png")) continue;
                    long lastModified = file.lastModified();
                    if (System.currentTimeMillis() - lastModified > cacheExpirationTimeMs) {
                        file.delete();
                    }
                }
            } catch (IOException e) {
                Log.e(TAG, "Error cleaning up cache", e);
            }
        });
    }
}
