use reqwest::blocking::{get, put};
use std::time::Duration;
use std::thread::sleep;

pub struct HttpClient {
    client: reqwest::blocking::Client,
    max_retries: usize,
    retry_delay: u64,
}

impl HttpClient {
    pub fn new(max_retries: usize, retry_delay: u64) -> Self {
        let client = reqwest::blocking::Client::builder()
            .timeout(Duration::from_secs(10))
            .build().unwrap();

        Self { client, max_retries, retry_delay }
    }

    pub async fn get(&self, url: &str, disable_cert_validation: bool) -> Result<reqwest::BlockingResponse, reqwest::Error> {
        let mut builder = self.client.get(url).timeout(Duration::from_secs(10));
        if disable_cert_validation {
            builder = builder.ignore_ssl_errors(true);
        }

        loop {
            match builder.send().await {
                Ok(response) => return Ok(response),
                Err(err) => {
                    if err.is_timeout() || err.is_connect_failure() {
                        sleep(Duration::from_millis(self.retry_delay));
                        self.retry_delay *= 2;
                    } else {
                        return Err(err);
                    }
                }
            }

            if self.max_retries == 0 {
                return Err(reqwest::Error::Timeout("Max retries reached".to_string()));
            }
        }
    }

    pub async fn put(&self, url: &str, disable_cert_validation: bool) -> Result<reqwest::BlockingResponse, reqwest::Error> {
        let mut builder = self.client.put(url).timeout(Duration::from_secs(10));
        if disable_cert_validation {
            builder = builder.ignore_ssl_errors(true);
        }

        loop {
            match builder.send().await {
                Ok(response) => return Ok(response),
                Err(err) => {
                    if err.is_timeout() || err.is_connect_failure() {
                        sleep(Duration::from_millis(self.retry_delay));
                        self.retry_delay *= 2;
                    } else {
                        return Err(err);
                    }
                }
            }

            if self.max_retries == 0 {
                return Err(reqwest::Error::Timeout("Max retries reached".to_string()));
            }
        }
    }
}
