    while (retry_count < OAUTH_AUTHENTICATION_RETRY) {
        struct oauth2_token* token = oauth2_login(client_id, client_secret);
        if (token != NULL) {
            session_data* new_session = (session_data*)malloc(sizeof(session_data));
