StateNode** createStateList(int* states, int numStates, FSA* fsa, int lastState) {
    // Allocate memory for the state list
    StateNode** stateList = (StateNode**)malloc((numStates + 1) * sizeof(StateNode*));
    if (stateList == NULL) return NULL;

    // Initialize the state list with NULL pointers
    for (int i = 0; i <= lastState; i++) {
        stateList[i] = NULL;
    }

    // Create and initialize each state node
    for (int i = 0; i < numStates; i++) {
        StateNode* state = (StateNode*)malloc(sizeof(StateNode));
        if (state == NULL) return NULL;

        state->id = states[i];
        state->metadata = 0;

        // Update the 'next' pointer of the last state in the list
        if (i < lastState) {
            stateList[lastState]->next = state;
        } else {
            stateList[lastState] = state;
        }
    }

    return stateList;
}
