using System;

namespace RandomValueGenerator
{
    public class RandomValueGenerator
    {
        private float _min;
        private float _max;

        public RandomValueGenerator(float min, float max)
        {
            ValidateRange(min, max);
            _min = Math.Min(min, max);
            _max = Math.Max(min, max);
        }

        public float GetRandomFloat()
        {
            return (float)System.Threading.ThreadLocal.Random.NextDouble() * (_max - _min) + _min;
        }

        public int GetRandomInt()
        {
            return (int)(GetRandomFloat());
        }

        private void ValidateRange(float min, float max)
        {
            if (min > max)
            {
                float temp = min;
                min = max;
                max = temp;
            }
        }

        public float GetRandomFloatWithDistribution(float probability)
        {
            if (probability < 0 || probability > 1)
            {
                throw new ArgumentOutOfRangeException("Probability value must be between 0 and 1.");
            }
            return (float)System.Threading.ThreadLocal.Random.NextDouble() * (_max - _min) + _min;
        }
    }
}
