["```
function asyncReduce(arr, initial, callback) {
  if (!Array.isArray(arr)) throw new Error('Invalid input: Array expected');

  const queue = [];
  let result;
  let error;

  function worker(index) {
    return new Promise((resolve, reject) => {
      if (index >= arr.length) {
        resolve();
        return;
      }

      try {
        const value = callback(result || initial, arr[index]);
        if (value instanceof Promise) {
          value.then(nextValue => {
            result = nextValue;
            worker(index + 1);
          }).catch(reject);
        } else {
          result = value;
          worker(index + 1);
        }
      } catch (err) {
        reject(err);
      }
    });
  }

  function nextValue() {
    if (!error && !queue.length) return result;

    if (error) throw error;

    const nextIndex = queue.shift();
    worker(nextIndex).then(() => {
      if (!queue.length) return result;
      setTimeout(nextValue, 0);
    }).catch(err => {
      error = err;
      if (!queue.length) throw error;
      setTimeout(nextValue, 0);
    });
  }

  nextValue();

  return new Promise((resolve, reject) => {
    resolve(result);
  });
}
```"]

