typedef struct {
    char key[32];
    int value;
} KeyValuePair;

typedef struct {
    int count;
    int sum;
    KeyValuePair pair[MAX_KEY_VALUE_PAIRS];
} Section;

void process_section(FILE *file, Section *section) {
    char line[1024];
    int i = 0;

    while (fgets(line, sizeof(line), file)) {
        if (sscanf(line, "= %s %d", section->pair[i].key, &section->pair[i].value) == 2) {
            section->count++;
            section->sum += section->pair[i].value;
            i++;
            if (i >= MAX_KEY_VALUE_PAIRS) {
                break;
            }
        } else if (sscanf(line, "= %s", section->pair[i].key) == 1) {
            break;
        } else {
            printf("Invalid line: %s\n", line);
        }
    }

    if (i > 0 && i < MAX_KEY_VALUE_PAIRS) {
        section->pair[i].value = (section->sum / i) + (section->count % 2 ? section->pair[(i - 1) % i].value : 0);
    }
}

void free_section(Section *section) {
    for (int i = 0; i < MAX_KEY_VALUE_PAIRS; i++) {
