['Here is the C function that parses a TIFF image file and extracts information about the image's bits per sample and sample per pixel:

```c
#include <stdio.h>
#include <string.h>
#include <tiffio.h>

typedef struct {
    uint16_t bits_per_sample;
    uint16_t samples_per_pixel;
    int extra_samples_count;
    uint16_t* extra_samples;
} TIFF_Info;

TIFF_Info parse_tiff_file(const char *filename) {
    TIFF_Info info = {0};

    // Open the TIFF file
    TIFF *tif = TIFFOpen(filename, "r");

    if (tif == NULL) {
        return (TIFF_Info){.bits_per_sample = 0, .samples_per_pixel = 0, .extra_samples_count = 0, .extra_samples = NULL};
    }

    // Get the bits per sample
    uint16_t bits_per_sample;
    TIFFGetField(tif, TIFF_FIELD_IMAGE_BITSPERSAMPLE, &bits_per_sample);

    if (bits_per_sample != 1 && bits_per_sample != 2 && bits_per_sample != 4 && bits_per_sample != 8 && bits_per_sample != 16) {
        // Return an error message
        return (TIFF_Info){.bits_per_sample = 0, .samples_per_pixel = 0, .extra_samples_count = 0, .extra_samples = NULL};
    }

    info.bits_per_sample = bits_per_sample;

    // Get the samples per pixel
    uint16_t samples_per_pixel;
    TIFFGetField(tif, TIFF_FIELD_IMAGE_SAMPLESPERPIXEL, &samples_per_pixel);
    info.samples_per_pixel = samples_per_pixel;

    // Get the extra samples (if any)
    if (TIFFGetFieldCount(tif) > 2) {
        int extra_samples_count = TIFFGetFieldCount(tif) - 2;
        uint16_t* extra_samples = (uint16_t*)malloc(extra_samples_count * sizeof(uint16_t));

        for (int i = 0; i < extra_samples_count; i++) {
            TIFFGetField(tif, i + 2, &extra_samples[i]);
        }

        info.extra_samples_count = extra_samples_count;
        info.extra_samples = extra_samples;
    } else {
        info.extra_samples_count = 0;
        info.extra_samples = NULL;
    }

    // Close the TIFF file
    TIFFClose(tif);

    return info;
}

// Example usage:
int main() {
    const char *filename = "example.tiff";
    TIFF_Info info = parse_tiff_file(filename);

    if (info.bits_per_sample == 0) {
        printf("Error: Bits per sample not supported.\n");
    } else {
        printf("Bits per sample: %u\n", info.bits_per_sample);
        printf("Samples per pixel: %u\n", info.samples_per_pixel);

        if (info.extra_samples_count > 0) {
            printf("Extra samples count: %d\n", info.extra_samples_count);

            for (int i = 0; i < info.extra_samples_count; i++) {
                printf("Extra sample %d: %u\n", i, info.extra_samples[i]);
            }
        }
    }

    return 0;
}
```']

