#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/wait.h>

#define MAX_CMDS 10
#define MAX_CMD_LENGTH 1024

int run_commands(char *cmds[], int num_cmds) {
    int status;
    pid_t pids[MAX_CMDS];
    int i, j;

    for (i = 0; i < num_cmds; i++) {
        if (fork() == 0) {
            // Child process
            signal(SIGINT, SIG_IGN);
            signal(SIGTERM, SIG_IGN);

            // Run the command
            system(cmds[i]);

            // Exit the child process
            exit(0);
        } else {
            pids[i] = i;
        }
    }

    for (i = 0; i < num_cmds; i++) {
        waitpid(pids[i], &status, 0);
    }

    if (num_cmds > 0 && WEXITSTATUS(status) != 0) {
        return 0;
    } else {
        return 1;
    }
}
