using System.Threading.Tasks;

public class WebsiteManager
{
    private readonly object _lock = new object();
    private readonly string _logFilePath;

    public WebsiteManager(string logFilePath)
    {
        _logFilePath = logFilePath;
    }

    public Task<Process> AddAndStartSiteAsync(string directoryPath, string siteName, string configFilePath)
    {
        if (!Directory.Exists(directoryPath))
            return null;

        lock (_lock)
        {
            if (!File.Exists(configFilePath))
                return null;

            var process = new Process
            {
                StartInfo = new ProcessStartInfo
                {
                    FileName = "dotnet",
                    Arguments = $"run --site-name {siteName} --config-file-path {configFilePath}",
                    WorkingDirectory = directoryPath,
                    RedirectStandardError = true,
                    RedirectStandardOutput = true,
                    UseShellExecute = false,
                    CreateNoWindow = true
                }
            };

            process.Start();

            return Task.FromResult(process);
        }
    }

    private void LogOperation(string operation, string siteName)
    {
        using (var logger = File.AppendText(_logFilePath))
        {
            logger.WriteLine($"{DateTime.Now} - {operation} website {siteName}");
        }
    }
}
