public class SSHExecutor {

    private static final int BUFFER_SIZE = 1024;
    private static final long TIMEOUT_MILLISECONDS = 30000;

    public void executeCommand(String hostname, int port, String username, String password, String command) throws IOException {
        // Set up the SSH connection
        com.jcraft.jsch.Session session = startSSHConnection(hostname, port, username, password);

        try (BufferedReader reader = new BufferedReader(new InputStreamReader(session.exec(command))) {
            long startTime = System.currentTimeMillis();

            StringBuilder output = new StringBuilder();
            String line;

            while ((line = reader.readLine()) != null) {
                if (line.length() > BUFFER_SIZE) {
                    // Handle large volumes of data efficiently
                    processLargeOutput(line);
                } else {
                    output.append(line).append('\n');
                }
            }

            long endTime = System.currentTimeMillis();
            long executionTime = endTime - startTime;

            System.out.println("Execution time: " + TimeUnit.MILLISECONDS.toSeconds(executionTime) + " seconds");

            // Check if the file exists and delete it
            String filename = command.split(" ")[3];
            if (deleteFileIfExists(filename)) {
                System.out.println("File deleted successfully");
            } else {
                System.out.println("Error deleting file");
            }
        } catch (IOException e) {
            long endTime = System.currentTimeMillis();
            long executionTime = endTime - startTime;

            System.out.println("Error executing command: " + e.getMessage());
            System.out.println("Execution time: " + TimeUnit.MILLISECONDS.toSeconds(executionTime) + " seconds");

            // Handle errors and exceptions securely
            if (e instanceof com.jcraft.jsch.SshException || e instanceof IOException) {
                try {
                    session.disconnect();
                } catch (IOException ignored) {}
            }
        } finally {
            // Close the SSH connection
            session.disconnect();
        }
    }

    private com.jcraft.jsch.Session startSSHConnection(String hostname, int port, String username, String password) throws IOException {
        // Set up the JSch library for SSH connections
        com.jcraft.jsch.Session session = new com.jcraft.jsch.Session();

        session.setConfig("StrictHostKeyChecking", "no");
        session.setConfig("PreferredAuthentications", "publickey,password");

        session.connect(hostname, port, username, password);

        return session;
    }

    private void processLargeOutput(String line) {
        // Implement the logic to handle large volumes of data efficiently
    }

    private boolean deleteFileIfExists(String filename) throws IOException {
        // Implement the logic to check if a file exists and delete it
    }
}
