int verify_oauth2_access_token(const char *json_string) {
    json_object *token_obj = json_object_from_json_string(json_string);

    if (!token_obj) {
        return 0; // JSON parsing error, token is not valid
    }

    if (!json_object_object_test_exists(token_obj, "access_token") ||
        !json_object_object_test_exists(token_obj, "expires_in") ||
        !json_object_object_test_exists(token_obj, "token_type")) {
        json_object_put(token_obj);
        return 0; // Missing required fields, token is not valid
    }

    const char *access_token = json_object_get_string(token_obj, "access_token");
    int expires_in = json_object_get_int(token_obj, "expires_in");
    const char *token_type = json_object_get_string(token_obj, "token_type");

    if (strlen(access_token) > MAX_TOKEN_LENGTH || strlen(token_type) > 8) {
        json_object_put(token_obj);
        return 0; // Invalid field values, token is not valid
    }

    if (strcmp(token_type, "Bearer") != 0) {
        json_object_put(token_obj);
        return 0; // Invalid token type, token is not valid
    }

    int now = time(NULL);
    if (expires_in <= 0 || now > expires_in) {
        json_object_put(token_obj);
        return 0; // Expired or invalid expiration value, token is not valid
    }

    const char *refresh_token = json_object_get_string(token_obj, "refresh_token");
    if (strlen(refresh_token) > MAX_REFRESH_TOKEN_LENGTH) {
        json_object_put(token_obj);
        return 0; // Invalid refresh token length, token is not valid
    }

    json_object_put(token_obj);
    return 1; // Token is valid
}
