// Define the structure for a state node
typedef struct StateNode {
    int id;
    int* transition_labels;
    int enabled_transitions;
} StateNode;

// Define the function to dynamically create and manage states in an FSA
StateNode** CreateStates(int* states, int num_states, void* fsa, int last_state) {
    // Allocate memory for the state list
    StateNode** state_list = (StateNode**)malloc((num_states + 1) * sizeof(StateNode*));

    // Initialize each state node
    for (int i = 0; i <= last_state; i++) {
        state_list[i] = (StateNode*)malloc(sizeof(StateNode));
        state_list[i]->id = states[i];
        state_list[i]->transition_labels = (int*)malloc(sizeof(int) * 4); // Assume each state has at most 4 transitions
        state_list[i]->enabled_transitions = 0;
    }

    return state_list;
}

// Define the function to free the memory allocated for the state list
void FreeStates(StateNode** state_list, int num_states) {
    // Free each state node
    for (int i = 0; i <= num_states; i++) {
        if (state_list[i]->transition_labels)
            free(state_list[i]->transition_labels);
        free(state_list[i]);
    }

    // Free the state list itself
    free(state_list);
}
