using System;
using System.Security.Cryptography;
using System.Text;

public class EncryptionHandler
{
    public string DecryptMessage(string base64EncodedMessage, string key, string iv, int minLength = 10, int maxLength = 1000)
    {
        try
        {
            // Validate Base64 encoding
            if (!IsValidBase64(base64EncodedMessage))
                return string.Empty;

            // Decode the Base64 message
            byte[] base64DecodedBytes = Convert.FromBase64String(base64EncodedMessage);

            // Validate decrypted message length
            int decryptedLength = TripleDesDecrypt(base64DecodedBytes, key, iv).Length;
            if (decryptedLength < minLength || decryptedLength > maxLength)
                return string.Empty;

            // Return the decrypted message as a string
            return Encoding.UTF8.GetString(TripleDesDecrypt(base64DecodedBytes, key, iv));
        }
        catch (Exception ex)
        {
            // Log any errors and return an empty string
            System.Diagnostics.Debug.WriteLine(ex.Message);
            return string.Empty;
        }
    }

    private byte[] TripleDesDecrypt(byte[] base64DecodedBytes, string key, string iv)
    {
        using (TripleDESCryptoServiceProvider tripleDes = new TripleDESCryptoServiceProvider())
        {
            tripleDes.Key = Convert.FromBase64String(key);
            tripleDes.IV = Convert.FromBase64String(iv);

            using (MemoryStream memoryStream = new MemoryStream(base64DecodedBytes))
            {
                using (CryptoStream cryptoStream = new CryptoStream(memoryStream, tripleDes.CreateDecryptor(), CryptoStreamMode.Write))
                {
                    byte[] buffer = new byte[4096];
                    int read;
                    while ((read = cryptoStream.Read(buffer, 0, buffer.Length)) > 0)
                        memoryStream.WriteByte((byte)read);
                }
            }

            return memoryStream.ToArray();
        }
    }

    private bool IsValidBase64(string base64EncodedMessage)
    {
        try
        {
            Convert.FromBase64String(base64EncodedMessage);
            return true;
        }
        catch (FormatException)
        {
            return false;
        }
    }
}
