    public Dictionary<string, int> GetHttpStatusCodeList(List<string> urls)
    {
        var httpClient = new HttpClient();
        var responseDict = new Dictionary<string, int>();

        foreach (var url in urls)
        {
            _ = Task.Run(() =>
            {
                try
                {
                    HttpResponseMessage response = httpclient.GetAsync(url).Result;
                    responseDict.Add(url, (int)response.StatusCode);
                }
                catch (HttpRequestException e)
                {
                    Console.WriteLine("Error with {0}: {1}", url, e.Message);
                }
                catch (TaskCanceledException e)
                {
                    Console.WriteLine("Request timed out for {0}", url);
                }
            });
        }

        return responseDict;
    }
}
