    public byte[] Decrypt(byte[] ciphertext, byte[] encryptionKey, byte[] iv, byte[] hmacSignature)
    {
        using (var aes = Aes.Create())
        {
            aes.Key = encryptionKey;
            aes.IV = iv;

            using (var decryptor = aes.CreateDecryptor())
            {
                using (var memoryStream = new MemoryStream(ciphertext))
                {
                    using (var cryptoStream = new CryptoStream(memoryStream, decryptor, CryptoStreamMode.Read))
                    {
                        var buffer = new byte[1024];
                        int bytesRead;
                        Array.Clear(memBuffer, 0, memBuffer.Length);

                        do
                        {
                            bytesRead = cryptoStream.Read(buffer, 0, buffer.Length);
                            buffer.CopyTo(memBuffer, memBuffer.Length - bytesRead);
                        } while (bytesRead > 0);

                        return memBuffer.ToArray();
                    }
                }
            }
        }
    }
}
