function buildAndTestProject(projectDirPath, envConfig) {
  const os = require('os');
  const fs = require('fs');
  const path = require('path');

  // Detect operating system
  let shellCmd;
  if (os.platform() === 'linux' || os.platform() === 'darwin') {
    shellCmd = 'bash';
  } else if (os.platform() === 'win32') {
    shellCmd = 'cmd.exe';
  }

  // Set cache directory based on environment configuration
  const cacheDir = envConfig.cacheDir || './.cache';

  try {
    // Check for existing build artifacts in the cache
    if (fs.existsSync(cacheDir)) {
      const cacheTimestamps = fs.readdirSync(cacheDir).map((file) => +path.basename(file, '.json'));
      const latestCacheTimestamp = Math.max(...cacheTimestamps);

      // Fetch updated dependencies and check for changed files
      const deps = require('./dependencies.json');
      const changedFiles = [];
      Object.keys(deps).forEach((dep) => {
        if (fs.existsSync(path.join(projectDirPath, dep))) {
          const fileStat = fs.statSync(path.join(projectDirPath, dep));
          if (fileStat.mtime > cacheTimestamps[0]) {
            changedFiles.push(dep);
          }
        }
      });

      // Execute build and test commands
      if (changedFiles.length) {
        shellCmd +=' /c "npm run build" && npm run test';
      } else {
        console.log('Using cached build artifacts...');
        shellCmd += ' & echo "Build successful!" | tee output.txt';
      }

      fs.writeFileSync(path.join(cacheDir, `timestamp.json`), JSON.stringify({ timestamp: latestCacheTimestamp }));
    } else {
      // No cache found; perform full build and test
      console.log('No cache found; performing full build...');
      shellCmd += ' & echo "Build successful!" | tee output.txt';
    }

    // Execute shell command with caching enabled
    const { stdout } = require('child_process').execSync(shellCmd, {
      encoding: 'utf8',
      env: Object.assign({}, process.env, {
        BUILD_CACHE_DIR: cacheDir,
        PROJECT_DIR_PATH: projectDirPath,
      }),
    });

    console.log(stdout);
  } catch (error) {
    console.error(error);
  }
}
