use std::path::Path;

fn set_directory_variable(dir_path: &str) -> bool {
    let env_var_name = "MY_DIR";
    let env_var_value = dir_path.to_string();

    if let Ok(_) = env::set_var(env_var_name, env_var_value) {
        info!("Environment variable {} set to {}", env_var_name, env_var_value);
        true
    } else {
        error!("Failed to set environment variable {} to {}", env_var_name, env_var_value);
        false
    }
}

fn create_directory(dir_path: &str) -> bool {
    if !Path::new(dir_path).exists() {
        match fs::create_dir_all(dir_path) {
            Ok(_) => {
                info!("Directory {} created", dir_path);
                true
            },
            Err(e) => {
                error!("Failed to create directory {}: {}", dir_path, e);
                false
            }
        }
    } else {
        info!("Directory {} already exists", dir_path);
        true
    }
}

fn get_default_dir_path() -> String {
    // implement logic to retrieve default path from external configuration file or database
    // for simplicity, just return a hardcoded value
    "default_directory".to_string()
}

pub fn set_my_dir() -> bool {
    let default_dir = get_default_dir_path();
    if env::var("MY_DIR").is_err() || env::var("MY_DIR").unwrap().is_empty() {
        if create_directory(&default_dir) && set_directory_variable(&default_dir) {
            true
        } else {
            false
        }
    } else {
        let existing_dir = env::var("MY_DIR").unwrap();
        if Path::new(&existing_dir).exists() {
            info!("Using existing directory {}", &existing_dir);
            set_directory_variable(&existing_dir)
        } else {
            error!("Environment variable MY_DIR is set but directory does not exist");
            false
        }
    }
}
