import json
import threading

class JSONParser:
    _registry = {}
    _mutex = threading.Lock()

    def __init__(self):
        self._factories = {}

    @classmethod
    def get_instance(cls, obj):
        if isinstance(obj, dict):
            return cls.from_json(obj)
        elif hasattr(obj, '__dict__'):
            return cls.to_json(obj)

    @classmethod
    def from_json(cls, data):
        instance = None
        for k, v in data.items():
            if k == 'type':
                if v not in cls._factories:
                    with cls._mutex:
                        if v not in cls._factories:
                            cls._factories[v] = {}
                factory = cls._factories.get(v)
                if factory:
                    instance = factory.pop(0, None)
                    break
        return instance

    @classmethod
    def to_json(cls, obj):
        instance = json.dumps(obj.__dict__)
        return instance

    @classmethod
    def add_factory(cls, id, factory):
        with cls._mutex:
            if id not in cls._factories:
                cls._factories[id] = []
            cls._factories[id].append(factory)

    @classmethod
    def remove_factory(cls, id):
        with cls._mutex:
            if id in cls._factories:
                del cls._factories[id]

    @classmethod
    def has_factory(cls, id):
        return id in cls._factories

# Example usage:

class Person:
    def __init__(self, name, age):
        self.name = name
        self.age = age

def person_factory():
    return Person(None, None)

JSONParser.add_factory('person', person_factory)
print(JSONParser.has_factory('person'))  # True
print(JSONParser.from_json({'type': 'person'}))  # Person object
