namespace MyNamespace {
    class RandomGenerator {
        public:
            static std::mt19937 engine;
            static int seed;

            RandomGenerator() : engine(seed) {}

            ~RandomGenerator() {}

            static void setSeed(int s) { seed = s; }

            static int generateRandomNumber(int min, int max) {
                std::uniform_int_distribution<int> distribution(min, max);
                return distribution(engine);
            }
    };

    MyNamespace::RandomGenerator::std::mt19937 RandomGenerator::engine;
    int RandomGenerator::seed = 0;

}

void populateArrays(int* offsetValues, int* keys, MyNamespace::RandomGenerator::RandomGenerator& randomGen) {
    const int MAX_SIZE = 10000;
    const int MIN_VALUE = 1;
    const int MAX_VALUE = 100;
    const int RECORD_COUNT = 5000;

    if (offsetValues == nullptr || keys == nullptr) {
        return; // Return error code
    }

    for (int i = 0; i < RECORD_COUNT; ++i) {
        offsetValues[i] = randomGen.generateRandomNumber(MIN_VALUE, MAX_VALUE);
        keys[i] = randomGen.generateRandomNumber(MIN_VALUE, MAX_VALUE);

        // Allocate memory for records array dynamically.
        int* recordArray;
        if ((recordArray = new int[RECORD_COUNT]) == nullptr) {
            // Free previously allocated memory and return error code
            delete[] offsetValues;
            delete[] keys;
            return; 
        }

        // Initialize each record with a random value within the given range.
        for (int j = 0; j < RECORD_COUNT; ++j) {
            recordArray[j] = randomGen.generateRandomNumber(MIN_VALUE, MAX_VALUE);
        }
    }

    std::cout << "Records populated successfully." << std::endl;
}

int main() {
    // Initialize the random number generator.
    MyNamespace::RandomGenerator::setSeed(time(NULL));

    int* offsetValues;
    int* keys;

    if ((offsetValues = new int[RECORD_COUNT]) == nullptr || 
        (keys = new int[RECORD_COUNT]) == nullptr) {
        // Return error code
        return -1; 
    }

    populateArrays(offsetValues, keys, MyNamespace::RandomGenerator());

    delete[] offsetValues;
    delete[] keys;

    return 0;
}
