typedef struct {
    uint32_t ue_id;
    uint16_t cell_id;
    int num_rrc_conn_reconfig;
    struct {
        uint8_t srb1_config;
        uint8_t dedicated_bearers;
        uint8_t measurement_controls;
    } rrc_conn_reconfig[10];
} LTE_Ue_Context;

LTE_Ue_Context* lte_ue_context_create(uint32_t ue_id, uint16_t cell_id) {
    LTE_Ue_Context* context = (LTE_Ue_Context*)malloc(sizeof(LTE_Ue_Context));
    if (!context) return NULL;

    context->ue_id = ue_id;
    context->cell_id = cell_id;
    context->num_rrc_conn_reconfig = 0;

    return context;
}

int lte_ue_context_add_rrc_conn_reconfig(LTE_Ue_Context* context, uint8_t srb1_config, uint8_t dedicated_bearers, uint8_t measurement_controls) {
    if (context->num_rrc_conn_reconfig >= sizeof(context->rrc_conn_reconfig) / sizeof(context->rrc_conn_reconfig[0])) {
        return -1; // Error: max number of RRC connection reconfigs reached
    }

    context->rrc_conn_reconfig[context->num_rrc_conn_reconfig].srb1_config = srb1_config;
    context->rrc_conn_reconfig[context->num_rrc_conn_reconfig].dedicated_bearers = dedicated_bearers;
    context->rrc_conn_reconfig[context->num_rrc_conn_reconfig++].measurement_controls = measurement_controls;

    return 0; // Success
}

int lte_ue_context_free(LTE_Ue_Context* context) {
    free(context);
    return 0; // Success
}

void parse_ue_context_json(const char* json_file, LTE_Ue_Context** ue_contexts) {
    json_object* jobj = json_object_from_file(json_file);
    if (!jobj) return;

    int num_ue_contexts = json_object_get_int(jobj, "num_ue_contexts");
    *ue_contexts = (LTE_Ue_Context*)malloc(sizeof(LTE_Ue_Context) * num_ue_contexts);

    for (int i = 0; i < num_ue_contexts; i++) {
        json_object* ue_ctx_obj = json_object_get_object(jobj, sprintf("ue_context_%d", i));
        if (!ue_ctx_obj) continue;

        LTE_Ue_Context* context = lte_ue_context_create(json_object_get_int(ue_ctx_obj, "ue_id"), json_object_get_int(ue_ctx_obj, "cell_id"));
        // Add RRC connection reconfigs...
        for (int j = 0; j < json_object_get_int(ue_ctx_obj, "num_rrc_conn_reconfig"); j++) {
            lte_ue_context_add_rrc_conn_reconfig(context, json_object_get_int(ue_ctx_obj, sprintf("srb1_config_%d", j)),
                                                  json_object_get_int(ue_ctx_obj, sprintf("dedicated_bearers_%d", j)),
                                                  json_object_get_int(ue_ctx_obj, sprintf("measurement_controls_%d", j)));
        }

        (*ue_contexts)[i] = context;
    }

    json_object_free(jobj);
}
