        free(doubles);
        free(ints);
        free(points);
        return NULL;
    }

    // Initialize random number generator for record values
    srand(time(NULL));

    // Initialize each record with a random value within the given range
    for (size_t i = 0; i < max_size; i++) {
        records[i].key = rand() % key_size;
        records[i].value = (double)rand() / RAND_MAX * offset_size;
    }

    return records;
}

