#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char mac[18];
    char ssid[33];
    struct client_info* clients;
} ap_t;

typedef struct {
    char ip[16];
    time_t last_seen;
    int quality;
} client_info_t;

ap_t* create_ap(char* mac, char* ssid) {
    ap_t* ap = (ap_t*)malloc(sizeof(ap_t));
    strcpy(ap->mac, mac);
    strcpy(ap->ssid, ssid);
    ap->clients = NULL;
    return ap;
}

void add_client(ap_t* ap, client_info_t* client) {
    if (!ap->clients) {
        ap->clients = (client_info_t*)malloc(sizeof(client_info_t));
        ap->clients->next = NULL;
    } else {
        client_info_t* current = ap->clients;
        while (current && current->next) {
            current = current->next;
        }
        current->next = (client_info_t*)malloc(sizeof(client_info_t));
        current->next->next = NULL;
        current->next->ip = client->ip;
        current->next->last_seen = client->last_seen;
        current->next->quality = client->quality;
    }
}

void remove_client(ap_t* ap, char* ip) {
    if (!ap->clients) return;

    client_info_t* current = ap->clients;
    client_info_t* prev = NULL;

    while (current && strcmp(current->ip, ip)) {
        prev = current;
        current = current->next;
    }

    if (!current) return;

    if (prev) {
        prev->next = current->next;
    } else {
        ap->clients = current->next;
    }

    free(current);
}

void update_last_seen(ap_t* ap, char* ip) {
    client_info_t* current = ap->clients;
    while (current) {
        if (!strcmp(current->ip, ip)) {
            current->last_seen = time(NULL);
            return;
        }
        current = current->next;
    }
}

void print_ap(ap_t* ap) {
    printf("AP: %s - %s\n", ap->mac, ap->ssid);

    client_info_t* current = ap->clients;
    while (current) {
        printf("Client: %s - Last Seen: %ld - Quality: %d\n",
            current->ip, current->last_seen, current->quality);
        current = current->next;
    }
}

int main() {
    ap_t* ap1 = create_ap("00:11:22:33:44:55", "MyAP");
    add_client(ap1, (client_info_t*)malloc(sizeof(client_info_t)));
    strcpy(((ap1->clients)->ip), "192.168.0.100");
    ((ap1->clients)->last_seen = time(NULL);
    ((ap1->clients)->quality = 80);

    ap_t* ap2 = create_ap("66:77:88:99:AA:BB", "AnotherAP");

    print_ap(ap1);
    update_last_seen(ap1, "192.168.0.100");
    remove_client(ap1, "192.168.0.100");

    return 0;
}
