LTE_PHY_PDU* createPDU(int cellID) {
    LTE_PHY_PDU* pdu = (LTE_PHY_PDU*)malloc(sizeof(LTE_PHY_PDU));
    // Initialize TFCI and RI within valid range
    pdu->L1_TFCI = rand() % 128;
    pdu->L1_RI = rand() % 256;

    int status;
    pid_t pid = fork();
    if (pid == 0) {
        // Perform external data retrieval using fork and wait system calls
        FILE* file = fopen("/path/to/external/data", "r");
        if (!file) {
            perror("Error opening file");
            return NULL;
        }
        fscanf(file, "%d", &status);
        fclose(file);

        kill(getppid(), SIGUSR1); // Signal parent process that data retrieval is complete
    } else {
        wait(NULL);
        if (waitpid(pid, NULL, 0) < 0) {
            perror("Error waiting for child");
            free(pdu);
            return NULL;
        }
    }

    // Validate TFCI and RI based on cell ID configuration
    if (status == 1) {
        // Validate successful
        pdu->L1_HARQ = (rand() % 2 == 0) ? HARQ_ACK : HARQ_NACK;
    } else {
        // Validation failed, skip this PDU
        free(pdu);
        return NULL;
    }

    return pdu;
}

int main() {
