        new_node->CRCFLAG = rand() % 2;

        // Add the new node to the linked list
        *tail = new_node;
        tail = &(*tail)->next; // Update the tail pointer

        if (i == n - 1) {
            // Last node in the list, so set its next pointer to NULL
            new_node->next = NULL;
        } else {
            // Add a link to the next node
            new_node->next = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T*));
            *new_node->next = NULL; // Initialize next pointer
        }
    }

    return head;
