        segment->seq_num = rand() % (4294967295 - 0) + 0; // 0-4294967295
        segment->ack_num = rand() % (4294967295 - 0) + 0; // 0-4294967295
        segment->flags = 'R' | 'S'; // Randomly choose flags

        if (!segments) {
            segments = safe_malloc(sizeof(TcpSegment*) * max_size);
            if (!segments) {
                free_segment(new_segment); // Free the new segment
                printf("Memory allocation failed. Error code: %d\n", errno);
                return -1; // or some error code
            }
        }

        segments[segment_count] = segment;
        segment_count++;

        if (segment_count >= max_size) {
            break;
        }
    }

    free_segments(segments, segment_count);
    return 0;
}
