#include <time.h>

typedef struct {
    int key;
    int value;
} record_t;

record_t* init_records(int num_records) {
    int i, j;
    record_t *records = (record_t *)malloc(num_records * sizeof(record_t));

    for(i = 0; i < num_records; ++i) {
        records[i].key = rand() % 100 + 1;
        records[i].value = rand() % 100 + 1;
    }

    return records;
}

void sort_records(record_t *records, int num_records) {
    record_t temp;
    int i, j;
    for(i = 0; i < num_records - 1; ++i) {
        for(j = 0; j < (num_records - i - 1); ++j) {
            if(records[j].key > records[j+1].key) {
                temp = records[j];
                records[j] = records[j+1];
                records[j+1] = temp;
            }
        }
    }
}

void free_records(record_t *records, int num_records) {
    free(records);
}

int main() {
    srand(time(NULL));

    record_t *records = init_records(10);
    sort_records(records, 10);

    for(int i = 0; i < 10; ++i) {
        printf("%d %d\n", records[i].key, records[i].value);
    }

    free_records(records, 10);

    return 0;
}
