    if (!context) return NULL;

    context->ue_id = ue_id;
    context->report = NULL;
    context->signal_quality_tag = rand() % 101; // random quality level between 0 and 100

    return context;
}

void destroy_ue_context(LTEUEContext* context) {
    if (!context) return;

    free(context->report);
    free(context);
}

int ue_list_size = 0;

LTEUEContext** ue_list = NULL;

void add_ue_context(int ue_id) {
    LTEUEContext** new_list = (LTEUEContext**)realloc(ue_list, (ue_list_size + 1) * sizeof(LTEUEContext*));
    if (!new_list) return;

    ue_list = new_list;
    ue_list[ue_list_size] = create_ue_context(ue_id);

    if (!ue_list[ue_list_size]) {
        for (int i = ue_list_size - 1; i >= 0; i--) {
            destroy_ue_context(ue_list[i]);
            free(ue_list[i]);
        }
        free(ue_list);
        return;
    }

    ue_list_size++;
}

void remove_ue_context(int ue_id) {
    for (int i = 0; i < ue_list_size; i++) {
        if (ue_list[i]->ue_id == ue_id) {
            destroy_ue_context(ue_list[i]);
            for (int j = i + 1; j < ue_list_size; j++) {
                ue_list[j - 1] = ue_list[j];
            }
            free(ue_list[--ue_list_size]);
            return;
        }
    }
}

void print_ue_contexts() {
    for (int i = 0; i < ue_list_size; i++) {
        printf("UE ID: %d, Signal Quality Tag: %d\n", ue_list[i]->ue_id, ue_list[i]->signal_quality_tag);
    }
}
