    // Initialize return pointer and memory allocation
    NFAPI_CRC_INDICATION_PDU_T** list = (NFAPI_CRC_INDICATION_PDU_T**)malloc((n + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!list) {
        fprintf(stderr, "Memory allocation failed for the list.\n");
        return NULL;
    }

    // Initialize current index to keep track of allocated memory
    int i = 0;

    while (i < n) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            // Handle memory allocation failure for individual structures
            fprintf(stderr, "Memory allocation failed for the structure.\n");
            break;
        }

        // Generate random RNTI and set CRCFLAG randomly
        pdu->RNTI = rand();
        pdu->CRCFLAG = (rand() & 1);  // Set CRCFLAG to 0 or 1

        // Add the structure to the list
        list[i] = pdu;
        i++;
    }

    return list;
}

// Function to check for uniqueness of RNTI values in a given list
int validateRNTIUniqueness(NFAPI_CRC_INDICATION_PDU_T** list, int n) {
    // Initialize flag to track if RNTI values are unique
    int isUnique = 1;

    // Iterate over the list and check for duplicate RNTI values
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if (list[i]->RNTI == list[j]->RNTI) {
                // Found a duplicate RNTI value
                isUnique = 0;
                break;
            }
        }
    }

    return isUnique;
}

