    if (!list) {
        fprintf(stderr, "Failed to create and populate the list.\n");
    } else {
        clock_t start = clock();
        int isUnique = validateRNTIUniqueness(list, n);
        clock_t end = clock();

        // Calculate time taken for population
        double seconds = (double)(end - start) / CLOCKS_PER_SEC;

        if (!isUnique) {
            fprintf(stderr, "RNTI values are not unique in the list.\n");
        } else {
            printf("List populated successfully with %d NFAPI_CRC_INDICATION_PDU_T structures and RNTI values checked for uniqueness.\n", n);
