#include <openssl/aes.h>
#include <openssl/err.h>
#include <openssl/rand.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef enum {
    ECB_MODE,
    EDE_MODE,
    EDE3_MODE,
    CFB_MODE
} CipherMode;

typedef struct {
    CipherMode mode;
    unsigned char* key;
    unsigned int key_length;
    EVP_CIPHER_CTX* ctx;
} CipherContext;

CipherContext* cipher_init(CipherMode mode, unsigned char* key, unsigned int key_length) {
    CipherContext* ctx = (CipherContext*)malloc(sizeof(CipherContext));
    if (ctx == NULL) return NULL;

    ctx->mode = mode;
    ctx->key = key;
    ctx->key_length = key_length;
    ctx->ctx = EVP_CIPHER_CTX_new();

    switch (mode) {
        case ECB_MODE:
            EVP_CipherInit_ex(ctx->ctx, EVP_aes_64_cbc(), NULL, key, key_length);
            break;
        case EDE_MODE:
            EVP_CipherInit_ex(ctx->ctx, EVP_aes_128_cbc(), NULL, key, key_length);
            break;
        case EDE3_MODE:
            EVP_CipherInit_ex(ctx->ctx, EVP_aes_128_cbc(), NULL, key, key_length);
            break;
        case CFB_MODE:
            EVP_CipherInit_ex(ctx->ctx, EVP_aes_128_cfb64(), NULL, key, key_length);
            break;
    }

    if (EVP_CIPHER_CTX_init(ctx->ctx) <= 0) {
        free(ctx);
        return NULL;
    }

    return ctx;
}

int cipher_encrypt(CipherContext* ctx, unsigned char* plaintext, unsigned char** ciphertext, unsigned int* ciphertext_len) {
    *ciphertext_len = EVP_CipherUpdate(ctx->ctx, (unsigned char*)*ciphertext, ciphertext_len);
    if (*ciphertext_len <= 0) return -1;

    return 1;
}

int cipher_decrypt(CipherContext* ctx, unsigned char* ciphertext, unsigned char** plaintext, unsigned int* plaintext_len) {
    *plaintext_len = EVP_CipherUpdate(ctx->ctx, (unsigned char*)*plaintext, plaintext_len);
