}

int asc_sort(const void *a, const void *b) {
    int pa = *(int *)a;
    int pb = *(int *)b;
    if (pa < pb) {
        return -1;
    } else if (pa > pb) {
        return 1;
    }
    return 0;
}

int desc_sort(const void *a, const void *b) {
    int pa = *(int *)a;
    int pb = *(int *)b;
    if (pa < pb) {
        return 1;
    } else if (pa > pb) {
        return -1;
    }
    return 0;
}
