record* create_records(long offset_count, long key_count, int max_value, int min_value, int max_size, bool use_custom_rng, rand_func custom_rng) {
    // Initialize thread-local storage for intermediate results
    pthread_mutex_init(&record_thread_data, NULL);
    pthread_mutex_lock(&record_thread_data);

    record* records = (record*)malloc(max_size * sizeof(record));
    if (!records) {
        // Allocation failed due to insufficient memory
        custom_logging_system_log("Memory allocation failure", "Records");
        free(records);  // Free any previously allocated memory
        return NULL;  // Return error code
    }

    int* offsets = (int*)malloc(key_count * sizeof(int));
    if (!offsets) {
        // Allocation failed due to insufficient memory
        custom_logging_system_log("Memory allocation failure", "Offsets");
        free(offsets);
        free(records);  // Free any previously allocated memory
        return NULL;  // Return error code
    }

    long* keys = (long*)malloc(key_count * sizeof(long));
    if (!keys) {
        // Allocation failed due to insufficient memory
        custom_logging_system_log("Memory allocation failure", "Keys");
        free(keys);
        free(offsets);
        free(records);  // Free any previously allocated memory
        return NULL;  // Return error code
    }

    for (int i = 0; i < offset_count; i++) {
        if (use_custom_rng) {
            records[i].value = custom_rng(min_value, max_value);
        } else {
            records[i].value = rand() % (max_value - min_value + 1) + min_value;
        }
    }

    pthread_mutex_unlock(&record_thread_data);

    return records;
}

