#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} Record;

Record* initRecords(int numRecords, const char** rangeFiles) {
    if (numRecords <= 0 || !rangeFiles) {
        return NULL; // invalid input
    }

    // dynamically allocate memory for arrays
    long* offsets = (long*)malloc(numRecords * sizeof(long));
    int* keys = (int*)malloc(numRecords * sizeof(int));
    Record* records = (Record*)malloc(numRecords * sizeof(Record));

    if (!offsets || !keys || !records) {
        free(offsets);
        free(keys);
        return NULL; // memory allocation failed
    }

    FILE* configFile = fopen("config.txt", "r");
    if (!configFile) {
        printf("Error: cannot open configuration file\n");
        free(offsets);
        free(keys);
        return NULL;
    }

    int lineNum = 1;
    while (fscanf(configFile, "%ld %d\n", &offsets[lineNum-1], &keys[lineNum-1]) == 2) {
        lineNum++;
    }
    fclose(configFile);

    if (lineNum != numRecords) {
        printf("Error: configuration file has incorrect number of entries (%d vs. %d)\n", lineNum, numRecords);
        free(offsets);
        free(keys);
        return NULL;
    }

    for (int i = 0; i < numRecords; i++) {
        Record* record = &records[i];
        record->value = rand() % ((rand() % 100 + 1) * 10); // random value within a range
    }

    // parse range files and set values for each record
    for (int i = 0; i < numRecords; i++) {
        FILE* rangeFile = fopen(rangeFiles[i], "r");
        if (!rangeFile) {
            printf("Error: cannot open range file %s\n", rangeFiles[i]);
            free(offsets);
            free(keys);
            return NULL;
        }

        int min, max;
        while (fscanf(rangeFile, "%d-%d\n", &min, &max) == 2) {
            if (i >= min && i <= max) {
                Record* record = &records[i];
                if (record->value < min || record->value > max) {
                    record->value = rand() % ((rand() % (max - min + 1)) + 1); // re-roll within the range
                }
            }
        }
        fclose(rangeFile);
    }

    return records;
}
