typedef struct {
    float value;
} data_point;

data_point* create_data_array(size_t size) {
    // Initialize array with dynamic allocation
    data_point* arr = (data_point*)malloc(size * sizeof(data_point));

    if (!arr) return NULL; // Memory allocation failed

    // Initialize values to random range
    srand(time(NULL)); // Seed random number generator
    for (size_t i = 0; i < size; i++) {
        arr[i].value = (float)(rand() / (RAND_MAX / FLOAT_RANGE));
    }

    return arr;
}

void resize_data_array(data_point** array, size_t* size, size_t new_size) {
    // Check if resizing is necessary
    if (*size >= new_size) return; // No need to resize

    // Allocate new array with increased size
    data_point* new_arr = (data_point*)realloc(*array, new_size * sizeof(data_point));

    if (!new_arr) { // Memory allocation failed
        free(*array); // Free original array
        *size = 0;     // Reset size to 0
        return;
    }

    // Copy data from old array to new array
    memcpy(new_arr, *array, *size * sizeof(data_point));

    // Update pointer and size
    free(*array);
    *array = new_arr;
    *size = new_size;
