namespace RandomNamespace {
    class Record {
        public:
            int value;
    };

    void generateRecords(int* offsets, int* keys, Record** records, int& totalRecords, int maxSize) {
        std::random_device rd;  // obtain a random number from hardware
        std::mt19937 gen(rd()); // seed the generator

        for (int i = 0; i < totalRecords; ++i) {
            if (*offsets + sizeof(Record) > maxSize) {
                std::cout << "Insufficient memory. Freeing previously allocated memory and returning error code." << std::endl;
                return -1;
            }

            // Initialize record with a random value
            new (&((*records)[i])) Record{static_cast<int>(gen() % 1000)};  // Generate a random number between 0 and 999

            offsets += sizeof(Record);
        }
    }
}
