<?php
function generateRandomString(int $length, string $characterSet): string {
    if ($length < 1 || empty($characterSet)) {
        return "Invalid input. Please provide a valid length and character set.";
    }

    $randomString = '';
    for ($i = 0; $i < $length; $i++) {
        $randomCharacter = substr($characterSet, rand(0, strlen($characterSet) - 1), 1);
        $randomString .= $randomCharacter;
