    int crcflag;
} nfapi_crc_indication_pdu_t;

// Function to create and populate a list of LTE UE Context structures
int create_lte_ue_context_list(int num_ues, lte_ue_context_t** lte_ue_context_list) {
    int i;
    for (i = 0; i < num_ues; i++) {
        // Create new LTE UE Context structure
        lte_ue_context_t* ue_ctx = (lte_ue_context_t*)malloc(sizeof(lte_ue_context_t));

        if (ue_ctx == NULL) {
            return -1; // Memory allocation failed
        }

        // Initialize UE ID and cell ID
        ue_ctx->ue_id = i;
        ue_ctx->cell_id = i * 2;

        // Calculate number of RRC Connection Reconfiguration messages needed
        int num_rrc_conn_reconf_msgs = (i % 3) + 1;

        // Allocate memory for the list of RRC Connection Reconfiguration messages
        ue_ctx->num_rrc_conn_reconf = num_rrc_conn_reconf_msgs;
        ue_ctx->rrc_conn_reconf_msgs = (struct rrc_conn_reconf_message**)malloc(num_rrc_conn_reconf_msgs * sizeof(struct rrc_conn_reconf_message*));

        if (ue_ctx->rrc_conn_reconf_msgs == NULL) {
            free(ue_ctx);
            return -1; // Memory allocation failed
        }

        // Create and populate the RRC Connection Reconfiguration messages
        for (int j = 0; j < num_rrc_conn_reconf_msgs; j++) {
            rrc_conn_reconf_message_t* rrc_conn_reconf_msg = (rrc_conn_reconf_message_t*)malloc(sizeof(rrc_conn_reconf_message_t));

            if (rrc_conn_reconf_msg == NULL) {
                for (int k = 0; k < j; k++) {
                    free(ue_ctx->rrc_conn_reconf_msgs[k]);
                }
                free(ue_ctx->rrc_conn_reconf_msgs);
                free(ue_ctx);
                return -1; // Memory allocation failed
            }

            // Initialize SRBI configuration, dedicated bearers, and measurement controls
            rrc_conn_reconf_msg->srbi_config = j;
            rrc_conn_reconf_msg->num_dedicated_bearers = (j % 2) + 1;
            rrc_conn_reconf_msg->measurement_controls = (j % 3) + 1;

            // Add the RRC Connection Reconfiguration message to the list
            ue_ctx->rrc_conn_reconf_msgs[j] = rrc_conn_reconf_msg;
        }

        // Create a new NFAPI CRC INDICATION PDU T structure for each LTE UE Context
        int num_nfapi_crc_indications = (i % 4) + 1;
        for (int j = 0; j < num_nfapi_crc_indications; j++) {
            nfapi_crc_indication_pdu_t* nfapi_crc_indication_pdu = (nfapi_crc_indication_pdu_t*)malloc(sizeof(nfapi_crc_indication_pdu_t));

            if (nfapi_crc_indication_pdu == NULL) {
                for (int k = 0; k < j; k++) {
                    free(ue_ctx->rrc_conn_reconf_msgs[k]);
                }
                free(ue_ctx->rrc_conn_reconf_msgs);
                free(ue_ctx);
                return -1; // Memory allocation failed
            }

            // Initialize RX UE INFORMATION TAG, RNTI, and CRC FLAG
            nfapi_crc_indication_pdu->rx_ue_info_tag = j;
            nfapi_crc_indication_pdu->rnti = (j % 2) + 1;
            nfapi_crc_indication_pdu->crcflag = (j % 3) + 1;

            // Add the NFAPI CRC INDICATION PDU T to the list
            ue_ctx->nfapi_crc_indications = (nfapi_crc_indication_pdu_t**)malloc((num_nfapi_crc_indications + j) * sizeof(nfapi_crc_indication_pdu_t*));
            ue_ctx->nfapi_crc_indications[j] = nfapi_crc_indication_pdu;
        }

        // Add the LTE UE Context to the list
        lte_ue_context_list[i] = ue_ctx;
    }

    return 0; // Success
}

int main() {
    int num_ues = 10;
    lte_ue_context_t** lte_ue_context_list = (lte_ue_context_t**)malloc(num_ues * sizeof(lte_ue_context_t*));

    if (lte_ue_context_list == NULL) {
        return -1; // Memory allocation failed
    }

    int result = create_lte_ue_context_list(num_ues, lte_ue_context_list);

    if (result != 0) {
        printf("Error creating LTE UE context list\n");
        for (int i = 0; i < num_ues; i++) {
            free(lte_ue_context_list[i]);
        }
        free(lte_ue_context_list);
        return -1;
    }

    // Print the created LTE UE Context structures
    for (int i = 0; i < num_ues; i++) {
        lte_ue_context_t* ue_ctx = lte_ue_context_list[i];

        printf("UE ID: %d, Cell ID: %d\n", ue_ctx->ue_id, ue_ctx->cell_id);

        for (int j = 0; j < ue_ctx->num_rrc_conn_reconf; j++) {
            rrc_conn_reconf_message_t* rrc_conn_reconf_msg = ue_ctx->rrc_conn_reconf_msgs[j];

            printf("SRBI configuration: %d, Dedicated bearers: %d, Measurement controls: %d\n", rrc_conn_reconf_msg->srbi_config, rrc_conn_reconf_msg->num_dedicated_bearers, rrc_conn_reconf_msg->measurement_controls);
        }

        for (int j = 0; j < ue_ctx->num_nfapi_crc_indications; j++) {
            nfapi_crc_indication_pdu_t* nfapi_crc_indication_pdu = ue_ctx->nfapi_crc_indications[j];

            printf("RX UE INFORMATION TAG: %d, RNTI: %d, CRC FLAG: %d\n", nfapi_crc_indication_pdu->rx_ue_info_tag, nfapi_crc_indication_pdu->rnti, nfapi_crc_indication_pdu->crcflag);
        }

        free(ue_ctx);
    }

    for (int i = 0; i < num_ues; i++) {
        free(lte_ue_context_list[i]);
    }
    free(lte_ue_context_list);
    return 0;
}
