#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <unistd.h>

typedef struct {
    int RNTI;
    int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* prev;
    struct node* next;
} Node;

Node* head = NULL;

void create_list(int n) {
    for (int i = 0; i < n; i++) {
        Node* new_node = (Node*) malloc(sizeof(Node));
        if (!new_node) {
            printf("Memory allocation failed\n");
            return;
        }
        new_node->data.RNTI = rand() % 1000;
        new_node->data.crcflag = rand() % 2;
        new_node->prev = NULL;
        new_node->next = NULL;

        if (head) {
            head->prev = &new_node->data;
            new_node->next = head;
            head = &new_node->data;
        } else {
            head = &new_node->data;
        }
    }
}

void insert_to_list(Node* node) {
    Node* temp = head;
    if (head == NULL || node->data.RNTI < temp->data.RNTI) {
        node->next = temp;
        node->prev = NULL;
        head = node;
    } else {
        while (temp->next && temp->data.RNTI > node->data.RNTI)
            temp = temp->next;
        node->next = temp->next;
        node->prev = temp;
        if (node->next) {
            node->next->prev = node;
        }
        temp->next = node;
    }
}

void save_list_to_file(Node* head, char* filename) {
    FILE* file = fopen(filename, "w");
    if (!file) {
        printf("Error opening file\n");
        return;
    }
    Node* temp = head;
    while (temp) {
        fprintf(file, "%d %d\n", temp->data.RNTI, temp->data.crcflag);
        temp = temp->next;
    }
    fclose(file);
}

void load_list_from_file(Node** head, char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        printf("Error opening file\n");
        return;
    }
    while (fscanf(file, "%d %d", &((*head)->data.RNTI, &((*head)->data.crcflag)) == 2) {
        Node* new_node = (Node*) malloc(sizeof(Node));
        if (!new_node) {
            printf("Memory allocation failed\n");
            return;
        }
        new_node->prev = (*head);
        new_node->next = NULL;
        (*head)->next = new_node;
        *head = new_node;
    }
    fclose(file);
}

void persist_list(Node* head, char* filename) {
    // Database integration goes here
    // For demonstration purposes, just save the list to file
    save_list_to_file(head, filename);
}

int main() {
    int n = 100000;
    create_list(n);

    Node* head_copy = NULL;
    load_list_from_file(&head_copy, "list.txt");

    persist_list(head, "persisted.txt");

    return 0;
}
