    boost::beast::http::timeout timeout(1000); // 1 second

    // Initialize arrays
    std::vector<long> offsets;
    std::vector<int> keys;

    for (int i = 0; i < 10; ++i) {
        offsets.push_back(i * 123);
        keys.push_back(i);
    }

    // Initialize array of record structures
    std::vector<record> records;

    for (int i = 0; i < 10; ++i) {
        records.emplace_back();
        records[i].value = static_cast<int>(std::rand() % 100); // Random value within range [0, 100)
    }

    // Send GET request to server
    boost::beast::http::request<boost::beast::http::string_body> req(boost::beast::http::verb::get, endpoint);
    req.set(boost::beast::http::field::content_length, "0");

    try {
        auto res = boost::beast::make_http_session().send(req);

        // Verify response
        if (res.result() == boost::beast::http::status::ok) {
            std::cout << "Response OK" << std::endl;
        } else {
            std::cerr << "Error: " << res.result().phrase() << std::endl;
        }
    } catch (const boost::system::system_error& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    // Parse OAuth2 access token response
    const std::string json = "{\"access_token\":\"abc123\",\"expires_in\":3600,\"token_type\":\"Bearer\"}";
    boost::json::value jval;
    try {
        jval = boost::json::parse(json);
    } catch (const boost::json::detail::parse_error& e) {
        std::cerr << "Error parsing JSON: " << e.what() << std::endl;
        return 1;
    }

    bool isValidToken = true;

    if (!jval.at("access_token").is_string()) {
        isValidToken = false;
    } else if (jval.at("expires_in").as_int64() <= 0) {
        isValidToken = false;
    } else if (jval.at("token_type").as_string().substr(0, 7) != "Bearer ") {
        isValidToken = false;
    }

    if (!isValidToken) {
        std::cerr << "Invalid token" << std::endl;
    } else {
        std::cout << "Valid token" << std::endl;
    }
}
