using Newtonsoft.Json;

public class LTEUEContext
{
    public Guid UEId { get; set; }
    public int CellId { get; set; }
    public MeasurementResult[] MeasurementResults { get; set; }
    public QoSIndicator QoS { get; set; }
}

public enum QoSIndicator
{
    High,
    Medium,
    Low
}

public class MeasurementResult
{
    public double RSRP { get; set; }
    public double RSRQ { get; set; }
    public double SINR { get; set; }
}

public class LTEUEContexts
{
    public List<LTEUEContext> UEs { get; set; }
}

public class EncryptionService
{
    private readonly TripleDES _des;
    private readonly byte[] _iv;

    public EncryptionService(byte[] key, byte[] iv)
    {
        _des = TripleDES.Create();
        _des.Key = key;
        _iv = iv;
    }

    public string DecryptBase64(string base64EncodedString)
    {
        using (var ms = new MemoryStream(Encoding.UTF8.GetBytes(base64EncodedString)))
        {
            var decryptor = _des.CreateDecryptor(_iv);
            var buffer = new byte[ms.Length];
            decryptor.TransformFinalBlock(ms.ToArray(), 0, buffer.Length);
            return Encoding.UTF8.GetString(buffer);
        }
    }

    public void SaveUEContexts(List<LTEUEContext> ues)
    {
        // External data storage system integration
        try
        {
            using (var connection = new MySqlConnection("YourConnectionstring"))
            {
                connection.Open();
                using (var command = new MySqlCommand())
                {
                    foreach (var ue in ues)
                    {
                        command.CommandText = "INSERT INTO UE_Contexts (UEId, CellId, MeasurementResults, QoS) VALUES (@UEId, @CellId, @MeasurementResults, @QoS)";
                        command.Parameters.AddWithValue("@UEId", ue.UEId);
                        command.Parameters.AddWithValue("@CellId", ue.CellId);
                        command.Parameters.AddWithValue("@MeasurementResults", JsonConvert.SerializeObject(ue.MeasurementResults));
                        command.Parameters.AddWithValue("@QoS", (int)ue.QoS);
                        command.ExecuteNonQuery();
                    }
                }
            }
        }
        catch (Exception ex)
        {
            // Handle errors and exceptions
            Console.WriteLine($"Error saving UE contexts: {ex.Message}");
        }
    }
}

public class LTEUEContextService
{
    private readonly EncryptionService _encryptionService;

    public LTEUEContextService(EncryptionService encryptionService)
    {
        _encryptionService = encryptionService;
    }

    public void ProcessBase64String(string base64EncodedString)
    {
        try
        {
            var decryptedJson = _encryptionService.DecryptBase64(base64EncodedString);
            if (string.IsNullOrEmpty(decryptedJson))
            {
                Console.WriteLine("Failed to decrypt the message.");
                return;
            }
            var lteUeContexts = JsonConvert.DeserializeObject<LTEUEContexts>(decryptedJson);
            _encryptionService.SaveUEContexts(lteUeContexts.UEs);
        }
        catch (Exception ex)
        {
            // Handle errors and exceptions
            Console.WriteLine($"Error processing the message: {ex.Message}");
        }
    }
}

public class Program
{
    public static void Main(string[] args)
    {
        var encryptionService = new EncryptionService(Encoding.UTF8.GetBytes("YourEncryptionKey"), Encoding.UTF8.GetBytes("YourInitializationVector"));
        var lteUeContextService = new LTEUEContextService(encryptionService);

        // Example usage
        string base64EncodedString = "YourBase64EncodedString";
        lteUeContextService.ProcessBase64String(base64EncodedString);
    }
}
