#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

typedef struct {
    int value;
    char *data;
} record;

void initialize_records(record **records, size_t num_records, int min_value, int max_value, int print_details) {
    *records = (record *)malloc(num_records * sizeof(record));
    if (*records == NULL) {
        printf("Memory allocation failed for records.\n");
        return;
    }

    long *offsets = (long *)malloc(num_records * sizeof(long));
    if (offsets == NULL) {
        free(*records);
        printf("Memory allocation failed for offsets.\n");
        return;
    }
    int *keys = (int *)malloc(num_records * sizeof(int));
    if (keys == NULL) {
        free(*records);
        free(offsets);
        printf("Memory allocation failed for keys.\n");
        return;
    }

    char **strings = (char **)calloc(num_records, sizeof(char *));
    if (strings == NULL) {
        free(*records);
        free(offsets);
        free(keys);
        printf("Memory allocation failed for strings.\n");
        return;
    }

    for (size_t i = 0; i < num_records; i++) {
        (*records)[i].value = rand() % ((max_value - min_value) + 1) + min_value;
        if (print_details)
            printf("Record %zu: Offset = %ld, Key = %d, Value = %d\n", i, offsets[i], keys[i], (*records)[i].value);

        char *string_data = (char *)malloc(20 * sizeof(char));
        sprintf(string_data, "Record_%zu", i);
        strings[i] = string_data;
    }

    free(offsets);
    free(keys);
    for (size_t i = 0; i < num_records; i++)
        free(strings[i]);
    free(strings);
}
