Node* create_node(UEContext* context) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        printf("Memory allocation failed\n");
        return NULL;
    }
    new_node->ue_context = context;
    new_node->prev = NULL;
    new_node->next = NULL;
    return new_node;
}

// Function to insert a node at the beginning of the list
void insert_at_beginning(Node** head, Node* new_node) {
    if (*head == NULL || *head == new_node) {
        return;
    }
    new_node->next = *head;
    *head = new_node;
    // Log insertion operation for debugging purposes
    printf("UE context inserted at the beginning\n");
}

// Function to insert a node after a given node in the list
void insert_after(Node* prev_node, Node* new_node) {
    if (prev_node == NULL || new_node == NULL) {
        return;
    }
    new_node->next = prev_node->next;
    if (prev_node->next != NULL) {
        prev_node->next->prev = new_node;
    }
    prev_node->next = new_node;
    new_node->prev = prev_node;
    // Log insertion operation for debugging purposes
    printf("UE context inserted after previous node\n");
}

// Function to remove a node from the list
void delete_node(Node** head, Node* node_to_remove) {
    if (*head == NULL || *head == node_to_remove) {
        return;
    }
    if (node_to_remove->prev != NULL) {
        node_to_remove->prev->next = node_to_remove->next;
    } else {
        *head = node_to_remove->next;
    }
    if (node_to_remove->next != NULL) {
        node_to_remove->next->prev = node_to_remove->prev;
    }
    // Log deletion operation for debugging purposes
    printf("UE context removed from the list\n");
}

// Function to free all allocated memory when the list is no longer needed
void free_list(Node** head) {
    Node* current_node = *head;
    while (current_node != NULL) {
        Node* next_node = current_node->next;
        free(current_node);
        current_node = next_node;
    }
}

