**JavaScript function:**
```javascript
function traverseDOM(tree, selector, callback) {
    const cache = {};

    function traverse(node) {
        if (!node) return [];

        let matches = [];
        if (node.classList && node.classList.length > 0) {
            const classes = node.classList;
            for (let i = 0; i < classes.length; i++) {
                if (callback(classes[i])) {
                    matches.push(node);
                }
            }
        } else if (node.id) {
            if (callback(node.id)) {
                matches.push(node);
            }
        }

        const children = node.childNodes;
        for (let i = 0; i < children.length; i++) {
            const childMatches = traverse(children[i]);
            matches = matches.concat(childMatches);
        }

        return matches;
    }

    function recursiveTraverse(node) {
        if (!node) return [];
        let matches = traverse(node);
        cache[selector] = matches;
        return matches;
    }

    return (node, selector) => {
        if (!cache[selector]) {
            const result = recursiveTraverse(node);
            if (!result.length) return [];
            return result;
        } else {
            return cache[selector];
        }
    };
}
