#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

typedef struct {
    int key;
    long offset;
} record_t;

record_t* create_record(int key, long offset) {
    record_t* record = (record_t*)malloc(sizeof(record_t));
    if (!record) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    record->key = key;
    record->offset = offset;
    return record;
}

int compare_records(const void* a, const void* b) {
    record_t* record1 = (record_t*)a;
    record_t* record2 = (record_t*)b;
    if (record1->key < record2->key) return -1;
    else if (record1->key > record2->key) return 1;
    else return 0;
}

void merge_records(record_t** arr1, int n1, record_t** arr2, int n2, record_t*** result, int* result_len) {
    qsort(*arr1, n1, sizeof(record_t), compare_records);
    qsort(*arr2, n2, sizeof(record_t), compare_records);

    int i = 0;
    int j = 0;
    int k = 0;

    while (i < n1 && j < n2) {
        if ((*arr1)[i]->key <= (*arr2)[j]->key) {
            (*result)[*result_len][k] = *(*arr1)[i];
            i++;
        } else {
            (*result)[*result_len][k] = (*arr2)[j];
            j++;
        }
        k++;
    }

    while (i < n1) {
        (*result)[*result_len][k] = (*arr1)[i];
        i++;
        k++;
    }

    while (j < n2) {
        (*result)[*result_len][k] = (*arr2)[j];
        j++;
        k++;
    }
}

int main() {
    // Example usage:
    int n1 = 5;
    int n2 = 3;

    record_t** records1 = (record_t**)malloc((n1 + 1) * sizeof(record_t*));
    for (int i = 0; i <= n1; i++) {
        records1[i] = create_record(rand() % 100, rand() % 1000000);
    }

    record_t** records2 = (record_t**)malloc((n2 + 1) * sizeof(record_t*));
    for (int i = 0; i <= n2; i++) {
        records2[i] = create_record(rand() % 100, rand() % 1000000);
    }

    record_t** result = (record_t**)malloc((n1 + n2) * sizeof(record_t*));
    int result_len = 0;

    merge_records(&records1, n1, &records2, n2, &result, &result_len);

    // Save the sorted records to a file
    FILE* f = fopen("output.bin", "wb");
    if (f) {
        fwrite(result, sizeof(record_t), result_len, f);
        fclose(f);
    }

    for (int i = 0; i <= n1; i++) free(records1[i]);
    for (int i = 0; i <= n2; i++) free(records2[i]);
    free(records1);
    free(records2);
    free(result);

    return 0;
}
```']

