// Union-Find data structure method
void union_find(int* arr, int n) {
    int parent[n];
    for (int i = 0; i < n; i++) {
        parent[i] = i;
    }

    for (int i = 0; i < n - 1; i++) {
        for (int j = i + 1; j < n; j++) {
            int start_time = clock();
            if (find(parent, arr[i], arr[j])) {
                printf("Pair %d and %d are in the same set. Time taken: %ld milliseconds.\n", i, j, (clock() - start_time) / 1000);
            } else {
                printf("Pair %d and %d are not in the same set. Time taken: %ld milliseconds.\n", i, j, (clock() - start_time) / 1000);
            }
        }
    }

    // Function to find the root of a node
    int find(int* parent, int x, int y) {
        if (parent[x] != x) {
            parent[x] = find(parent, parent[x], y); // Path compression
        }
        return x;
    }
}

