#include <stdlib.h>
#include <pthread.h>

// Define a structure for UE Context
typedef struct {
    uint64_t ue_id;
    uint32_t cell_id;
    int num_rrc_messages; // Number of RRC Connection Reconfiguration messages
    struct rrc_message **rrc_messages; // List of RRC Connection Reconfiguration messages
} ue_context;

// Define a structure for RRC Message
typedef struct {
    int srbr1_config;
    int dedicated_bearers;
    int measurement_controls;
} rrc_message;

// Function to create and populate a list of UE Contexts
void* add_ue_context(void* context, void* new_ctx) {
    ue_context** ue_list = (ue_context**)context;
    ue_context* new_ue_ctx = (ue_context*)new_ctx;
    pthread_mutex_lock(&mutex); // Lock for thread safety
    *ue_list = realloc(*ue_list, (++((*ue_list)->size) * sizeof(ue_context)));
    (*ue_list)[(*ue_list)->size - 1] = new_ue_ctx;
    pthread_mutex_unlock(&mutex); // Unlock
    return NULL;
}

// Function to serialize a list of UE Contexts to disk
void ue_context_serialize(const ue_context** ue_list, int num_ue, const char* filename) {
    FILE* file = fopen(filename, "wb");
    for (int i = 0; i < num_ue; i++) {
        fwrite(&((*ue_list)[i].ue_id), sizeof(uint64_t), 1, file);
        fwrite(&((*ue_list)[i].cell_id), sizeof(uint32_t), 1, file);
        int rrc_msg_size = (*ue_list)[i].num_rrc_messages * sizeof(rrc_message);
        fwrite(&rrc_msg_size, sizeof(int), 1, file);
        for (int j = 0; j < (*ue_list)[i].num_rrc_messages; j++) {
            fwrite(&((*ue_list)[i].rrc_messages[j]->srbr1_config), sizeof(int), 1, file);
            fwrite(&((*ue_list)[i].rrc_messages[j]->dedicated_bearers), sizeof(int), 1, file);
            fwrite(&((*ue_list)[i].rrc_messages[j]->measurement_controls), sizeof(int), 1, file);
        }
    }
    fclose(file);
}

// Function to deserialize a list of UE Contexts from disk
int ue_context_deserialize(ue_context** ue_list, int* num_ue, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return -1;
    for (int i = 0; i < *num_ue; i++) {
        fread(&((*ue_list)[i].ue_id), sizeof(uint64_t), 1, file);
        fread(&((*ue_list)[i].cell_id), sizeof(uint32_t), 1, file);
        int rrc_msg_size;
        fread(&rrc_msg_size, sizeof(int), 1, file);
        (*ue_list)[i].num_rrc_messages = rrc_msg_size / sizeof(rrc_message);
        (*ue_list)[i].rrc_messages = realloc((*ue_list)[i].rrc_messages, rrc_msg_size * sizeof(rrc_message*));
        for (int j = 0; j < (*ue_list)[i].num_rrc_messages; j++) {
            fread(&((*ue_list)[i].rrc_messages[j]->srbr1_config), sizeof(int), 1, file);
            fread(&((*ue_list)[i].rrc_messages[j]->dedicated_bearers), sizeof(int), 1, file);
            fread(&((*ue_list)[i].rrc_messages[j]->measurement_controls), sizeof(int), 1, file);
        }
    }
    fclose(file);
    return 0;
}

// Initialize mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int main() {
    // Initialize and populate the list of UE Contexts
    ue_context* ue_list = NULL;
    pthread_mutex_lock(&mutex); // Lock for thread safety
    ue_list = malloc(sizeof(ue_context));
    ue_list->size = 1; // Initial size is 1
    pthread_mutex_unlock(&mutex); // Unlock

    // Add more UE Contexts dynamically
    int num_ue = 5;
    for (int i = 0; i < num_ue; i++) {
        // Create and populate a new UE Context structure
        ue_context* new_ctx = malloc(sizeof(ue_context));
        new_ctx->ue_id = i;
        new_ctx->cell_id = i * 2;
        int rrc_msg_size = 5; // Number of RRC Connection Reconfiguration messages
        new_ctx->rrc_messages = malloc(rrc_msg_size * sizeof(rrc_message*));

        for (int j = 0; j < rrc_msg_size; j++) {
            rrc_message* new_rrc_msg = malloc(sizeof(rrc_message));
            new_rrc_msg->srbr1_config = i;
            new_rrc_msg->dedicated_bearers = j * 2;
            new_rrc_msg->measurement_controls = (j + 1) % 3; // Cyclic measurement controls
            new_ctx->rrc_messages[j] = new_rrc_msg;
        }

        // Add the new UE Context to the list
        pthread_mutex_lock(&mutex); // Lock for thread safety
        add_ue_context(&ue_list, new_ctx);
        pthread_mutex_unlock(&mutex); // Unlock

        free(new_ctx->rrc_messages); // Free memory allocated for RRC messages
    }

    // Serialize the list of UE Contexts to disk
    ue_context_serialize(ue_list, num_ue, "ue_contexts.bin");

    // Deserialize the list of UE Contexts from disk
    int deserialized_num_ue = 0;
    if (ue_context_deserialize(&ue_list, &deserialized_num_ue, "ue_contexts.bin") == 0) {
        printf("Deserialization successful. Number of UE contexts: %d\n", deserialized_num_ue);
    } else {
        printf("Error during deserialization.\n");
    }

    // Free memory allocated for the list of UE Contexts
    pthread_mutex_lock(&mutex); // Lock for thread safety
    while (ue_list->size > 0) {
        ue_context* last_ctx = &ue_list[ue_list->size - 1];
        free(last_ctx->rrc_messages);
        free(last_ctx);
        --ue_list->size;
    }
    free(ue_list);
    pthread_mutex_unlock(&mutex); // Unlock

    return 0;
}
