            FILE* fptr = fopen(path, "rb");
            if (fptr != NULL) {
                struct stat sb;
                if (fstat(fileno(fptr), &sb) == 0) {
                    size = sb.st_size;
                }
                fclose(fptr);
            }
            FileMetadata metadata = {path, size, 0};
            // Your code here to check readability
