void findLargestFile(FILE** files, int num_files) {
    int max_index = -1;
    for (int i = 0; i < num_files; i++) {
        FILE* fptr = fopen(files[i]->path, "rb");
        struct stat sb;
        if (fstat(fileno(fptr), &sb) == 0) {
            size_t size = sb.st_size;
            if (max_index == -1 || size > files[max_index]->size) {
                max_index = i;
            }
        }
        fclose(fptr);
    }
    printf("Largest file: %s\n", files[max_index]->path);
}

