NFAPI_CRC_INDICATION_PDU_T* create_and_populate_list(int num_structures) {
    // Initialize list and pointer to current element
    NFAPI_CRC_INDICATION_PDU_T* list = NULL;
    NFAPI_CRC_INDICATION_PDU_T* current = NULL;

    // Allocate memory for the list
    if (!(list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T)))) {
        return NULL;  // Handle memory allocation failure
    }

    // Initialize random seed
    srand(time(NULL));

    // Create and populate each structure in the list
    for (int i = 0; i < num_structures; i++) {
        current = &list[i];

        // Set valid RX_UE_INFORMATION_TAG and RNTI
        current->RX_UE_INFORMATION_TAG = i;
        current->RNTI = i;

        // Set CRC_INDICATION_REL8_TAG with randomly set CRCFLAG
        for (int j = 0; j < CRC_INDICATION_REL8_TAG_SIZE; j++) {
            current->CRC_INDICATION_REL8_TAG[j] = rand() % 256;
        }
    }

    // Sort the list by RNTI in ascending order
    qsort(list, num_structures, sizeof(NFAPI_CRC_INDICATION_PDU_T), compare_RNTI);

    return list;
}

int compare_RNTI(const void* a, const void* b) {
    NFAPI_CRC_INDICATION_PDU_T* struct_a = (NFAPI_CRC_INDICATION_PDU_T*)a;
    NFAPI_CRC_INDICATION_PDU_T* struct_b = (NFAPI_CRC_INDICATION_PDU_T*)b;

    if (struct_a->RNTI < struct_b->RNTI) {
        return -1;
    } else if (struct_a->RNTI > struct_b->RNTI) {
        return 1;
    }

    return 0;
}
