// Function to create and populate list of LTE MAC PDU structures
LTEMacPdu* createMacPdus(int N, int numMaceValues) {
    // Initialize the logger
    FILE *logger = fopen("mac_pdu_logger.log", "w");
    if (!logger) {
        printf("Error opening logger file.\n");
        return NULL;
    }

    // Get a predefined set of MAC CE values
    int* maceValues = (int*)malloc(numMaceValues * sizeof(int));
    for (int i = 0; i < numMaceValues; i++) {
        maceValues[i] = i % 256; // Randomly select MAC CE values from the set
    }

    // Create a list of LTE MAC PDU structures
    LTEMacPdu* macPdus = (LTEMacPdu*)malloc(N * sizeof(LTEMacPdu));
    if (!macPdus) {
        printf("Error allocating memory for MAC PDUs.\n");
        fclose(logger);
        return NULL;
    }

    // Populate the list with random MAC entity IDs and selected MAC CE values
    srand(time(NULL)); // Seed the random number generator
    for (int i = 0; i < N; i++) {
        macPdus[i].macEntityId = rand() % (1 << 16);
        macPdus[i].macCe = maceValues[rand() % numMaceValues];
        printf("Created MAC PDU with CE value %d and entity ID %u.\n", macPdus[i].macCe, macPdus[i].macEntityId);
        fprintf(logger, "Created MAC PDU with CE value %d and entity ID %u.\n", macPdus[i].macCe, macPdus[i].macEntityId);
    }

    // Free memory allocated for MAC CE values
    free(maceValues);

    // Return the list of LTE MAC PDU structures
    fclose(logger);
    return macPdus;
}

// Function to release memory allocated for MAC PDUs
void releaseMacPdus(LTEMacPdu* macPdus, int N) {
    if (!macPdus) {
        printf("Error: Attempting to release NULL pointer.\n");
        return;
    }

    free(macPdus);
}

int main() {
    // Example usage:
    LTEMacPdu* macPdus = createMacPdus(10, 256); // Create a list of 10 MAC PDUs with 256 possible CE values
    releaseMacPdus(macPdus, 10); // Release memory allocated for the MAC PDUs

    return 0;
}

