void add_ue_context(LTEUEContext*** list, int* total_ues) {
    *list = realloc(*list, (*total_ues + 1) * sizeof(LTEUEContext*));
    if (*list == NULL) {
        printf("Memory allocation failed\n");
        return;
    }

    LTEUEContext* new_ue_context = malloc(sizeof(LTEUEContext));
    if (new_ue_context == NULL) {
        printf("Memory allocation for UE context failed\n");
        free(*list);
        *list = NULL;
        return;
    }

