    new_ue_context->cell_id = 456; // dummy value
    new_ue_context->rrc_conn_reconfig_msgs = malloc(1 * sizeof(char*));
    if (new_ue_context->rrc_conn_reconfig_msgs == NULL) {
        printf("Memory allocation for RRC connection reconfiguration messages failed\n");
        free(new_ue_context);
        free(*list);
        *list = NULL;
        return;
    }
    new_ue_context->num_rrc_conn_reconfig_msgs = 1; // dummy value

    (*list)[*total_ues] = new_ue_context;
    (*total_ues)++;

