    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to read integers from standard input and find largest integer
void read_and_find_largest(int **arr, int *size) {
    int i = 0;
    *arr = (int *)malloc(sizeof(int));
    while (1) {
        printf("Enter an integer (or -1 to stop): ");
        scanf("%d", &((*arr)[i]));
        if ((*arr)[i] == -1)
            break;
        i++;
        (*arr) = (int *)realloc(*arr, sizeof(int) * (i + 1));
    }
    *size = i;
}

// Function to populate list of NFAPI_CRC_INDICATION_PDU_T structures
void populate_list(NFAPI_CRC_INDICATION_PDU_T **list, int size, int *max_size) {
    srand(time(NULL)); // seed for random number generation
    *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < size; i++) {
        (*list)[i].RX_UE_INFORMATION_TAG = rand() % 100;
        (*list)[i].RNTI = rand() % 1000;
        (*list)[i].CRCFLAG = rand() % 2;
    }
    *max_size = size;
}

// Function to validate integrity of each structure
int validate_structure(NFAPI_CRC_INDICATION_PDU_T *struct_obj) {
    if (struct_obj->RX_UE_INFORMATION_TAG < 0 || struct_obj->RX_UE_INFORMATION_TAG > 100)
        return -1; // invalid tag
    else if (struct_obj->RNTI < 0 || struct_obj->RNTI > 999)
        return -2; // invalid RNTI
    else if (struct_obj->CRCFLAG != 0 && struct_obj->CRCFLAG != 1)
        return -3; // invalid CRC flag
    else
        return 0; // valid structure
}

// Function to handle potential delays in data acquisition
void handle_delays(int retry_interval) {
    printf("Data acquisition delayed. Retrying after %d seconds...\n", retry_interval);
    sleep(retry_interval);
}

int main() {
    int *arr;
    int size = 0;
    read_and_find_largest(&arr, &size);

    NFAPI_CRC_INDICATION_PDU_T *list;
    int max_size = 0;
    populate_list(&list, size, &max_size);

    for (int i = 0; i < max_size; i++) {
        if (validate_structure(&list[i]) == -1) {
            printf("Invalid RX_UE_INFORMATION_TAG in structure %d\n", i);
            continue;
        } else if (validate_structure(&list[i]) == -2) {
            printf("Invalid RNTI in structure %d\n", i);
            continue;
        } else if (validate_structure(&list[i]) == -3) {
            printf("Invalid CRC flag in structure %d\n", i);
            continue;
        }
    }

    // free memory
    for (int i = 0; i < max_size; i++) {
        free(list + i);
    }
    free(list);

    return 0;
}
