// Function to create and populate the list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T** createAndPopulateList(int n, int* result) {
    NFAPI_CRC_INDICATION_PDU_T** list = (NFAPI_CRC_INDICATION_PDU_T**)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* entry = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        entry->RX_UE_INFORMATION_TAG = rand() % 100;
        entry->RNTI = rand() % 10;
        strcpy(entry->CRC_INDICATION_REL8_TAG, "Random_CRC");

        list[i] = entry;

        // Log information about each structure
        printf("Populated entry: RX_UE_INFORMATION_TAG=%d RNTI=%d CRC_INDICATION_REL8_TAG=\"%s\"\n", 
               entry->RX_UE_INFORMATION_TAG, entry->RNTI, entry->CRC_INDICATION_REL8_TAG);
    }

    *result = n;
    return list;
}

// Function to serialize the populated list into a binary file
int serializeList(NFAPI_CRC_INDICATION_PDU_T** list, int n) {
    int fd = open("output.bin", O_WRONLY | O_CREAT, S_IRUSR | S_IWUSR);
    if (fd < 0) {
        return -1;
    }

    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* entry = list[i];
        // Serialize the structure
        unsigned char buffer[1024];
        int len = sizeof(NFAPI_CRC_INDICATION_PDU_T);
        memcpy(buffer, &entry, len);

        // Compress the serialized data using zlib
        z_stream strm;
        strm.zalloc = Z_NULL;
        strm.zfree = Z_NULL;
        strm.opaque = Z_NULL;

        unsigned char compressed[1024];
        int compr_len;

        deflateInit(&strm, Z_DEFAULT_COMPRESSION);
        strm.next_in = buffer;
        strm.avail_in = len;
        strm.total_out = 0;

        do {
            strm.next_out = compressed;
            strm.avail_out = 1023;
            deflate(&strm, Z_NO_FLUSH);

            compr_len = strm.total_out;
        } while (strm.avail_out == 0);

        deflateEnd(&strm);

        // Write the compressed data to the file
        write(fd, compressed, compr_len);
    }

    close(fd);
    return 0;
}

// Function to deserialize the serialized binary file into a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T** deserializeList(int* result) {
    int fd = open("output.bin", O_RDONLY, S_IRUSR | S_IWUSR);
    if (fd < 0) {
        return NULL;
    }

    int n;
    read(fd, &n, sizeof(n));

    NFAPI_CRC_INDICATION_PDU_T** list = (NFAPI_CRC_INDICATION_PDU_T**)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* entry = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        // Deserialize the structure
        unsigned char buffer[1024];
        int len;
        read(fd, &len, sizeof(len));
        read(fd, buffer, len);

        // Decompress the deserialized data using zlib
        z_stream strm;
        strm.zalloc = Z_NULL;
        strm.zfree = Z_NULL;
        strm.opaque = Z_NULL;

        unsigned char decompressed[1024];
        int decomp_len;

        inflateInit(&strm);
        strm.next_in = buffer;
        strm.avail_in = len;
        strm.total_out = 0;

        do {
            strm.next_out = decompressed;
            strm.avail_out = 1023;
            inflate(&strm, Z_NO_FLUSH);

            decomp_len = strm.total_out;
        } while (strm.avail_out == 0);

        inflateEnd(&strm);

        // Update the list with the deserialized entry
        memcpy(entry, decompressed, decomp_len);
        list[i] = entry;

        printf("Deserialized entry: RX_UE_INFORMATION_TAG=%d RNTI=%d CRC_INDICATION_REL8_TAG=\"%s\"\n", 
               entry->RX_UE_INFORMATION_TAG, entry->RNTI, entry->CRC_INDICATION_REL8_TAG);
    }

    close(fd);
    return list;
}

int main() {
    int n = 5; // number of entries in the list

    NFAPI_CRC_INDICATION_PDU_T** list = createAndPopulateList(n, &n);

    if (list != NULL) {
        serializeList(list, n);

        NFAPI_CRC_INDICATION_PDU_T** deserialized_list = deserializeList(&n);
