void printPDULList(LTE_PHY_PDU* pdulList, int size) {
    for (int i = 0; i < size; i++) {
        printf("TFCI: %d, RI: %d, HARQ: %s\n",
               pdulList[i].L1_TFCI,
               pdulList[i].L1_RI,
               pdulList[i].L1_HARQ ? "HARQ_ACK" : "HARQ_NACK");
    }
}

int main() {
    int size = 10; // configurable list size
    LTE_PHY_PDU* pdulList = createPDULList(size);
    if (!pdulList) {
        return -1;
    }

    printPDULList(pdulList, size);

    free(pdulList);

    return 0;
}
