void manage_ue_context_list(UE_Context** ue_ctx_list, int* num_ue_ctx) {
    // Allocate memory for a new UE context structure
    UE_Context* new_ue_ctx = (UE_Context*)malloc(sizeof(UE_Context));

    if(new_ue_ctx != NULL) {
        // Initialize the newly allocated structure
        new_ue_ctx->ue_id = 0;  // Update with valid UE ID
        new_ue_ctx->cell_id = 0;  // Update with valid Cell ID
        new_ue_ctx->rrc_state = IDLE;  // Initialize RRC state as IDLE

        // Add the new structure to the list and increment the count
        *num_ue_ctx += 1;
        if(*ue_ctx_list != NULL) {
            UE_Context** temp = (UE_Context**)malloc((sizeof(UE_Context*) * (*num_ue_ctx)));
            memcpy(temp, *ue_ctx_list, sizeof(UE_Context*) * (*num_ue_ctx - 1));
            free(*ue_ctx_list);
            *ue_ctx_list = temp;
        } else {
            *ue_ctx_list = (UE_Context**)malloc(sizeof(UE_Context*));
        }

        // Update the newly added structure in the list
        (*ue_ctx_list)[*num_ue_ctx - 1] = new_ue_ctx;
    }

    // Handle memory deallocation for removed UE context structures
    if(*num_ue_ctx > 5) {
        *num_ue_ctx -= 1;
        free((*ue_ctx_list)[0]);
        memmove(*ue_ctx_list, (*ue_ctx_list) + 1, sizeof(UE_Context*) * (*num_ue_ctx));
        free((*ue_ctx_list));
        *ue_ctx_list = NULL;
    }
}

