    UE_Context data;
    struct Node *next;
} Node;

// Function to create and populate the linked list of LTE UE context structures
UE_Context* create_ue_contexts(int num_structures) {
    Node *head = NULL, *current = NULL;
    for (int i = 0; i < num_structures; i++) {
        UE_Context *ue_context = malloc(sizeof(UE_Context));
        if (!ue_context) {
            printf("Memory allocation failed.\n");
            return NULL;
        }

        // Retrieve UE information and RRC state values from external data source
        // ...

        Transmission_Parameters *params = malloc(sizeof(Transmission_Parameters));
        if (!params) {
            printf("Memory allocation failed.\n");
            free(ue_context);
            return NULL;
        }

        ue_context->ue_id = i;
        ue_context->rrc_state = 0; // Set RRC state value
        ue_context->params = params;

        Node *new_node = malloc(sizeof(Node));
        if (!new_node) {
            printf("Memory allocation failed.\n");
            free(ue_context);
            free(params);
            return NULL;
        }

        new_node->data = *ue_context;
        new_node->next = current;
        current = new_node;

        if (i == 0)
            head = current;
    }

    UE_Context *last_ue_context = NULL;
    Node *last_node = NULL;
    for (current = head; current; current = current->next) {
        last_ue_context = &current->data;
        last_node = current;
    }

    free(last_node);
    return last_ue_context;
}
