#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define the LTE UE Context structure
typedef struct {
    int ue_id;
    char tac[4];
    RRC_Connection_Info_t rrc_connection_info;
} LTE_UERadioContext_t;

// Define the RRC Connection Information structure
typedef struct {
    int cell_id;
    double serving_frequency;
} RRC_Connection_Info_t;

LTE_UERadioContext_t* create_ue_contexts_from_csv(const char* csv_file_path, int N) {
    FILE* fp = fopen(csv_file_path, "r");
    if (!fp) {
        return NULL; // Return error code
    }

    LTE_UERadioContext_t* ue_contexts = (LTE_UERadioContext_t*)malloc(N * sizeof(LTE_UERadioContext_t));
    if (!ue_contexts) {
        fclose(fp);
        return NULL; // Return error code
    }

    char line[1024];
    int i;
    for (i = 0; i < N; i++) {
        fgets(line, 1024, fp);
        char* token = strtok(line, ",");
        if (!token) {
            fclose(fp);
            free(ue_contexts);
            return NULL; // Return error code
        }
        ue_contexts[i].ue_id = atoi(token);

        token = strtok(NULL, ",");
        if (!token) {
            fclose(fp);
            free(ue_contexts);
            return NULL; // Return error code
        }
        sprintf(ue_contexts[i].tac, "%s", token);

        RRC_Connection_Info_t* rrc_connection_info = &ue_contexts[i].rrc_connection_info;
        token = strtok(NULL, ",");
        if (!token) {
            fclose(fp);
            free(ue_contexts);
            return NULL; // Return error code
        }
        rrc_connection_info->cell_id = atoi(token);

        token = strtok(NULL, ",");
        if (!token) {
            fclose(fp);
            free(ue_contexts);
            return NULL; // Return error code
        }
        rrc_connection_info->serving_frequency = atof(token);
    }

    fclose(fp);
    return ue_contexts;
}

int main() {
    int N = 1000;
    LTE_UERadioContext_t* ue_contexts = create_ue_contexts_from_csv("ue_contexts.csv", N);
    if (!ue_contexts) {
        printf("Error reading CSV file\n");
    } else {
        // Process the UE contexts
        for (int i = 0; i < N; i++) {
            printf("%d: TAC=%s, Cell ID=%d, Serving Frequency=%.2f\n",
                   ue_contexts[i].ue_id,
                   ue_contexts[i].tac,
                   ue_contexts[i].rrc_connection_info.cell_id,
                   ue_contexts[i].rrc_connection_info.serving_frequency);
        }
        free(ue_contexts);
    }

    return 0;
}
```']

