// Structure representing an LTE UE Context
typedef struct {
    int ue_id;
    int cell_id;
    time_t last_updated;
    struct rrc_conn_reconfig *rrc_msgs; // List of RRC Connection Reconfiguration messages
} lte_ue_context;

// Function to create and populate a list of LTE UE Context structures
int create_lte_ue_context_list(int num_ue, lte_ue_context **ue_context_list) {
    int i;
    for (i = 0; i < num_ue; i++) {
        lte_ue_context *ue_ctx = malloc(sizeof(lte_ue_context));
        if (!ue_ctx) {
            return -1; // Memory allocation failed
        }

        ue_ctx->ue_id = i + 1; // Assign valid UE ID
        ue_ctx->cell_id = i % 10; // Assign a random cell ID
        ue_ctx->last_updated = time(NULL); // Set the last updated timestamp

        // Allocate memory for RRC Connection Reconfiguration messages
        int num_rrc_msgs = i + 1;
        ue_ctx->rrc_msgs = malloc(num_rrc_msgs * sizeof(struct rrc_conn_reconfig));
        if (!ue_ctx->rrc_msgs) {
            free(ue_ctx); // Free partially allocated resources
            return -2; // Memory allocation failed for RRC messages
        }

        // Initialize the list of RRC Connection Reconfiguration messages
        for (int j = 0; j < num_rrc_msgs; j++) {
            ue_ctx->rrc_msgs[j].timestamp = time(NULL);
            ue_ctx->rrc_msgs[j].msg_type = j % 3; // Assign a random message type
        }

        *ue_context_list = realloc(*ue_context_list, (i + 1) * sizeof(lte_ue_context *));
        (*ue_context_list)[i] = ue_ctx;
    }

    return 0; // Success
}
