    }

    // In-place quicksort
    int pivot_index = n / 2;
    qsort(*list, n, sizeof(NFAPI_CRC_INDICATION_PDU_T), (int (*)(const void *, const void *))compare);

    free(*list);
}

int compare(const void *a, const void *b) {
    NFAPI_CRC_INDICATION_PDU_T *pdu_a = (NFAPI_CRC_INDICATION_PDU_T *)a;
    NFAPI_CRC_INDICATION_PDU_T *pdu_b = (NFAPI_CRC_INDICATION_PDU_T *)b;

    if (pdu_a->RNTI < pdu_b->RNTI) {
        return -1;
    } else if (pdu_a->RNTI > pdu_b->RNTI) {
        return 1;
    } else {
        return 0;
    }
}
