} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu_list(int n, int max_size) {
    NFAPI_CRC_INDICATION_PDU_T* list = NULL;
    int i, rnti[1000];

    srand(time(NULL)); // Seed the random number generator
    for (i = 0; i < max_size; i++) {
        if ((list = realloc(list, (i + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T))) == NULL) {
            return NULL; // Handle memory allocation failure gracefully
        }
    }

    for (i = 0; i < n && i < max_size; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        do {
            pdu.RNTI = rand() % 1000; // Generate a random RNTI
        } while (find_rnti(rnti, i + 1, pdu.RNTI) >= 0); // Ensure no duplicate RNTIs

        pdu.RX_UE_INFORMATION_TAG = rand() % 1000;
        pdu.CRC_INDICATION_REL8_TAG = rand() % 1000;
        pdu.CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1

        list[i].RX_UE_INFORMATION_TAG = pdu.RX_UE_INFORMATION_TAG;
        list[i].RNTI = pdu.RNTI;
        list[i].CRC_INDICATION_REL8_TAG = pdu.CRC_INDICATION_REL8_TAG;

        rnti[i] = pdu.RNTI; // Store the RNTIs for checking duplicates
    }

    return list;
}

int find_rnti(int* rntis, int n, int target) {
    int i;
    for (i = 0; i < n; i++) {
        if (rntis[i] == target) {
            return i; // Return the index of the found RNTI
        }
    }
    return -1; // Return -1 if the target RNTI is not found
}

int main() {
