    NFAPI_CRC_INDICATION_PDU_T* list = create_crc_indication_pdu_list(n, 1000);

    if (list == NULL) {
        printf("Error: Memory allocation failed.\n");
    } else {
        int i;
        for (i = 0; i < n; i++) {
            printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d\n", list[i].RX_UE_INFORMATION_TAG, list[i].RNTI, list[i].CRC_INDICATION_REL8_TAG);
        }
    }

    return 0;
}
