#define MAX_STRUCTURES 1000
#define RATE_LIMIT_PER_SECOND 10
#define RATE_LIMIT_PER_MINUTE 100

typedef struct {
    int rnti;
    int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
int structures_in_pool = 0;
int rate_limit_per_second = RATE_LIMIT_PER_SECOND;
int rate_limit_per_minute = RATE_LIMIT_PER_MINUTE;
int pool_size = MAX_STRUCTURES;
int current_rate = 0;

void* allocate_structure(void* unused) {
    NFAPI_CRC_INDICATION_PDU_T* structure = malloc(sizeof(NFAPI_CRC_INDATION_PDU_T));
    if(structure == NULL) {
        LOG_ERROR("Failed to allocate memory");
        return NULL;
    }
    pthread_mutex_lock(&lock);
    structures_in_pool++;
    pthread_mutex_unlock(&lock);
    return structure;
}

void deallocate_structure(void* ptr) {
    free(ptr);
    pthread_mutex_lock(&lock);
    structures_in_pool--;
    pthread_mutex_unlock(&lock);
}

void populate_list(int num_structures, int rnti_start, int rnti_end) {
    for (int i = 0; i < num_structures; i++) {
        NFAPI_CRC_INDICATION_PDU_T* structure = allocate_structure(NULL);
        if(structure == NULL) continue;
        structure->rnti = rand() % (rnti_end - rnti_start + 1) + rnti_start;
        int crcflag = rand() % 2; // randomly set CRCFLAG
        structure->crcflag = crcflag;
        pthread_mutex_lock(&lock);
        if(structures_in_pool >= pool_size) {
            LOG_ERROR("Pool is full, rate limiting exceeded");
            break;
        }
        pthread_cond_signal(&cond);
        pthread_mutex_unlock(&lock);
    }
}

void* process_structure(void* ptr) {
    NFAPI_CRC_INDICATION_PDU_T* structure = (NFAPI_CRC_INDICATION_PDU_T*)ptr;
    // process the structure here
    return NULL;
}

int main() {
    srand(time(NULL));
    pthread_t threads[MAX_STRUCTURES];
    for(int i = 0; i < MAX_STRUCTURES; i++) {
        if(pthread_create(&threads[i], NULL, process_structure, allocate_structure(NULL))) {
            LOG_ERROR("Failed to create thread");
            return 1;
        }
    }
    // wait for all threads to finish
    for(int i = 0; i < MAX_STRUCTURES; i++) {
        pthread_join(threads[i], NULL);
    }
    return 0;
}
