// Define the structure for LTE UE Context
typedef struct {
    int ue_id;
    int rnti;
    int crc_flag;
} lte_ue_context_t;

// Function to create and populate a list of LTE UE Context structures
int create_ue_context_list(int num_ue, FILE* log_file) {
    // Initialize the number of UE Contexts created
    int total_ue = 0;

    // Initialize the pointer to the head of the linked list
    lte_ue_context_t* head = NULL;
    lte_ue_context_t** tail = &head;

    for (int i = 0; i < num_ue; i++) {
        // Allocate memory for a new UE Context structure
        lte_ue_context_t* ue = (lte_ue_context_t*)malloc(sizeof(lte_ue_context_t));
        if (!ue) {
            fprintf(stderr, "Memory allocation failed.\n");
            return -1;
        }

        // Set the UE ID, RNTI, and CRC FLAG randomly
        srand(time(NULL));
        ue->ue_id = rand() % 1000 + 1;
        ue->rnti = (rand() % 65536) | 0x0001; // Ensure valid RNTI range (0x0001 to 0xFFFF)
        ue->crc_flag = rand() & 1;

        // Log the UE Context details
        fprintf(log_file, "UE ID: %d, RNTI: %x, CRC FLAG: %d\n", ue->ue_id, ue->rnti, ue->crc_flag);

        // Add the new UE Context to the linked list
        *tail = ue;
        tail = &((*tail)->next);
    }

    return total_ue;
}
