    node->data = data;
    node->prev = NULL;
    node->next = NULL;
    return node;
}

void insert_node(List* list, Node* node) {
    pthread_mutex_lock(&list->lock);

    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        node->prev = list->tail;
        list->tail->next = node;
        list->tail = node;
    }

    list->length++;
    pthread_mutex_unlock(&list->lock);
}

void free_list(List* list) {
    Node* current = list->head;
    Node* next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
