typedef struct {
    int rx_ue_info_tag;
    int rnti;
    unsigned char crc_flag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_crc_indications(int num_pds, int* error_code) {
    NFAPI_CRC_INDICATION_PDU_T* pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_pds * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        *error_code = 1;
        return NULL;
    }

    for (int i = 0; i < num_pds; i++) {
        pdus[i].rx_ue_info_tag = rand() % 100 + 1;
        pdus[i].rnti = rand() % 1000 + 1;
        pdus[i].crc_flag = rand() % 2 ? 0 : 1;
    }

    return pdus;
}

unsigned char** resolve_dns(const char* hostnames[], int num_hostnames, int* error_code) {
    unsigned char** ip_addresses = (unsigned char**)malloc(num_hostnames * sizeof(unsigned char*));
    if (!ip_addresses) {
        *error_code = 2;
        return NULL;
    }

    for (int i = 0; i < num_hostnames; i++) {
        struct sockaddr_in sin;
        struct hostent* he;

        if ((he = gethostbyname(hostnames[i])) == NULL) {
            *error_code = 3;
            return NULL;
        }

        ip_addresses[i] = (unsigned char*)malloc(INET_ADDRSTRLEN);
        inet_ntop(AF_INET, &he->h_addr, ip_addresses[i], INET_ADDRSTRLEN);
    }

    return ip_addresses;
}

int main() {
    int num_pds = 10;
    int* error_code = NULL;

    NFAPI_CRC_INDICATION_PDU_T* crc_indications = create_crc_indications(num_pds, &error_code);

    if (!crc_indications) {
        printf("Error creating CRC indications: %d\n", *error_code);
        return 1;
    }

    const char* hostnames[] = {"www.example.com", "example.net", "localhost"};
    int num_hostnames = sizeof(hostnames) / sizeof(char*);

    unsigned char** ip_addresses = resolve_dns(hostnames, num_hostnames, &error_code);

    if (!ip_addresses) {
        printf("Error resolving DNS: %d\n", *error_code);
        return 1;
    }

    // Use crc_indications and ip_addresses as needed

    free(crc_indications);
    for (int i = 0; i < num_hostnames; i++) {
        free(ip_addresses[i]);
    }
    free(ip_addresses);

    return 0;
}
