// Define the structure for LTE UE Context
typedef struct {
    int ue_id;
    int cell_id;
    int signal_strength;
} LteUeContext;

// Define the structure for Cell context
typedef struct {
    int cell_id;
    time_t expiration_time;
    // List of UE contexts for this cell
    LteUeContext **ue_contexts;
    int num_ue_contexts;
} LteCellContext;

// Function to create and populate a list of LTE UE Context structures
LteCellContext *create_cell_context(int cell_id, time_t expiration_time) {
    LteCellContext *cell_ctx = (LteCellContext *)malloc(sizeof(LteCellContext));
    cell_ctx->cell_id = cell_id;
    cell_ctx->expiration_time = expiration_time;
    cell_ctx->num_ue_contexts = 0;
    return cell_ctx;
}

// Function to add a UE context to the corresponding cell
void add_ue_context(LteCellContext *cell_ctx, LteUeContext *ue_ctx) {
    cell_ctx->ue_contexts = (LteUeContext **)realloc(cell_ctx->ue_contexts, sizeof(LteUeContext *)*(cell_ctx->num_ue_contexts + 1));
    cell_ctx->ue_contexts[cell_ctx->num_ue_contexts] = ue_ctx;
    cell_ctx->num_ue_contexts++;
}

// Function to clean up expired UE contexts
void cleanup_expired_ue_contexts(LteCellContext *cell_ctx, time_t current_time) {
    int i;
    for (i = 0; i < cell_ctx->num_ue_contexts; i++) {
        if (current_time > cell_ctx->ue_contexts[i]->expiration_time) {
            free(cell_ctx->ue_contexts[i]);
            memmove(&cell_ctx->ue_contexts[i], &cell_ctx->ue_contexts[i + 1], sizeof(LteUeContext *)*(cell_ctx->num_ue_contexts - i - 1));
            cell_ctx->num_ue_contexts--;
        }
    }
}

// Function to serialize the list of UE contexts
void serialize_ue_contexts(const LteCellContext *cell_ctx, FILE *file) {
    int i;
    for (i = 0; i < cell_ctx->num_ue_contexts; i++) {
        fwrite(&cell_ctx->ue_contexts[i]->ue_id, sizeof(int), 1, file);
        fwrite(&cell_ctx->ue_contexts[i]->cell_id, sizeof(int), 1, file);
        fwrite(&cell_ctx->ue_contexts[i]->signal_strength, sizeof(int), 1, file);
    }
}

// Function to deserialize the list of UE contexts
void deserialize_ue_contexts(LteCellContext *cell_ctx, FILE *file) {
    int i;
    for (i = 0; i < cell_ctx->num_ue_contexts; i++) {
        LteUeContext *ue_ctx = (LteUeContext *)malloc(sizeof(LteUeContext));
        fread(&ue_ctx->ue_id, sizeof(int), 1, file);
        fread(&ue_ctx->cell_id, sizeof(int), 1, file);
        fread(&ue_ctx->signal_strength, sizeof(int), 1, file);
        add_ue_context(cell_ctx, ue_ctx);
    }
}

int main() {
    // Initialize the random number generator
    srand(time(NULL));

    LteCellContext *cell_ctx = create_cell_context(1, time(NULL) + 3600); // Create a cell context with ID 1 and expiration time 1 hour from now

    for (int i = 0; i < 10; i++) {
        LteUeContext *ue_ctx = (LteUeContext *)malloc(sizeof(LteUeContext));
        ue_ctx->ue_id = rand();
        ue_ctx->cell_id = 1;
        ue_ctx->signal_strength = rand() % 100 + 1;
        add_ue_context(cell_ctx, ue_ctx);
    }

    // Periodically clean up expired UE contexts
    time_t current_time = time(NULL);
    while (current_time < cell_ctx->expiration_time) {
        cleanup_expired_ue_contexts(cell_ctx, current_time);
        sleep(60); // Sleep for 1 minute before checking again
        current_time = time(NULL);
    }

    // Serialize the list of UE contexts to a file
    FILE *file = fopen("ue_contexts.bin", "wb");
    serialize_ue_contexts(cell_ctx, file);
    fclose(file);

    return 0;
}
