    FILE* fp = fopen("crc_indication_pdu_list.bin", "wb");

    if (!fp) return -1;

    // Serialize each structure in the list
    for (int i = 0; i < num_elements; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = list[i];

        fwrite(&pdu->rx_ue_info_tag, sizeof(int), 1, fp);
        fwrite(&pdu->rnti, sizeof(int), 1, fp);
        fwrite(&pdu->crcflag, sizeof(enum {CRCFLAG_ON, CRCFLAG_OFF}), 1, fp);
    }

    fclose(fp);

    return 0;
}

