function traverseDOMTree(node, selector, sizeLimit, allowedChars) {
    let result = [];
    let stack = [node];

    while (stack.length > 0) {
        node = stack.pop();
        if (node && node.classList && Array.from(node.classList).some(cls => selector === cls)) {
            result.push(node);
        }
        for (let child of node.childNodes) {
            stack.push(child);
        }
    }

    let inputStr = '';
    for (let elem of result) {
        inputStr += elem.id || '';
    }

    if (inputStr.length <= sizeLimit && allowedChars.includesEvery(charCode)) {
        return inputStr + '/';
    } else {
        return '';
    }
}

function charCodeToAllowed(allowedChars) {
    let set = new Set();
    for (let char of allowedChars) {
        set.add(char.charCodeAt(0));
    }
    return set;
}
