    ctx_mgr->max_active_contexts = atoi(getenv("MAX_ACTIVE_CONTEXTS"));
    ctx_mgr->num_active_contexts = 0;
    ctx_mgr->cleanup_interval = atoi(getenv("CLEANUP_INTERVAL"));
    ctx_mgr->retry_timeout = atoi(getenv("RETRY_TIMEOUT"));
    pthread_mutex_init(&ctx_mgr->lock, NULL);
    return (void*)ctx_mgr;
}

