    LTE_UERadioAccessBearerContext* merged_ue_contexts = (LTE_UERadioAccessBearerContext*)malloc((size1 + size2) * sizeof(LTE_UERadioAccessBearerContext));
    for (int i = 0; i < size1; i++) {
        memcpy(&merged_ue_contexts[i], &ue_contexts1[i], sizeof(LTE_UERadoAccessBearerContext));
