                    memcpy(&merged_ue_contexts[j], &ue_contexts2[i], sizeof(LTE_UERadioAccessBearerContext));
                    found = 1;
                    break;
                }
            }
        }
        if (!found) {
            memcpy(&merged_ue_contexts[size1 + i], &ue_contexts2[i], sizeof(LTE_UERadoAccessBearerContext));
        }
    }
