#include <time.h>

typedef struct {
    int val;
} record;

int allocate_memory(int max_size, int min_val, int max_val) {
    if (max_size < 2) {
        return -1; // error: invalid max_size value
    }

    int* offsets = (int*)malloc(max_size * sizeof(int));
    if (!offsets) {
        return -1; // error: memory allocation failed for offsets
    }

    int* keys = (int*)malloc(max_size * sizeof(int));
    if (!keys) {
        free(offsets);
        return -1; // error: memory allocation failed for keys
    }

    record* records = (record*)malloc((max_size / 2) * sizeof(record));
    if (!records) {
        free(offsets);
        free(keys);
        return -1; // error: memory allocation failed for records
    }

    srand(time(NULL)); // initialize random number generator

    // generate unique offsets and keys
    int offset_val = rand();
    for (int i = 0; i < max_size; i++) {
        offsets[i] = offset_val++;
        if (i >= max_size - 1) {
            offset_val = rand();
        }
    }

    int key_val = rand();
    for (int i = 0; i < max_size; i++) {
        keys[i] = key_val++;
        if (i >= max_size - 1) {
            key_val = rand();
        }
    }

    // generate unique record values
    int record_val = rand() % (max_val - min_val + 1);
    for (int i = 0; i < max_size / 2; i++) {
        records[i].val = record_val++;
        if (i >= max_size / 2 - 1) {
            record_val = rand() % (max_val - min_val + 1);
        }
    }

    return 0; // success
}

int main() {
    int max_size = 100;
    int min_val = 10;
    int max_val = 50;

    if (allocate_memory(max_size, min_val, max_val) != 0) {
        printf("Error allocating memory.\n");
    } else {
        printf("Memory allocated successfully!\n");
    }

    return 0;
}
