                              LTE_Ue_Context **ue_contexts2, int num_ue_contexts2,
                              LTE_Ue_Context ***merged_ue_contexts) {
    for (int i = 0; i < num_ue_contexts2; i++) {
        bool found = false;
        for (int j = 0; j < num_ue_contexts1; j++) {
            if ((*ue_contexts1)[j]->ue_id == (*ue_contexts2)[i]->ue_id) {
                found = true;
                if ((*ue_contexts1)[j]->signal_strength < (*ue_contexts2)[i]->signal_strength) {
                    free((*ue_contexts1)[j]);
                    memmove(&(*ue_contexts1)[j], &(*ue_contexts1)[j + 1], (num_ue_contexts1 - j - 1) * sizeof(LTE_Ue_Context *));
                    (*num_ue_contexts1)--;
                    j--;
                }
            }
        }
        if (!found) {
            (*num_ue_contexts1)++;
            (*merged_ue_contexts) = realloc((*merged_ue_contexts), (*num_ue_contexts1 + 1) * sizeof(LTE_Ue_Context *));
            (*merged_ue_contexts)[*num_ue_contexts1 - 1] = malloc(sizeof(LTE_Ue_Context));
            memcpy(&(*merged_ue_contexts)[*num_ue_contexts1 - 1], &(*ue_contexts2)[i], sizeof(LTE_Ue_Context));
