void add_measurement_report(Measurement_Report_List *list, int ue_id, int rsrp, int rsrq, int sinr) {
    if (rsrp < -140 || rsrp > -50 || rsrq < -3 || rsrq > 3 || sinr < -20 || sinr > 20) {
        return; // Invalid measurement report
    }

    LTE_PHY_Measurement_Report *report = malloc(sizeof(LTE_PHY_Measurement_Report));
    if (report == NULL) {
        return; // Memory allocation failed
    }
    report->ue_id = ue_id;
    report->rsrp = rsrp;
    report->rsrq = rsrq;
    report->sinr = sinr;
    time_t timestamp = time(NULL);
    report->timestamp = timestamp;

    if (list->count == list->capacity) {
        // Resize the list
        size_t new_capacity = list->capacity == 0 ? 1 : list->capacity * 2;
        LTE_PHY_Measurement_Report **new_reports = realloc(list->reports, new_capacity * sizeof(LTE_PHY_Measurement_Report *));
        if (new_reports == NULL) {
            free(report);
            return; // Memory allocation failed
        }
        list->reports = new_reports;

        for (size_t i = list->capacity; i < new_capacity; i++) {
            new_reports[i] = NULL;
        }

        list->capacity = new_capacity;
    }

    if (list->count >= list->capacity) {
        // Reallocate reports
        LTE_PHY_Measurement_Report **new_reports = malloc((list->capacity * 2) * sizeof(LTE_PHY_Measurement_Report *));
        for (size_t i = 0; i < list->capacity; i++) {
            new_reports[i] = list->reports[i];
        }
        free(list->reports);
        list->reports = new_reports;
        list->capacity *= 2;
    }

    if (list->count >= list->capacity) {
        // Reallocate reports
        LTE_PHY_Measurement_Report **new_reports = malloc((list->capacity * 2) * sizeof(LTE_PHY_Measurement_Report *));
        for (size_t i = 0; i < list->capacity; i++) {
            new_reports[i] = list->reports[i];
        }
        free(list->reports);
        list->reports = new_reports;
        list->capacity *= 2;
    }

    report->next = NULL;

    if (list->count == 0) {
        list->reports[0] = report;
    } else {
        for (size_t i = 0; i < list->capacity - 1; i++) {
            if (list->reports[i]->next == NULL) {
                list->reports[i]->next = report;
                break;
            }
        }
    }

    list->count++;
}
