import json

class JSONEncoder:
    def __init__(self):
        self.registry = {}

    def encode(self, data):
        return json.dumps(data)

    def decode(self, json_data):
        try:
            return json.loads(json_data)
        except json.JSONDecodeError as e:
            print(f"Failed to parse JSON: {e}")
            return None

    def add_factory_function(self, id, factory_func):
        self.registry[id] = factory_func

    def create_instance_from_json(self, json_data, id):
        data = self.decode(json_data)
        if not data:
            return None
        return self.registry.get(id, lambda x: None)(data)

    def to_json_string(self, obj):
        return json.dumps(obj)
