// Union-Find data structure for RNTI values
int* parent;
int* rank;

void make_set(int x) {
    parent[x] = x;
}

int find(int x) {
    if (parent[x] != x)
        return find(parent[x]);
    return x;
}

void union_sets(int x, int y) {
    int root_x = find(x);
    int root_y = find(y);
    if (root_x == root_y)
        return;
    if (rank[root_x] < rank[root_y])
        parent[root_x] = root_y;
    else
        parent[root_y] = root_x;
    if (rank[root_x] == rank[root_y]) {
        rank[root_x]++;
        rank[root_y]++;
    }
}

// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
void populate_NFAPI_CRC_INDICATION_PDU_T(int n, int* RNTI_values, int* CRC_flags, int** list) {
    // Initialize Union-Find data structure
    parent = (int*)malloc((n + 1)*sizeof(int));
    rank = (int*)malloc((n + 1)*sizeof(int));
    for (int i = 0; i <= n; i++) {
        make_set(i);
    }

    // Create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
    *list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n*sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < n; i++) {
        (*list)[i].RX_UE_INFORMATION_TAG = rand() % 100;
        (*list)[i].RNTI = RNTI_values[i];
        if ((int)rand()/RAND_MAX > 0.5)
            (*list)[i].CRCFLAG = CRC_flags[i];
        else
            (*list)[i].CRCFLAG = (1 << 31);

        // Check for disjointness among the RNTI values using Union-Find data structure
        int current_RNTI = find((*list)[i].RNTI);
        for (int j = i - 1; j >= 0; j--) {
            if (find(RNTI_values[j]) == current_RNTI) {
                union_sets(RNTI_values[i], RNTI_values[j]);
                break;
            }
        }
    }

    // Free memory allocated for Union-Find data structure
    free(parent);
    free(rank);
}

int main() {
    int n = 10;  // Number of NFAPI_CRC_INDICATION_PDU_T structures to create
    int RNTI_values[n];  // Array of RNTI values
    int CRC_flags[n];  // Array of CRC flags

