// Function to find the largest integer in an array
int find_largest(int arr[], int size) {
    int max_val = arr[0];
    int i;
    for (i = 1; i < size; i++) {
        if (arr[i] > max_val)
            max_val = arr[i];
    }
    return max_val;
}

// Function to read integers from standard input
int* read_integers(int *max_size) {
    int i, num_read = 0;
    int *input_ints = NULL;

    // Read integers until the maximum size is reached or end-of-file is encountered
    while (num_read < *max_size && scanf("%d", &i) == 1) {
        if (input_ints == NULL) {
            input_ints = (int *)malloc((num_read + 2) * sizeof(int));
            input_ints[num_read] = i;
        } else {
            input_ints = (int *)realloc(input_ints, (num_read + 2) * sizeof(int));
            input_ints[num_read] = i;
        }
        num_read++;
    }

    // If the maximum size was not reached, free allocated memory
    if (num_read < *max_size) {
        free(input_ints);
        return NULL;
    } else {
        *max_size = num_read;
        return input_ints;
    }
}

int main() {
    int max_size = 1000;
    lte_ue_context **ue_contexts;
    int *input_ints;

    // Generate and populate a list of LTE UE Context structures
    ue_contexts = create_and_populate_lte_ue_contexts(max_size);

    // Read integers from standard input
    input_ints = read_integers(&max_size);

    // Find the largest integer in the array
    int max_val = find_largest(input_ints, max_size);

    printf("The largest integer is %d.\n", max_val);

    // Free allocated memory
    for (int i = 0; i < max_size; i++) {
        free(ue_contexts[i]);
    }
    free(ue_contexts);
    free(input_ints);

    return 0;
}
