    new->next = NULL;
    new->prev = &ue_ctx->nas_messages_list;
    ue_ctx->nas_messages_list.prev = new;
    new->prev = NULL;
    *(struct list_head**)&new->next = &ue_ctx->nas_messages_list;
    ue_ctx->nas_messages_list.next = new;

    // Add the NAS message to the linked list
    nas_msg->next = NULL;
    nas_msg->prev = new;
    new->next = nas_msg;
    nas_msg->prev = &new->next;
}

