        list[i].rx_ue_info_tag.crcflag = rand() & 1;

        list[i].crc_indication_rel8_tag.crc = rand();
    }

    // Serialize the list to a binary file
    binary_file = fopen("output.bin", "wb");
    if (!binary_file) {
        log_message(1, "Failed to open output.bin for writing");
        return 1;
    }

    fwrite(&n, sizeof(int), 1, binary_file);
    for (int i = 0; i < n; i++) {
        fwrite(&list[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, binary_file);
    }
    fclose(binary_file);

    // Free memory
    free(list);

    return 0;
}
