import subprocess
import json

def modify_kickstart_config(config_file_path, placeholders_dict):
    # Open the configuration file for reading
    with open(config_file_path, 'r') as config_file:
        config_contents = config_file.read()

    # Create a new configuration file for writing
    new_config_file_path = f"{config_file_path}.modified"
    with open(new_config_file_path, 'w') as new_config_file:
        for key, value in placeholders_dict.items():
            # Replace the placeholder with the actual value
            config_contents = config_contents.replace(f"<{key}>", str(value))

        # Add a new line with an encrypted password
        new_config_file.write(f"encrypted_password: <encrypted_password>\n")

    # Run sed commands to modify the configuration file
    for command in [
        f"s/{placeholders_dict['username']}/new_username/g",
        f"s/{placeholders_dict['password']}/new_password/g"
    ]:
        try:
            subprocess.run(f"sed -i '{command}' {config_file_path}", shell=True, check=True)
        except subprocess.CalledProcessError as e:
            raise Exception(f"sed command failed: {e}")

    # Replace the original configuration file with the modified one
    subprocess.run(f"mv {new_config_file_path} {config_file_path}", shell=True)

if __name__ == '__main__':
    config_file_path = 'kickstart.conf'
    placeholders_dict = {'username': 'old_username', 'password': 'old_password'}
    modify_kickstart_config(config_file_path, placeholders_dict)
