#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define a structure to store integers in a linked list
typedef struct Node {
    int data;
    struct Node* next;
} Node;

// Function to create a new node
Node* createNode(int value) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        printf("Memory error\n");
        exit(1);
    }
    newNode->data = value;
    newNode->next = NULL;
    return newNode;
}

// Function to insert a new node at the end of the linked list
void insertNode(Node** head, int value) {
    Node* newNode = createNode(value);
    if (*head == NULL) {
        *head = newNode;
    } else {
        Node* lastNode = *head;
        while (lastNode->next != NULL) {
            lastNode = lastNode->next;
        }
        lastNode->next = newNode;
    }
}

// Function to print the linked list
void printList(Node* head) {
    while (head != NULL) {
        printf("%d ", head->data);
        head = head->next;
    }
    printf("\n");
}

// Function to find and print the largest integer in the array
int largestInteger(int* arr, int size) {
    if (size == 0) {
        return -1; // Return a sentinel value indicating an empty array
    }

    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

// Function to calculate and print the average of all integers in the array
double averageInteger(int* arr, int size) {
    double sum = 0.0;
    for (int i = 0; i < size; i++) {
        sum += arr[i];
    }
    if (size > 0) {
        return sum / size;
    } else {
        return 0.0; // Return a sentinel value indicating an empty array
    }
}

// Main function to read and process the input
int main() {
    Node* head = NULL; // Initialize the linked list

    int n, max, avg;
    printf("Enter the number of integers: ");
    scanf("%d", &n);

    if (n > 10000) {
        printf("Error: Maximum allowed size exceeded.\n");
        exit(1);
    }

    int* arr = (int*)malloc(n * sizeof(int));
    if (!arr) {
        printf("Memory error\n");
        exit(1);
    }

    for (int i = 0; i < n; i++) {
        printf("Enter integer %d: ", i + 1);
        scanf("%d", &arr[i]);
        insertNode(&head, arr[i]);
    }

    max = largestInteger(arr, n);
    avg = averageInteger(arr, n);

    free(arr); // Free allocated memory

    if (head != NULL) {
        printf("Largest integer: %d\n", max);
        printf("Average integer: %.2f\n", avg);
        printList(head);
    } else {
        printf("No integers entered.\n");
    }

    return 0;
}

