void generate_lte_phy_msgs(int num_msgs, lte_phy_msg_t **lte_phy_msgs) {
    int i;
    srand(time(NULL)); // Initialize random seed

    // Interact with the external database to retrieve valid UE IDs and cell IDs
    FILE *db_file = fopen("database.txt", "r");
    if (db_file == NULL) {
        printf("Error: unable to open database file.\n");
        return;
    }

    int num_ue_ids, num_cell_ids;
    fscanf(db_file, "%d %d", &num_ue_ids, &num_cell_ids);
    int *ue_ids = (int *)malloc(num_ue_ids * sizeof(int));
    int *cell_ids = (int *)malloc(num_cell_ids * sizeof(int));

    for (i = 0; i < num_ue_ids; i++) {
        fscanf(db_file, "%d", &ue_ids[i]);
    }
    for (i = 0; i < num_cell_ids; i++) {
        fscanf(db_file, "%d", &cell_ids[i]);
    }

    fclose(db_file);

    // Create and populate the list of LTE PHY layer control messages
    *lte_phy_msgs = (lte_phy_msg_t *)malloc(num_msgs * sizeof(lte_phy_msg_t));
    for (i = 0; i < num_msgs; i++) {
        int ue_id_idx = rand() % num_ue_ids;
        int cell_id_idx = rand() % num_cell_ids;

        (*lte_phy_msgs)[i].ue_id = ue_ids[ue_id_idx];
        (*lte_phy_msgs)[i].cell_id = cell_ids[cell_id_idx];

        // Generate random DCI fields
