void create_pdu_list(int max_entries, int* consecutive_invalid_limit) {
    // Initialize the list and error count
    LTE_PHY_PDU** pdu_list = NULL;
    int error_count = 0;
    int current_consecutive_invalid = 0;

    // Get the maximum number of consecutive invalid entries from config file or env var
    *consecutive_invalid_limit = 5; // Default value

    for (int i = 0; i < max_entries; i++) {
        LTE_PHY_PDU* pdu = (LTE_PHY_PDU*)malloc(sizeof(LTE_PHY_PDU));
        if (!pdu) {
            printf("Error allocating memory.\n");
            break;
        }

        // Set valid TFCI and RI values
        pdu->L1_TFCI = rand() % 256;
        pdu->L1_RI = rand() % 16;

        // Randomly set HARQ status
        if (rand() % 2) {
            pdu->L1_HARQ = HARQ_ACK;
        } else {
            pdu->L1_HARQ = HARQ_NACK;

            // Increment error count and check for consecutive invalid entries
            error_count++;
            current_consecutive_invalid++;

            if (current_consecutive_invalid >= *consecutive_invalid_limit) {
                printf("Maximum consecutive invalid entries reached.\n");
                break;
            }
        }

        // Check if the TFCI and RI values are within their valid ranges
        if (pdu->L1_TFCI < 0 || pdu->L1_TFCI > 255 || pdu->L1_RI < 0 || pdu->L1_RI > 15) {
            printf("Invalid PDU entry.\n");
            error_count++;
        }

        // Add the PDU to the list
        if (!pdu_list) {
            pdu_list = (LTE_PHY_PDU**)malloc(sizeof(LTE_PHY_PDU*) * max_entries);
            pdu_list[i] = pdu;
        } else {
            int j;
            for (j = i; j > 0; j--) {
                pdu_list[j] = pdu_list[j - 1];
            }
            pdu_list[0] = pdu;
        }
    }

    // Clean up and print the error count
    if (pdu_list) {
        for (int i = 0; i < max_entries; i++) {
            free(pdu_list[i]);
        }
        free(pdu_list);
    }
    printf("Error count: %d\n", error_count);
}
