        pdu->rx_ue_info_tag = ((int*)external_data_source)[i % ((int*)external_data_source)[1]];
        pdu->rnti = ((int*)external_data_source)[i % ((int*)external_data_source)[2]];
        int crcflag = (pdu->rx_ue_info_tag & 0x1) | (pdu->rnti & 0x2);
        pthread_mutex_unlock(&mutex);

        if (pdu->rx_ue_info_tag < 0 || pdu->rx_ue_info_tag > 0xffffff || pdu->rnti < 0 || pdu->rnti > 0xffff) {
            free(pdu_array);
            return NULL;
        }
    }

    pthread_mutex_lock(&mutex);
    num_pdu_created = n;
    pthread_mutex_unlock(&mutex);

