#define TCP_CONNECTION_STRUCT_SIZE 256
#define MAX_TCP_CONNECTIONS 1024
#define LOGGING_LEVEL 3

typedef struct {
    char ip_address[16];
    int port_number;
    int connection_status; // 0 - not established, 1 - established
} tcp_connection_t;

void* tcp_connection_pool = NULL;
int tcp_connections_count = 0;

tcp_connection_t* create_tcp_connection(int seed) {
    tcp_connection_t* conn = (tcp_connection_t*)malloc(TCP_CONNECTION_STRUCT_SIZE);
    if (!conn) return NULL; // allocation failure

    srand(seed); // set random seed
    conn->port_number = rand() % 65535 + 1;
    conn->connection_status = rand() % 2;

    // generate random IP address
    const char* ip_addresses[] = {"192.168.1.1", "10.0.0.1", "172.16.254.1"};
    strcpy(conn->ip_address, ip_addresses[rand() % (sizeof(ip_addresses) / sizeof(ip_addresses[0]))]);

    return conn;
}

int populate_tcp_connections(int num_connections, int seed) {
    for (int i = 0; i < num_connections; i++) {
        tcp_connection_t* conn = create_tcp_connection(seed + i);
        if (!conn) {
            free(conn); // deallocate partial connections
            return -1; // allocation failure
        }
        // add connection to pool
        if (tcp_connections_count >= MAX_TCP_CONNECTIONS) {
            printf("TCP connection pool is full!\n");
            break;
        }
        conn->next = tcp_connection_pool;
        tcp_connection_pool = conn;
        tcp_connections_count++;
    }
    return 0; // success
}

void free_tcp_connections() {
    tcp_connection_t* current = tcp_connection_pool;
    while (current) {
        tcp_connection_t* next = current->next;
        free(current);
        current = next;
    }
    tcp_connection_pool = NULL;
    tcp_connections_count = 0;
}

int main(int argc, char** argv) {
    if (argc < 3) {
        printf("Usage: %s num_connections seed\n", argv[0]);
        return -1; // invalid input
    }

    int num_connections = atoi(argv[1]);
    int seed = atoi(argv[2]);

    if (populate_tcp_connections(num_connections, seed)) {
        printf("Error allocating TCP connections!\n");
        free_tcp_connections(); // clean up partial connections
        return -1;
    }

    printf("TCP connection pool created with %d structures.\n", num_connections);

    free_tcp_connections();

    return 0; // success
}
