#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_LIST_SIZE 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    char RNTI[8];
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *nfaList = NULL;
int nfaListSize = 0;
pthread_mutex_t nfaListMutex = PTHREAD_MUTEX_INITIALIZER;

void* allocateMemory(size_t size) {
    return malloc(size);
}

void freeMemory(void* ptr) {
    free(ptr);
}

int addNFAPI_CRC_INDICATION_PDU_T(NFAPI_CRC_INDICATION_PDU_T* newNFA, int rnti) {
    pthread_mutex_lock(&nfaListMutex);

    if (nfaListSize >= MAX_LIST_SIZE) {
        pthread_mutex_unlock(&nfaListMutex);
        return -1; // List full
    }

    NFAPI_CRC_INDICATION_PDU_T* temp = realloc(nfaList, sizeof(NFAPI_CRC_INDICATION_PDU_T)*(nfaListSize + 1));
    if (!temp) {
        freeMemory(nfaList);
        nfaList = NULL;
        pthread_mutex_unlock(&nfaListMutex);
        return -2; // Memory allocation failed
    }
    nfaList = temp;

    NFAPI_CRC_INDICATION_PDU_T* newNFAPI = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!newNFAPI) {
        freeMemory(newNFAPI);
        pthread_mutex_unlock(&nfaListMutex);
        return -2; // Memory allocation failed
    }
    memcpy(newNFAPI, newNFA, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    nfaList[nfaListSize] = *newNFAPI;
    if (rnti > 0) {
        qsort(nfaList, nfaListSize + 1, sizeof(NFAPI_CRC_INDICATION_PDU_T), compareNFA);
    }

    pthread_mutex_unlock(&nfaListMutex);

    return 0; // Success
}

int removeNFAPI_CRC_INDICATION_PDU_T(int rnti) {
    pthread_mutex_lock(&nfaListMutex);

    for (int i = nfaListSize - 1; i >= 0; i--) {
        if (strcmp(nfaList[i].RNTI, "") != 0 && strcmp(nfaList[i].RNTI, &rnti) == 0) {
            freeMemory(&nfaList[i]);
            memmove(&nfaList[i], &nfaList[i + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (nfaListSize - i - 1));
            nfaListSize--;
        }
    }

    pthread_mutex_unlock(&nfaListMutex);
    return 0; // Success
}

int compareNFA(const void* a, const void* b) {
    NFAPI_CRC_INDICATION_PDU_T* x = (NFAPI_CRC_INDICATION_PDU_T*)a;
    NFAPI_CRC_INDICATION_PDU_T* y = (NFAPI_CRC_INDICATION_PDU_T*)b;

    return strcmp(x->RNTI, y->RNTI);
}

void freeNfaList() {
    for (int i = 0; i < nfaListSize; i++) {
        freeMemory(&nfaList[i]);
    }
    freeMemory(nfaList);
    nfaList = NULL;
    nfaListSize = 0;
}
