#define MAX_LIST_SIZE 1000
#define CRCFLAG_MAX_VALUE 255

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG[CRCFLAG_MAX_VALUE];
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T* list = NULL;
int list_size = 0;

void* generate_pdu(void* data) {
    int i, j;
    for (i = 0; i < MAX_LIST_SIZE; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pthread_mutex_lock(&lock);
        if (list_size >= MAX_LIST_SIZE) {
            list = realloc(list, sizeof(NFAPI_CRC_INDATION_PDU_T) * (list_size + MAX_LIST_SIZE));
            if (!list) {
                perror("Memory allocation error");
                exit(1);
            }
        }
        pdu.RX_UE_INFORMATION_TAG = i;
        pdu.RNTI = i % 256;
        for (j = 0; j < CRCFLAG_MAX_VALUE; j++) {
            pdu.CRC_INDICATION_REL8_TAG[j] = rand() % 256;
        }
        list[list_size++] = pdu;
        pthread_mutex_unlock(&lock);
    }
    return NULL;
}

void* log_pdu(void* data) {
    FILE* file = fopen("pdu_log.txt", "a");
    if (!file) {
        perror("Error opening log file");
        return NULL;
    }
    for (int i = 0; i < list_size; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu = list[i];
        fprintf(file, "RX_UE_INFORMATION_TAG: %d\nRNTI: %d\n", pdu.RX_UE_INFORMATION_TAG, pdu.RNTI);
        for (int j = 0; j < CRCFLAG_MAX_VALUE; j++) {
            fprintf(file, "%d ", pdu.CRC_INDICATION_REL8_TAG[j]);
        }
        fprintf(file, "\n");
    }
    fclose(file);
    return NULL;
}

void create_pdu_list(int n) {
    pthread_t thread;
    int i;
    for (i = 0; i < n; i++) {
        pthread_create(&thread, NULL, generate_pdu, NULL);
        pthread_join(thread, NULL);
    }
    log_pdu(NULL);
}
