    pthread_mutex_t lock;
} DynamicList;

// Function to initialize a new dynamic list
DynamicList* dynamic_list_init(int initial_capacity) {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    list->size = 0;
    list->capacity = initial_capacity;
    list->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Function to add an element to the dynamic list
void dynamic_list_add(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&list->lock);
    if (list->size == list->capacity) {
        // Resize the list when it's full
        int new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        list->data = new_data;
        list->capacity = new_capacity;
    }
    list->data[list->size] = element;
    list->size++;
    pthread_mutex_unlock(&list->lock);
}

// Function to search for an element in the dynamic list
NFAPI_CRC_INDICATION_PDU_T* dynamic_list_search(DynamicList* list, int rnti) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->size; i++) {
        if (list->data[i].rnti == rnti) {
            NFAPI_CRC_INDICATION_PDU_T* element = &list->data[i];
            pthread_mutex_unlock(&list->lock);
            return element;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return NULL;
}

// Function to remove an element from the dynamic list
void dynamic_list_remove(DynamicList* list, int rnti) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->size; i++) {
        if (list->data[i].rnti == rnti) {
            // Shift elements down to fill the gap
            memmove(&list->data[i], &list->data[i + 1], (list->size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            list->size--;
            break;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

// Function to serialize the dynamic list to a file
void dynamic_list_serialize(DynamicList* list, FILE* file) {
    pthread_mutex_lock(&list->lock);
    fwrite(&list->size, sizeof(int), 1, file);
    for (int i = 0; i < list->size; i++) {
        fwrite(&list->data[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }
    pthread_mutex_unlock(&list->lock);
}

// Function to deserialize the dynamic list from a file
void dynamic_list_deserialize(DynamicList* list, FILE* file) {
    pthread_mutex_lock(&list->lock);
    fread(&list->size, sizeof(int), 1, file);
    list->data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, list->size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < list->size; i++) {
        fread(&list->data[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }
    pthread_mutex_unlock(&list->lock);
}

// Function to clear the dynamic list
void dynamic_list_clear(DynamicList* list) {
    pthread_mutex_lock(&list->lock);
    list->size = 0;
    pthread_mutex_unlock(&list->lock);
}
