        if (pthread_join(threads[i], NULL)) {
            printf("Error joining thread %d\n", i);
            return -1;
        }
    }

    pthread_attr_destroy(&attr);

    // Store PDUs in file or database
    FILE *file = fopen("pdu_data.txt", "w");
