#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define structures for NFAPI_CRC_INDICATION_PDU_T, RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a caching mechanism using a hash table with thread-safe locking
typedef struct {
    void **cache;
    pthread_mutex_t lock;
    size_t cache_size;
    size_t cache_capacity;
} Cache_t;

Cache_t *cache_init(size_t capacity) {
    Cache_t *cache = malloc(sizeof(Cache_t));
    cache->cache = calloc(capacity, sizeof(void *));
    cache->lock = PTHREAD_MUTEX_INITIALIZER;
    cache->cache_size = 0;
    cache->cache_capacity = capacity;
    return cache;
}

void cache_free(Cache_t *cache) {
    for (size_t i = 0; i < cache->cache_size; i++) {
        free(cache->cache[i]);
    }
    free(cache->cache);
    free(cache);
}

// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T *create_crc_indication_pdu_list(int n, Cache_t *cache) {
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < n; i++) {
        int RX_UE_INFORMATION_TAG = rand() % 100000;
        int RNTI = rand() % 100;

        // Check if the RX_UE_INFORMATION_TAG and RNTI are in the cache
        pthread_mutex_lock(&cache->lock);
        void *cached_data = NULL;
        for (size_t j = 0; j < cache->cache_size; j++) {
            if (*((int *)cache->cache[j]) == RX_UE_INFORMATION_TAG && *(int *)((char *)cache->cache[j] + sizeof(int)) == RNTI) {
                cached_data = cache->cache[j];
                break;
            }
        }
        pthread_mutex_unlock(&cache->lock);

        // If not in the cache, create a new entry and add it to the cache
        if (cached_data == NULL) {
            NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
            pdu->RNTI = RNTI;
            pdu->CRCFLAG = rand() % 2; // Randomly set CRCFLAG

            pthread_mutex_lock(&cache->lock);
            cache->cache[cache->cache_size++] = pdu;
            if (cache->cache_size >= cache->cache_capacity) {
                void **new_cache = realloc(cache->cache, (cache->cache_capacity * 2 + 1) * sizeof(void *));
                cache->cache = new_cache;
                cache->cache_capacity *= 2;
            }
            pthread_mutex_unlock(&cache->lock);
        } else {
            // If in the cache, use the cached data
            pdu_list[i].RX_UE_INFORMATION_TAG = *(int *)cached_data;
            pdu_list[i].RNTI = *(int *)((char *)cached_data + sizeof(int));
            pdu_list[i].CRCFLAG = rand() % 2; // Randomly set CRCFLAG for this PDU
        }
    }

    return pdu_list;
}

// Function to free the list of NFAPI_CRC_INDICATION_PDU_T structures
void free_crc_indication_pdu_list(NFAPI_CRC_INDICATION_PDU_T *pdu_list, int n) {
    for (int i = 0; i < n; i++) {
        free(&pdu_list[i]);
    }
    free(pdu_list);
}

int main() {
    Cache_t *cache = cache_init(100); // Initialize the cache with a capacity of 100 entries

    int n = 10; // Create a list of NFAPI_CRC_INDICATION_PDU_T structures with n elements
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = create_crc_indication_pdu_list(n, cache);

    // Use the pdu_list...

    free_crc_indication_pdu_list(pdu_list, n); // Free the list of NFAPI_CRC_INDICATION_PDU_T structures

    cache_free(cache); // Free the cache

    return 0;
}

