        nfapdu_list[i].rnti = rand() % 100;
        nfapdu_list[i].crc_flag = (rand() % 2) ? 0 : 1;
    }

    parse_input_file(input_file, num_nfapdu);

    if (output_file) {
        file = fopen(output_file, "w");
        if (!file) {
            syslog(LOG_ERR, "Error opening output file %s", output_file);
