    for (int i = 0; i < num_tbs; i++) {
        ue_ctx->tbs[i].tb_size = rand() % MAX_MEMORY / 2 + 1;
        ue_ctx->tbs[i].harq_initiated = rand() % 2;
    }

    return ue_ctx;
}

