        return;
    }

    if (ue_ctx->tbs) {
        free(ue_ctx->tbs);
    }
    free(ue_ctx);
}

int main() {
    size_t total_memory_usage = 0;
    LteUeContext *ue_ctxs[MAX_MEMORY / sizeof(LteUeContext)];
    int ue_count = 0;

    while (total_memory_usage <= MAX_MEMORY && ue_count < MAX_MEMORY / sizeof(LteUeContext)) {
        LteUeContext *new_ue_ctx = create_ue_context(NUM_TBS);
        if (!new_ue_ctx) {
            printf("Memory allocation failed!\n");
            break;
        }

        ue_ctxs[ue_count++] = new_ue_ctx;
        total_memory_usage += sizeof(LteUeContext) + NUM_TBS * sizeof(UplinkTb);
