// Function to create and populate a list of LTE UE Context structures
UEContext** create_ue_contexts(int num_ue, int max_rnti) {
    UEContext** ue_ctx_list = NULL;
    int* rnti_list = NULL;

    // Calculate the total memory needed for UE contexts
    size_t total_size = sizeof(UEContext*) * (num_ue + 1);

    // Allocate memory for the UE context list
    if ((ue_ctx_list = (UEContext**)malloc(total_size)) == NULL) {
        return NULL;  // Memory allocation failed
    }

    // Initialize the UE context list with null pointers
    memset(ue_ctx_list, 0, total_size);

    // Allocate memory for the RNTI list
    if ((rnti_list = (int*)malloc(sizeof(int) * max_rnti)) == NULL) {
        free(ue_ctx_list);  // Free allocated memory on error
        return NULL;
    }

    // Generate random UE IDs and RNTIs
    for (int i = 0; i < num_ue; i++) {
        ue_ctx_list[i] = (UEContext*)malloc(sizeof(UEContext));

        if (ue_ctx_list[i] == NULL) {
            return NULL;  // Memory allocation failed
        }

        ue_ctx_list[i]->ue_id = rand() % 100;
        rnti_list[i] = rand() % max_rnti;

        // Generate random downlink data payload
