    return context;
}

void free_ue_context(LTE_Ue_Context* context) {
    if (context == NULL)
        return;
    free(context->rrc_conn_setup_cmpt);
    free(context);
}

typedef struct {
    LTE_Ue_Context** list;
    int size;
} UE_Context_List;

UE_Context_List* create_ue_context_list() {
    UE_Context_List* list = (UE_Context_List*)malloc(sizeof(UE_Context_List));
    list->list = NULL;
    list->size = 0;
    return list;
}

void add_ue_context_to_list(UE_Context_List* list, LTE_Ue_Context* context) {
    if (list == NULL || context == NULL)
        return;

    // dynamically resize the list if necessary
    if (list->size >= list->size * 2) {
        list->list = realloc(list->list, (list->size * 2 + 1) * sizeof(LTE_Ue_Context*));
        list->size *= 2;
    }

    // add context to the end of the list
    list->list[list->size++] = context;
}

void free_ue_context_list(UE_Context_List* list) {
    if (list == NULL)
        return;

    for (int i = 0; i < list->size; i++) {
        free_ue_context(list->list[i]);
    }
    free(list->list);
    free(list);
}

