#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <pthread.h>

#define MAX_DEVICES 1000
#define BUFFER_SIZE_MIN 64
#define BUFFER_SIZE_MAX 4096

typedef struct {
    int device_id;
    char mac_address[18];
    char buffer[BUFFER_SIZE_MAX];
} DeviceContext;

DeviceContext *devices = NULL;
int num_devices = 0;
pthread_mutex_t devices_lock = PTHREAD_MUTEX_INITIALIZER;

void *device_context_new(int device_id, char *mac_address) {
    DeviceContext *new_device = (DeviceContext *)malloc(sizeof(DeviceContext));
    new_device->device_id = device_id;
    strcpy(new_device->mac_address, mac_address);
    // Initialize buffer with random payload
    int i;
    for (i = 0; i < BUFFER_SIZE_MAX; i++) {
        if (rand() % 2) {
            new_device->buffer[i] = '1';
        } else {
            new_device->buffer[i] = '0';
        }
    }
    return new_device;
}

int device_context_free(DeviceContext *device) {
    free(device);
    return 0;
}

void populate_devices(int num_configs, char **configs) {
    pthread_mutex_lock(&devices_lock);

    for (int i = 0; i < num_configs; i++) {
        DeviceContext *new_device = device_context_new(atoi(configs[i]), configs[i] + 17);
        devices[num_devices++] = new_device;
    }

    pthread_mutex_unlock(&devices_lock);
}

void free_devices() {
    for (int i = 0; i < num_devices; i++) {
        device_context_free(devices[i]);
    }
    free(devices);
    devices = NULL;
    num_devices = 0;
}

void *config_service_get_devices(void *arg) {
    // Call the external configuration service to retrieve the list of devices
    int num_configs, i;
    char **configs = config_service_get_config();
    num_configs = config_service_count_configs();

    if (num_configs > MAX_DEVICES) {
        printf("Error: Too many devices configured. Limit exceeded.\n");
        return NULL;
    }

    populate_devices(num_configs, configs);

    // Cache the device list locally
    pthread_mutex_lock(&devices_lock);
    for (i = 0; i < num_configs; i++) {
        config_service_update_cache(configs[i]);
    }
    pthread_mutex_unlock(&devices_lock);

    return NULL;
}

int main(int argc, char **argv) {
    int buffer_size;

    if (argc != 2 || strcmp(argv[1], "--help") == 0) {
        printf("Usage: %s <buffer-size>\n", argv[0]);
        return -1;
    }

    buffer_size = atoi(argv[1]);

    if (buffer_size < BUFFER_SIZE_MIN || buffer_size > BUFFER_SIZE_MAX) {
        printf("Error: Invalid buffer size. Must be between %d and %d.\n", 
            BUFFER_SIZE_MIN, BUFFER_SIZE_MAX);
        return -1;
    }

    pthread_t thread;

    // Start a separate thread to retrieve the device list from the external service
    pthread_create(&thread, NULL, config_service_get_devices, NULL);

    // Wait for the thread to complete before freeing the devices
    pthread_join(thread, NULL);

    free_devices();

    return 0;
}
```

Note that this code assumes the existence of `config_service_get_config`, `config_service_count_configs`, and `config_service_update_cache` functions that interact with the external configuration service. You may need to implement these functions according to your specific requirements.']

