#include <netinet/in.h>
#include <arpa/inet.h>

#define MAX_CONNECTIONS 1000
#define BUFFER_SIZE 1024

typedef struct {
    int id;
    char remote_ip[16];
    char* buffer;
} TCPConnection;

TCPConnection** connections = NULL;
int connection_count = 0;

void create_tcp_connections(int num_connections) {
    for (int i = 0; i < num_connections; i++) {
        TCPConnection* conn = (TCPConnection*)malloc(sizeof(TCPConnection));
        if (!conn) {
            printf("Error: Unable to allocate memory for TCP connection.\n");
            return;
        }

        conn->id = i + 1;
        inet_ntop(AF_INET, NULL, conn->remote_ip, sizeof(conn->remote_ip));
        conn->buffer = (char*)malloc(BUFFER_SIZE);
        if (!conn->buffer) {
            printf("Error: Unable to allocate memory for TCP connection buffer.\n");
            free(conn);
            return;
        }

        // Generate random payload
        srand(time(NULL));
        for (int j = 0; j < BUFFER_SIZE - 1; j++) {
            conn->buffer[j] = (char)(rand() % 256);
        }
        conn->buffer[BUFFER_SIZE - 1] = '\0';

        if (!connections) {
            connections = (TCPConnection**)malloc(sizeof(TCPConnection*) * MAX_CONNECTIONS);
            connection_count = 0;
        }

        connections[connection_count++] = conn;
    }
}

void log_connection_event(int id, int payload_size) {
    // Integrate with external logging system
    printf("Connection event logged: ID %d, Payload size %d\n", id, payload_size);
}

void release_tcp_connections() {
    for (int i = 0; i < connection_count; i++) {
        TCPConnection* conn = connections[i];
        free(conn->buffer);
        free(conn);
    }
    free(connections);
}
