                (*mme_ul_data_pdu_list)->pdus = &pdu;
            } else {
                *mme_ul_data_pdu_list = realloc(*mme_ul_data_pdu_list, sizeof(LTE_PHY_MME_UL_DATA_PDU_T) + (batch_size - 1) * sizeof(MME_UL_DATA_PDU_T));
                (*mme_ul_data_pdu_list)->num_pdus += batch_size;
                MME_UL_DATA_PDU_T* temp = &((*mme_ul_data_pdu_list)->pdus)[j];
                temp->ue_id = mme_ul_data_pdu->ue_id;
                temp->mac_ce = pdu.mac_ce;
                temp->crc = pdu.crc;
            }
        }
    }
