typedef struct {
    int ue_index;
    int cell_id;
    float rssi;
    float sinr;
    int cqi;
} measurement_report;

measurement_report* create_measurement_report(int ue_index, int cell_id) {
    measurement_report* report = (measurement_report*)malloc(sizeof(measurement_report));
    if (!report) return NULL;

    report->ue_index = ue_index;
    report->cell_id = cell_id;
    report->rssi = 0.0f; 
    report->sinr = 0.0f;
    report->cqi = 0;

    return report;
}

void free_measurement_report(measurement_report* report) {
    if (report) free(report);
}

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

measurement_report** lte_phy_measurements = NULL;
int num_measurements = 0;

void add_measurement(int ue_index, int cell_id, float rssi, float sinr, int cqi) {
    pthread_mutex_lock(&lock);

    measurement_report* report = create_measurement_report(ue_index, cell_id);
    if (!report) {
        pthread_mutex_unlock(&lock);
        return;
    }

    report->rssi = rssi; 
    report->sinr = sinr;
    report->cqi = cqi;

    if (num_measurements == 0) {
        lte_phy_measurements = (measurement_report**)malloc(sizeof(measurement_report*));
        if (!lte_phy_measurements) {
            free_measurement_report(report);
            pthread_mutex_unlock(&lock);
            return;
        }
    } else {
        measurement_report** new_measurements = (measurement_report**)realloc(lte_phy_measurements, sizeof(measurement_report*) * (num_measurements + 1));
        if (!new_measurements) {
            free_measurement_report(report);
            pthread_mutex_unlock(&lock);
            return;
        }
        lte_phy_measurements = new_measurements;
    }

    lte_phy_measurements[num_measurements++] = report;

    pthread_mutex_unlock(&lock);
}

void free_lte_phy_measurements() {
    for (int i = 0; i < num_measurements; i++) {
        free_measurement_report(lte_phy_measurements[i]);
    }

    if (num_measurements > 0) {
        measurement_report** new_measurements = (measurement_report**)realloc(lte_phy_measurements, sizeof(measurement_report*) * 0);
        lte_phy_measurements = new_measurements;
    }
}
