#include <string.h>

// Define a structure for LTE UE Context
typedef struct {
    int ue_id;
    int cell_id;
    struct {
        int srb1_config;
        int num_dedicated_bearers;
        int measurement_controls;
    } rrc_connection_reconfiguration;
} lte_ue_context;

// Define a node for linked list of LTE UE Contexts
typedef struct Node {
    lte_ue_context* ue_context;
    struct Node* next;
} ListNode;

// Function to read integers from standard input and find the largest integer
int find_largest_integer() {
    int n, max = INT_MIN, temp;
    scanf("%d", &n);
    int arr[n];
    for (int i = 0; i < n; i++) {
        scanf("%d", &arr[i]);
    }
    for (int i = 0; i < n; i++) {
        if (arr[i] > max)
            max = arr[i];
    }
    printf("The largest integer is: %d\n", max);
    return 0;
}

// Function to generate and populate a linked list of LTE UE Contexts
ListNode* create_lte_ue_contexts() {
    ListNode* head = NULL, *current = NULL;
    FILE* file = fopen("ue_contexts.json", "r");
    if (file == NULL) {
        printf("Error opening file.\n");
        return head;
    }
    char buffer[1024];
    while (fscanf(file, "{\"ue_id\": %d, \"cell_id\": %d, \"rrc_connection_reconfiguration\":{\"srb1_config\": %d, \"dedicated_bearers\": %d, \"measurement_controls\": %d}}\n", 
                 &ue_context->ue_id, &ue_context->cell_id, &ue_context->rrc_connection_reconfiguration.srb1_config,
                 &ue_context->rrc_connection_reconfiguration.num_dedicated_bearers,
                 &ue_context->rrc_connection_reconfiguration.measurement_controls) == 4) {
        ListNode* new_node = (ListNode*)malloc(sizeof(ListNode));
        new_node->ue_context = (lte_ue_context*)malloc(sizeof(lte_ue_context));
        new_node->next = NULL;
        if (head == NULL)
            head = current = new_node;
        else
            current->next = new_node, current = new_node;
    }
    fclose(file);
    return head;
}
