                (unsigned char)(rand() & 0xff), (unsigned char)(rand() & 0xff),
                (unsigned char)(rand() & 0xff), (unsigned char)(rand() & 0xff));
        device_list[i]->operational_status = rand() % 2; // Randomly generate operational status
        device_list[i]->signal_strength = (float)rand() / RAND_MAX;
    }

    return device_list;
}

