    for (int i = 0; i < *num_devices; i++) {
        // Update device operational status based on measurement reports
        if (device_list[i]->signal_strength > 0.5)
            device_list[i]->operational_status = 1;
        else
            device_list[i]->operational_status = 0;
    }
}

