void process_input(FILE_INFO_T *file_info_list, FILE *input_stream) {
    char file_path[MAX_FILE_PATH_LENGTH];
    long size;
    int i = 0;

    while (i < MAX_FILES_IN_MEMORY && fgets(file_path, sizeof(file_path), input_stream)) {
        file_path[strcspn(file_path, "\n")] = '\0';
        if ((size = getFileSize(file_path)) == -1) {
            // Handle invalid or corrupted data
            continue;
        }
        strcpy(file_info_list[i].path, file_path);
        file_info_list[i].size = size;
        i++;
    }

    fclose(input_stream);
}

void find_largest_file(FILE_INFO_T *file_info_list) {
    FILE_INFO_T largest_file = file_info_list[0];
    for (int i = 1; i < MAX_FILES_IN_MEMORY; i++) {
        if (file_info_list[i].size > largest_file.size) {
            largest_file = file_info_list[i];
        }
    }
    printf("The largest file is: %s, size: %ld bytes\n", largest_file.path, largest_file.size);
}

long getFileSize(const char *file_path) {
    struct stat buffer;
    if (stat(file_path, &buffer) != 0) {
        return -1; // File not found or corrupted data
    }
    return buffer.st_size;
}
