#include <stdlib.h>
#include <stdio.h>

// Define the structure for LTE UE Context
typedef struct {
    int ue_id;
    int cell_id;
    struct dl_grant* grants;
    int grant_count;
} lte_ue_context;

// Define the structure for DL Grant
typedef struct {
    int timestamp;
    char frequency_band;
    int resource_block_index;
} dl_grant;

// Function to create and populate a list of LTE UE Context structures
lte_ue_context* create_ue_context_list(int num_ue) {
    lte_ue_context* ue_contexts = (lte_ue_context*)malloc(num_ue * sizeof(lte_ue_context));
    for (int i = 0; i < num_ue; i++) {
        ue_contexts[i].ue_id = i;
        ue_contexts[i].cell_id = i;
        ue_contexts[i].grants = NULL;
        ue_contexts[i].grant_count = 0;
    }
    return ue_contexts;
}

// Function to add a DL Grant to a UE Context
void add_dl_grant(lte_ue_context* ue_context, dl_grant grant) {
    // Check if the resource block index is already in use
    for (int i = 0; i < ue_context->grant_count; i++) {
        if (ue_context->grants[i].resource_block_index == grant.resource_block_index) {
            printf("Error: Duplicate resource block index\n");
            return;
        }
    }

    // Reallocate memory if necessary
    if (ue_context->grant_count >= 100) {
        ue_context->grants = (dl_grant*)realloc(ue_context->grants, (ue_context->grant_count + 1) * sizeof(dl_grant));
    }

    // Add the new grant
    if (ue_context->grant_count == 0) {
        ue_context->grants = (dl_grant*)malloc(sizeof(dl_grant));
    } else {
        ue_context->grants = (dl_grant*)realloc(ue_context->grants, (ue_context->grant_count + 1) * sizeof(dl_grant));
    }
    ue_context->grants[ue_context->grant_count] = grant;
    ue_context->grant_count++;
}

// Function to remove a DL Grant from a UE Context
void remove_dl_grant(lte_ue_context* ue_context, int index) {
    // Check if the index is within bounds
    if (index >= ue_context->grant_count) {
        printf("Error: Index out of range\n");
        return;
    }

    // Shift the remaining grants down one position
    for (int i = index; i < ue_context->grant_count - 1; i++) {
        ue_context->grants[i] = ue_context->grants[i + 1];
    }
    free(ue_context->grants[ue_context->grant_count - 1]);
    ue_context->grant_count--;
}

// Function to integrate external data into the UE Context structures
void integrate_data(lte_ue_context* ue_contexts, int num_ue) {
    // Example usage: assume we have an array of dl_grant structs with valid data
    dl_grant grants[] = {
        {1, 'a', 0},
        {2, 'b', 1},
        {3, 'c', 2},
        ...
    };

    for (int i = 0; i < num_ue; i++) {
        add_dl_grant(&ue_contexts[i], grants[i]);
    }
}

// Function to handle updates from multiple concurrent threads
void update_ue_contexts(lte_ue_context* ue_contexts, int num_ue) {
    // Example usage: assume we have an array of threads with valid data
    pthread_t threads[] = {
        pthread_create(NULL, NULL, (void*)add_dl_grant, &ue_contexts[0]),
        pthread_create(NULL, NULL, (void*)remove_dl_grant, &ue_contexts[1]),
        ...
    };

    for (int i = 0; i < num_ue; i++) {
        pthread_join(threads[i], NULL);
    }
}

// Function to free the memory allocated for UE Context structures
void free_ue_context_list(lte_ue_context* ue_contexts, int num_ue) {
    for (int i = 0; i < num_ue; i++) {
        if (ue_contexts[i].grants != NULL) {
            for (int j = 0; j < ue_contexts[i].grant_count; j++) {
                free(&ue_contexts[i].grants[j]);
            }
            free(ue_contexts[i].grants);
        }
    }
    free(ue_contexts);
}

int main() {
    // Create a list of UE Context structures
    int num_ue = 1000;
    lte_ue_context* ue_contexts = create_ue_context_list(num_ue);

    // Integrate external data into the UE Context structures
    integrate_data(ue_contexts, num_ue);

    // Handle updates from multiple concurrent threads
    update_ue_contexts(ue_contexts, num_ue);

    // Free the memory allocated for UE Context structures
    free_ue_context_list(ue_contexts, num_ue);

    return 0;
}
