    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8;
    timestamp_t processed_timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a doubly linked list structure
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T* data;
    struct Node* prev;
    struct Node* next;
} Node;

Node* head = NULL;
int list_size = 0;
int max_list_size = MAX_LIST_SIZE;

void init_list() {
    head = NULL;
    list_size = 0;
}

void clear_list() {
    while (head != NULL) {
        Node* temp = head;
        head = head->next;
        free(temp);
    }
    list_size = 0;
}

NFAPI_CRC_INDICATION_PDU_T* create_nfa_pi_crc_indication_pdu_t(int rnti, int crcflag) {
    NFAPI_CRC_INDATION_PDU_T* nfa_pi_crc_indication_pdu_t = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (nfa_pi_crc_indation_pdu_t == NULL) {
        printf("Memory allocation failed.\n");
        return NULL;
    }
    // Initialize the structure
    nfa_pi_crc_indication_pdu_t->rx_ue_info = ...;  // Implement your code here
    nfa_pi_crc_indication_pdu_t->rnti = rnti;
    nfa_pi_crc_indication_pdu_t->crc_indication_rel8 = ...;  // Implement your code here
    nfa_pi_crc_indication_pdu_t->processed_timestamp = time(NULL);
    return nfa_pi_crc_indation_pdu_t;
}

void add_to_list(NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }
    new_node->data = data;
    new_node->prev = NULL;
    new_node->next = head;
    if (head != NULL) {
        head->prev = &new_node;
    } else {
        init_list();
    }
    head = new_node;
    list_size++;
}

void remove_from_list(NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* temp = head;
    while (temp != NULL && temp->data != data) {
        temp = temp->next;
    }
    if (temp == NULL) {
        printf("Data not found in the list.\n");
        return;
    }
    if (temp->prev != NULL) {
        temp->prev->next = temp->next;
    } else {
        head = temp->next;
    }
    if (temp->next != NULL) {
        temp->next->prev = temp->prev;
    }
    free(temp);
    list_size--;
}

void check_list_capacity() {
    if (list_size >= max_list_size) {
        clear_list();
    }
}

int main() {
    // Initialize the list
    init_list();

    // Add structures to the list
    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T* data = create_nfa_pi_crc_indication_pdu_t(i, rand() % 2);
        add_to_list(data);
    }

    // Check and clear the list if it reaches its maximum capacity
    while (list_size > max_list_size) {
        check_list_capacity();
    }

    return 0;
}

