#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int value;
    char* identifier;
} record;

void initialize_records(record** records, int num_records, int min_value, int max_value) {
    *records = (record*)calloc(num_records, sizeof(record));

    if (*records == NULL) {
        return; // Memory allocation failed
    }

    for (int i = 0; i < num_records; i++) {
        record* current_record = &(*records)[i];
        current_record->value = rand() % (max_value - min_value + 1) + min_value;
        char buffer[16]; // Buffer to store the identifier
        sprintf(buffer, "Record-%d", i);
        current_record->identifier = (char*)malloc(strlen(buffer) + 1); // Allocate memory for the string
        strcpy(current_record->identifier, buffer);
    }

    for (int i = 0; i < num_records; i++) {
        free((void*)((*records)[i]).identifier); // Free allocated strings
    }
    free(*records); // Free all records
}
