    int oldest_transaction_age = 0;
    int total_transactions = 0;
    int max_weighted_sum = 0;
    int target_rnti = 0;

    for (int i = 0; i < n; i++) {
        // Filter based on age
        if (list[i].RX_UE_INFORMATION_TAG > max_age_seconds) {
            continue;
        }

        total_transactions++;

        // Filter based on number of transactions in the past 3 seconds
        if (total_transactions > 10 && list[i].RX_UE_INFORMATION_TAG < max_age_seconds - 3) {
            break;
        }

        // Update metrics
        if (list[i].CRC_INDICATION_REL8_TAG > max_weighted_sum) {
            max_weighted_sum = list[i].CRC_INDICATION_REL8_TAG;
            target_rnti = list[i].RNTI;
        }
    }

    return target_rnti;
