        for (int j = 0; j < 20; j++) {
            records[i].string[j] = (char)(rand() % 26 + 'a'); // Random lowercase letter within range ['a', 'z')
        }
    }

    return 0; // Return success code indicating successful memory allocation and initialization
}

void free_memory(int num_records, long* offset_values, int* keys, Record* records) {
    if (offset_values)
        free(offset_values);
