int read_data_from_file(int fd, void* data, size_t count) {
    size_t remaining_bytes = count;
    char* buf = (char*)data;

    while (remaining_bytes > 0) {
        ssize_t bytes_read = read(fd, buf, remaining_bytes);

        if (bytes_read < 0) {
            return -1; // error reading from file
        } else if (bytes_read == 0) {
            break; // end of file reached
        }

        remaining_bytes -= bytes_read;
        buf += bytes_read;
    }

    return 0; // successful read
}

