typedef struct {
    int value;
} record;

void initialize_records(record **records, int num_records, int min_val, int max_val) {
    *records = (record *)malloc(num_records * sizeof(record));
    if (*records == NULL) {
        printf("Error: Memory allocation failed for records.\n");
        return;
    }

    int *offsets = (int *)malloc((num_records + 1) * sizeof(int));
    if (offsets == NULL) {
        free(*records);
        printf("Error: Memory allocation failed for offsets.\n");
        return;
    }

    int *keys = (int *)malloc(num_records * sizeof(int));
    if (keys == NULL) {
        free(*records);
        free(offsets);
        printf("Error: Memory allocation failed for keys.\n");
        return;
    }

    srand(time(NULL));

    for (int i = 0; i < num_records; i++) {
        record current_record = {(rand() % (max_val - min_val + 1)) + min_val};
        (*records)[i] = current_record;

        offsets[i] = rand();
        keys[i] = rand();
    }

    offsets[num_records] = 0;
    for (int i = 0; i < num_records; i++) {
        if (offsets[i] > offsets[i - 1]) {
            printf("Error: Offset values are not in ascending order.\n");
            free(*records);
            free(offsets);
            free(keys);
            return;
        }
    }

    for (int i = 0; i < num_records; i++) {
        if (keys[i] > max_val) {
            printf("Error: Key value is out of range.\n");
            free(*records);
            free(offsets);
            free(keys);
            return;
        }
    }

    free(offsets);
    free(keys);

    return;
}
