    LTE_MAC_PDU_T* pdu = (LTE_MAC_PDU_T*) malloc(sizeof(LTE_MAC_PDU_T));

    if (!pdu) return NULL;

    pdu->subheader = 0; // initialize with default value

    size_t total_size = sizeof(int); // space for number of SDUs
    for (int i = 0; i < num_sdus; ++i) {
        total_size += sdus_sizes[i]; // add size of each SDU
    }

    pdu->sdus = malloc(total_size);
    if (!pdu->sdus) {
        free(pdu);
        return NULL;
    }

    memcpy(pdu->sdus, &num_sdus, sizeof(int));
    for (int i = 0; i < num_sdus; ++i) {
        memcpy((char*) pdu->sdus + sizeof(int) + i * sdus_sizes[i], &sdus_sizes[i], sdus_sizes[i]);
    }

    pdu->sdus_size = total_size;

    return pdu;
}

void destroy_lte_mac_pdu(LTE_MAC_PDU_T* pdu) {
    if (!pdu) return;

    free(pdu->sdus);
    free(pdu);
}
