    // Dynamically adjust maximum list size based on system load metrics
    int max_size = MIN(MAX_LIST_SIZE, (int)(getloadavg(NULL)[2] / 10.0) * MAX_LIST_SIZE);

    NFAPI_CRC_INDICATION_PDU_T *list = NULL;
