    }

    // Serialize the list of structures into a binary file
    int fd = open(output_file, O_RDWR | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR);
    if (fd == -1) {
        printf("Error: File operation failed.\n");
        return;
    }

    if (fwrite(list, sizeof(NFAPI_CRC_INDICATION_PDU_T), num_elements, fd) != num_elements) {
        printf("Error: Serialization failed.\n");
        close(fd);
        return;
    }

    close(fd);
}

// Function to deserialize the list of structures from a binary file
NFAPI_CRC_INDICATION_PDU_T *deserialize_list(FILE *input_file) {
    // Initialize error handling for memory allocation failures
    NFAPI_CRC_INDICATION_PDU_T *list = NULL;
    int num_elements;

    // Open the input file
    int fd = open(input_file, O_RDONLY);
    if (fd == -1) {
        printf("Error: File operation failed.\n");
        return NULL;
    }

    // Get the number of elements in the list
    fseek(fd, 0, SEEK_END);
    num_elements = ftell(fd) / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    rewind(fd);

    // Allocate memory for the deserialized list
    list = malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (list == NULL) {
        printf("Memory allocation failed.\n");
        close(fd);
        return NULL;
    }

    // Deserialize the list of structures from a binary file
    if (fread(list, sizeof(NFAPI_CRC_INDICATION_PDU_T), num_elements, fd) != num_elements) {
        printf("Error: Deserialization failed.\n");
        free(list);
        close(fd);
        return NULL;
    }

    close(fd);
    return list;
}

