#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

#define MAX_CACHE_SIZE 1000
#define CRC_INDICATION_REL8_TAG_LENGTH 16
#define RX_UE_INFORMATION_TAG_LENGTH 12

typedef struct {
    uint32_t RNTI;
    uint8_t data[RX_UE_INFORMATION_TAG_LENGTH];
} RX_UE_INFORMATION_TAG;

typedef enum {
    CRCFLAG_GOOD,
    CRCFLAG_BAD,
    CRCFLAG_UNKNOWN
} CRCFLAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_info;
    CRCFLAG crcflag;
    uint8_t crc_ind_rel8_tag[CRC_INDICATION_REL8_TAG_LENGTH];
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_crc_list(int n, int* cache_size) {
    NFAPI_CRC_INDICATION_PDU_T* list = NULL;
    RX_UE_INFORMATION_TAG* cache = NULL;
    int cache_idx = 0;
    int i;

    for (i = 0; i < n; i++) {
        RX_UE_INFORMATION_TAG* new_rx_ue_info = malloc(sizeof(RX_UE_INFORMATION_TAG));
        if (!new_rx_ue_info) {
            free(list);
            return NULL;
        }

        new_rx_ue_info->RNTI = rand();
        //populate data
        strcpy((char*)new_rx_ue_info->data, "RX_UE_INFORMATION_TAG");

        CRCFLAG crcflag = (CRCFLAG)(rand() % 3);
        uint8_t* crc_ind_rel8_tag = malloc(CRC_INDICATION_REL8_TAG_LENGTH);
        if (!crc_ind_rel8_tag) {
            free(list);
            return NULL;
        }
        //populate tag
        for (int j = 0; j < CRC_INDICATION_REL8_TAG_LENGTH; j++) {
            crc_ind_rel8_tag[j] = rand() % 256;
        }

        NFAPI_CRC_INDICATION_PDU_T* new_pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pdu) {
            free(list);
            return NULL;
        }

        new_pdu->rx_ue_info = *new_rx_ue_info;
        new_pdu->crcflag = crcflag;
        memcpy(new_pdu->crc_ind_rel8_tag, crc_ind_rel8_tag, CRC_INDICATION_REL8_TAG_LENGTH);

        if (!list) {
            list = new_pdu;
        } else {
            NFAPI_CRC_INDICATION_PDU_T* temp = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * (i + 1));
            if (!temp) {
                free(list);
                return NULL;
            }

            memcpy(temp, list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * i);
            temp[i] = *new_pdu;
            free(list);
            list = temp;
        }

        //cache management
        if (cache_idx >= *cache_size || cache[cache_idx].RNTI == new_rx_ue_info->RNTI) {
            for (int j = 0; j < cache_idx; j++) {
                free(&cache[j]);
            }
            *cache_size += MAX_CACHE_SIZE;
            cache = realloc(cache, sizeof(RX_UE_INFORMATION_TAG) * (*cache_size));
        }

        cache[cache_idx++] = *new_rx_ue_info;
    }

    return list;
}

