void* ue_context_list = NULL;
int max_entries = 0;
int current_entries = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

ue_context* init_ue_context_list(int max_entries) {
    if (max_entries <= 0) {
        return NULL;
    }

    pthread_mutex_lock(&lock);
    ue_context_list = (ue_context*)malloc(max_entries * sizeof(ue_context));
    current_entries = 0;
    pthread_mutex_unlock(&lock);

    return ue_context_list;
}

void add_ue_context(int mac_ce_tag, int rnti) {
    pthread_mutex_lock(&lock);
    if (current_entries >= max_entries) {
        // List is full, skip this entry
        pthread_mutex_unlock(&lock);
        return;
    }

    ue_context_list[current_entries].mac_ce_tag = mac_ce_tag;
    ue_context_list[current_entries].rnti = rnti;
    current_entries++;

    pthread_mutex_unlock(&lock);
}

void free_ue_context_list() {
    pthread_mutex_lock(&lock);
    if (ue_context_list != NULL) {
        free(ue_context_list);
        ue_context_list = NULL;
    }
    current_entries = 0;
    pthread_mutex_unlock(&lock);
}
