// Define the structure for LTE PHY Layer Configuration
typedef struct {
    int pci;
    char cgi[20];
    int max_results; // Dynamic maximum number of Measurement Results
    struct measurement_result *measurement_results;
} lte_phy_config_t;

// Define the structure for Measurement Results
typedef struct {
    float sqi;
    time_t timestamp;
} measurement_result_t;

// Function to create and populate a list of LTE PHY Layer Configuration structures
lte_phy_config_t* create_lte_phy_configs(int num_configs) {
    // Allocate memory for each configuration and its measurement results
    lte_phy_config_t *configs = (lte_phy_config_t*)malloc(num_configs * sizeof(lte_phy_config_t));
    if (!configs) return NULL;

    // Initialize each configuration's PCI to a random valid value
    srand(time(NULL));
    int pcis[num_configs];
    for (int i = 0; i < num_configs; i++) {
        pcis[i] = rand() % 504;
        configs[i].pci = (pcis[i] > 503) ? log_error("Invalid PCI") : pcis[i];
    }

    // Allocate memory for each configuration's measurement results
    int max_results_per_config = 50; // Default maximum number of Measurement Results per LTE PHY Layer Configuration structure
    for (int i = 0; i < num_configs; i++) {
        configs[i].measurement_results = (measurement_result_t*)malloc(max_results_per_config * sizeof(measurement_result_t));
        if (!configs[i].measurement_results) return NULL;

        // Initialize each measurement result with a random SQI and timestamp
        for (int j = 0; j < max_results_per_config; j++) {
            configs[i].measurement_results[j].sqi = (float)(rand() % 10000) / 100.0;
            configs[i].measurement_results[j].timestamp = time(NULL);
        }
    }

    return configs;
}

// Function to serialize the list of LTE PHY Layer Configuration structures to a binary file
int serialize_lte_phy_configs(const lte_phy_config_t *configs, int num_configs, const char* filename) {
    // Open the file in binary write mode
    FILE *fp = fopen(filename, "wb");
    if (!fp) return -1;

    // Write the number of configurations and each configuration's details to the file
    fwrite(&num_configs, sizeof(int), 1, fp);
    for (int i = 0; i < num_configs; i++) {
        fwrite(&configs[i].pci, sizeof(int), 1, fp);
        fwrite(configs[i].cgi, sizeof(char), strlen(configs[i].cgi), fp);
        fwrite(&configs[i].max_results, sizeof(int), 1, fp);
        int measurement_result_count = strlen(configs[i].measurement_results) / sizeof(measurement_result_t);
        fwrite(&measurement_result_count, sizeof(int), 1, fp);
        for (int j = 0; j < measurement_result_count; j++) {
            fwrite(&configs[i].measurement_results[j], sizeof(measurement_result_t), 1, fp);
        }
    }

    // Close the file
    fclose(fp);
    return 0;
}

// Function to deserialize the list of LTE PHY Layer Configuration structures from a binary file
lte_phy_config_t* deserialize_lte_phy_configs(const char* filename) {
    // Open the file in binary read mode
    FILE *fp = fopen(filename, "rb");
    if (!fp) return NULL;

    // Read the number of configurations and each configuration's details from the file
    int num_configs;
    fread(&num_configs, sizeof(int), 1, fp);
    lte_phy_config_t *configs = (lte_phy_config_t*)malloc(num_configs * sizeof(lte_phy_config_t));
    if (!configs) return NULL;

    for (int i = 0; i < num_configs; i++) {
        fread(&configs[i].pci, sizeof(int), 1, fp);
        configs[i].cgi = (char*)malloc(strlen(configs[i].cgi) + 1); // Read the CGI string
        fread(configs[i].cgi, sizeof(char), strlen(configs[i].cgi), fp);
        fread(&configs[i].max_results, sizeof(int), 1, fp);
        int measurement_result_count;
        fread(&measurement_result_count, sizeof(int), 1, fp);
        configs[i].measurement_results = (measurement_result_t*)malloc(measurement_result_count * sizeof(measurement_result_t));
        if (!configs[i].measurement_results) return NULL;

        for (int j = 0; j < measurement_result_count; j++) {
            fread(&configs[i].measurement_results[j], sizeof(measurement_result_t), 1, fp);
        }
    }

    // Close the file
    fclose(fp);

    return configs;
}

// Function to handle log error and PCI value validation
int log_error(const char* message) {
    printf("Error: %s\n", message);
    return -1; // Return a failure code for error handling
}
