#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int sequence_number;
    int acknowledgment_number;
    char payload[1024];
} segment_t;

typedef struct {
    pthread_mutex_t lock;
    int count;
    segment_t **segments;
} segment_list_t;

void init_segment_list(segment_list_t *list) {
    list->count = 0;
    list->segments = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

int add_segment(segment_list_t *list) {
    segment_t *new_segment = (segment_t *)malloc(sizeof(segment_t));
    if (new_segment == NULL) {
        return -1; // Out of memory
    }

    new_segment->header.sequence_number = rand();
    new_segment->header.acknowledgment_number = rand();
    strcpy(new_segment->payload, "This is a random payload");

    pthread_mutex_lock(&list->lock);
    list->segments = realloc(list->segments, (list->count + 1) * sizeof(segment_t *));
    if (!list->segments) {
        free(new_segment);
        return -2; // Memory allocation failed
    }

    list->segments[list->count] = new_segment;
    list->count++;
    pthread_mutex_unlock(&list->lock);

    return 0; // Success
}

void print_segments(segment_list_t *list) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->count; i++) {
        segment_t *segment = list->segments[i];
        printf("Sequence Number: %d\n", segment->header.sequence_number);
        printf("Acknowledgment Number: %d\n", segment->header.acknowledgment_number);
        printf("Payload: %s\n", segment->payload);
    }
    pthread_mutex_unlock(&list->lock);
}

void free_segment_list(segment_list_t *list) {
    for (int i = 0; i < list->count; i++) {
        free(list->segments[i]);
    }
    free(list->segments);
    pthread_mutex_destroy(&list->lock);
}
