void crc_indication_pdu_list_insert_collision_tracker(NFAPI_CRC_INDICATION_PDU_T **list, NFAPI_CRC_INDICATION_PDU_T *pdu, int *collisions) {
    unsigned long index = hash_func(pdu);
    if (list[index]->RNTI != pdu->RNTI) {
        // Handle collision by rehashing
        for (int i = 0; i < INITIAL_CAPACITY; i++) {
            unsigned long new_index = (index + i) % NFAPI_CRC_INDICATION_PDU_T_MAX;
            if (!list[new_index]->RNTI) {
                list[new_index] = pdu;
                return;
            }
        }
        // Handle full table by resizing
        int new_capacity = INITIAL_CAPACITY * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_list = (NFAPI_CRC_INDICATION_PDU_T *)realloc(*list, sizeof(NFAPI_CRC_INDATION_PDU_T) * new_capacity);
        if (!new_list) {
            // Handle memory allocation failure
            printf("Memory allocation failed.\n");
            return;
        }
        *list = new_list;
        index = hash_func(pdu);
    }
    (*collisions)++;
