// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    char* RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
void createNFAPIList(int numElements, void (*callback)(const char*, int, int)) {
    // Initialize the list with an initial capacity of 1,000
    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(numElements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        printf("Memory allocation failed. Exiting...\n");
        return;
    }

    // Initialize the hash table for efficient lookup
    int hashTableSize = 1000; // Adjust this value based on your specific requirements
    int* hashTable = (int*)malloc(hashTableSize * sizeof(int));
    if (!hashTable) {
        printf("Memory allocation failed. Exiting...\n");
        free(list);
        return;
    }

    for (int i = 0; i < numElements; i++) {
        // Generate a random RX_UE_INFORMATION_TAG
        char* tag = malloc(64 * sizeof(char)); // Adjust this value based on your specific requirements
        if (!tag) {
            printf("Memory allocation failed. Skipping this entry...\n");
            continue;
        }
        sprintf(tag, "RX_UE_INFO_TAG_%d", rand() % 10000);

        int RNTI = rand() % 1000; // Generate a random RNTI
        int CRCFLAG = rand() & 1; // Randomly set CRCFLAG (0 or 1)

        // Check for duplicate RNTI
        int hashValue = RNTI % hashTableSize;
        if (hashTable[hashValue] == RNTI) {
            // Update the existing entry with new CRCFLAG
            list[i].RX_UE_INFORMATION_TAG = tag;
            list[i].RNTI = RNTI;
            list[i].CRCFLAG = CRCFLAG;
        } else {
            // Add the new element to the list and hash table
            list[i].RX_UE_INFORMATION_TAG = tag;
            list[i].RNTI = RNTI;
            list[i].CRCFLAG = CRCFLAG;
            hashTable[hashValue] = RNTI;

            if (callback != NULL) {
                callback(tag, RNTI, CRCFLAG);
            }
        }

        // Release memory for the temporary tag
        free(tag);
    }

    // Free the hash table and list
    free(hashTable);
    free(list);
}

// Example callback function to log invalid entries
void logInvalidEntries(const char* tag, int RNTI, int CRCFLAG) {
    printf("Invalid entry detected: %s, RNTI = %d, CRCFLAG = %d\n", tag, RNTI, CRCFLAG);
}
