```javascript
function reduce(arr, initialValue, callback) {
  let accumulator = initialValue;
  (async () => {
    for await (const current of arr) {
      accumulator = await callback(accumulator, current);
    }
    return accumulator;
  })();
}

// Example usage:
let numbers = [1, 2, 3, 4, 5];
let initialVal = 10;

reduce(numbers, initialVal, async (acc, curr) => {
  console.log(`Accumulator: ${acc}, Current: ${curr}`);
  return acc + curr;
})
  .then((result) => {
    console.log(`Final result: ${result}`);
  })
  .catch((err) => {
    console.error(err);
  });
```

