#include <libxml/parser.h>
#include <libxml/tree.h>

typedef struct {
    xmlNode* node;
    char* class_name;
    char* id;
} DomElement;

DomElement* get_elements_by_selector(xmlDoc* doc, char* selector) {
    DomElement* elements = NULL;
    int element_count = 0;

    xmlXPathContext* ctx;
    xmlXPathObject* result;

    ctx = xmlXPathNewContext(doc);
    ctx->nodeKindSet = xmlXPathNodeKindSet(ctx->nodeKindSet, XML_XPATH_NODE_ELEMENT);

    result = xmlXPathEvalExpression(ctx, BAD_CAST selector);

    if (result != NULL) {
        for (xmlNode* node = result->nodesetval; node; node = node->next) {
            DomElement* element = (DomElement*)malloc(sizeof(DomElement));
            element->node = node;
            element->class_name = xmlGetNodeName(node);
            element->id = xmlGetAttribute(node, "id");

            if (elements == NULL) {
                elements = (DomElement*)malloc(sizeof(DomElement));
                element_count = 1;
            } else {
                DomElement* temp = (DomElement*)realloc(elements, (element_count + 1) * sizeof(DomElement));
                temp[element_count - 1] = *element;
                free(element);
                elements = temp;
                element_count++;
            }
        }

        xmlXPathFreeObject(result);
    }

    xmlXPathFreeContext(ctx);

    return elements;
}
