// Function to create and populate a list of LTE UE contexts
void* init_lte_ue_ctx_list(size_t size) {
    void *ptr = NULL;

    // Allocate memory for the list
    ptr = malloc(sizeof(lte_ue_ctx_t *) * size);
    if (!ptr) {
        return NULL;  // Handle memory allocation failure
    }

    // Initialize each UE context structure
    lte_ue_ctx_t *ctx = (lte_ue_ctx_t*)malloc(size * sizeof(lte_ue_ctx_t));
    if (!ctx) {
        free(ptr);  // Free partially allocated list in case of failure
        return NULL;  // Handle memory allocation failure
    }

    for (size_t i = 0; i < size; i++) {
        ctx[i].ue_id = rand() % 10000;
        ctx[i].rnti = rand() % 1000000;
        ctx[i].crc_flag = rand() % 2;
    }

    // Return the list
    return ptr;
}

// Function to free the allocated memory for the UE context list
void free_lte_ue_ctx_list(void *ptr) {
    if (!ptr) {
        return;  // Handle NULL pointer case
    }

    // Free each UE context structure
    lte_ue_ctx_t **ctx = (lte_ue_ctx_t**)ptr;
    for (size_t i = 0; i < strlen(ctx); i++) {
        free(ctx[i]);
    }

    // Free the list itself
    free(ptr);
}

int main() {
    size_t num_ue_ctxs = 100;  // Adjust this value to test varying loads

    void *ue_ctx_list = init_lte_ue_ctx_list(num_ue_ctxs);
    if (!ue_ctx_list) {
        printf("Error: Memory allocation failed.\n");
    } else {
        // Use the list here
