#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the structure for LTE UE context
typedef struct {
    int ue_id;
    int rnti;
    int crc_flag;
} LteUeContext;

// Define a doubly linked list node
typedef struct Node {
    LteUeContext data;
    struct Node* prev;
    struct Node* next;
} ListNode;

// Function to create and populate the list of LTE UE context structures
ListNode* create_uetransition_list(int num_entries) {
    ListNode* head = NULL;
    ListNode* tail = NULL;
    int i;

    for (i = 0; i < num_entries; i++) {
        ListNode* new_node = (ListNode*)malloc(sizeof(ListNode));
        if (!new_node) {
            printf("Memory allocation failed.\n");
            return NULL;
        }

        new_node->data.ue_id = rand() % 100;
        new_node->data.rnti = rand() % 1000;
        new_node->data.crc_flag = (rand() % 2) ? 1 : 0;

        if (!head) {
            head = tail = new_node;
        } else {
            tail->next = new_node;
            new_node->prev = tail;
            tail = new_node;
        }
    }

    return head;
}

// Function to insert a new UE context at the beginning of the list
void insert_at_beginning(ListNode** head, LteUeContext* data) {
    ListNode* new_node = (ListNode*)malloc(sizeof(ListNode));
    if (!new_node) {
        printf("Memory allocation failed.\n");
        return;
    }

    new_node->data = *data;
    new_node->next = (*head);
    new_node->prev = NULL;

    if (*head)
        (*head)->prev = &new_node->data;
    else
        (*head) = new_node;
}

// Function to insert a new UE context at the end of the list
void insert_at_end(ListNode** head, LteUeContext* data) {
    ListNode* new_node = (ListNode*)malloc(sizeof(ListNode));
    if (!new_node) {
        printf("Memory allocation failed.\n");
        return;
    }

    new_node->data = *data;
    new_node->next = NULL;
    new_node->prev = (*head);

    if (*head)
        ((*head)->next) = &new_node->data;
    else
        (*head) = &new_node->data;
}

// Function to remove a UE context based on its UE ID
void remove_ue_context(ListNode** head, int ue_id) {
    ListNode* current = *head;
    while (current && current->data.ue_id != ue_id)
        current = current->next;

    if (!current)
        printf("UE context not found.\n");
    else {
        if (current->prev)
            current->prev->next = current->next;
        else
            *head = current->next;

        if (current->next)
            current->next->prev = current->prev;
        free(current);
    }
}

// Function to free the list and its nodes
void free_list(ListNode** head) {
    ListNode* current = *head;

    while (current) {
        ListNode* next_node = current->next;
        free(current);
        current = next_node;
    }

    *head = NULL;
}
