#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char *SourceAddress;
    char *DestinationAddress;
    char *Payload;
    int DelayBudget;
    int ThroughputRequirement;
    int ReliabilityRequirement;
} NetworkPacket;

NetworkPacket* populatePacketsFromCSV(const char *filename, int *numPackets) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        return NULL;
    }

    NetworkPacket **packets = (NetworkPacket **)malloc(1000 * sizeof(NetworkPacket *));
    int i = 0;

    while (i < 1000 && !feof(file)) {
        char line[1024];
        fgets(line, sizeof(line), file);

        char *token = strtok(line, ",");
        NetworkPacket *packet = (NetworkPacket *)malloc(sizeof(NetworkPacket));

        packet->SourceAddress = strdup(token);
        token = strtok(NULL, ",");
        packet->DestinationAddress = strdup(token);
        token = strtok(NULL, ",");
        packet->Payload = strdup(token);

        if (token != NULL) {
            packet->DelayBudget = atoi(token);
            token = strtok(NULL, ",");
            packet->ThroughputRequirement = atoi(token);
            token = strtok(NULL, ",");
            packet->ReliabilityRequirement = atoi(token);
        } else {
            packet->DelayBudget = 50;
            packet->ThroughputRequirement = 30;
            packet->ReliabilityRequirement = 75;
        }

        packets[i] = packet;
        i++;
    }

    fclose(file);

    *numPackets = i;

    return packets;
}

int main() {
    // Usage example
    const char *filename = "network_packets.csv";
    int numPackets;
    NetworkPacket **packets = populatePacketsFromCSV(filename, &numPackets);
    if (packets == NULL) {
        printf("Error: Could not read from file.\n");
    } else {
        for (int i = 0; i < numPackets; i++) {
            // Use the packets
            free(packets[i]->SourceAddress);
            free(packets[i]->DestinationAddress);
            free(packets[i]->Payload);
            free(packets[i]);
        }
        free(packets);
    }

    return 0;
}

```']

