        UplinkTb *tb = &new_ue_ctx->tbs[j];
        tb->tb_size = rand() % 1024 + 1;
        tb->harq_initiated = rand() % 2;
    }

    if (*ue_contexts == NULL) {
        *ue_contexts = new_ue_ctx;
    } else {
        LteUeContext *curr = *ue_contexts;
        while (curr->next != NULL) {
            curr = curr->next;
        }
        curr->next = new_ue_ctx;
    }
}

void remove_ue_context(LteUeContext **ue_contexts, int ue_id_to_remove) {
    LteUeContext *curr = *ue_contexts;
    LteUeContext *prev = NULL;

    while (curr != NULL && curr->ue_id != ue_id_to_remove) {
        prev = curr;
        curr = curr->next;
    }

    if (curr == NULL) {
        return;
    }

    if (prev == NULL) {
        *ue_contexts = curr->next;
    } else {
        prev->next = curr->next;
    }

    free(curr);
}

void free_ue_context_list(LteUeContext **ue_contexts) {
    LteUeContext *curr = *ue_contexts;
    LteUeContext *next = NULL;

    while (curr != NULL) {
        next = curr->next;
        free(curr);
        curr = next;
    }

    *ue_contexts = NULL;
}

int main() {
    int num_ue_contexts = 1000;
    LteUeContext *ue_contexts = NULL;

    populate_ue_context_list(num_ue_contexts, &ue_contexts);

    // Add some more UE contexts
    add_ue_context(&ue_contexts, 1);
    add_ue_context(&ue_contexts, 2);
    add_ue_context(&ue_contexts, 3);

    // Remove a few UE contexts
    remove_ue_context(&ue_contexts, 2);
    remove_ue_context(&ue_contexts, 3);

    free_ue_context_list(&ue_contexts);

    return 0;
}
```']

