void* create_crc_indication_pdu_list(int num_structures, int seed, int logging_level) {
    // Initialize random number generator with given seed
    srand(seed);

    // Calculate total memory needed for list and individual structures
    size_t total_memory = sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_structures;
    size_t pool_size = 1024; // Memory pool size, adjust as needed

    // Allocate memory for the list using a memory pool
    void* list_memory = malloc(pool_size);
    if (!list_memory) {
        return NULL; // Allocation failed
    }

    // Initialize pointers to the start of each structure in the list
    NFAPI_CRC_INDICATION_PDU_T** structures = (NFAPI_CRC_INDICATION_PDU_T**)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T*) * num_structures);
    if (!structures) {
        free(list_memory); // Free allocated memory on failure
        return NULL;
    }

    // Populate the list with randomly generated structures
    for (int i = 0; i < num_structures; i++) {
        NFAPI_CRC_INDICATION_PDU_T* structure = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!structure) {
            // Reallocate memory from the pool if individual allocation fails
            size_t allocated_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
            void* allocated_memory = realloc(list_memory, total_memory + allocated_size);
            list_memory = allocated_memory;
            structures[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            continue;
        }

        // Generate random values for RX_UE_INFORMATION_TAG and RNTI
        structure->RX_UE_INFORMATION_TAG = rand() % 256;
        structure->RNTI = (rand() % 65536) | ((uint16_t)1 << 15);

        // Generate random CRC flag value
        uint32_t crc_flag = rand() % (1 << 31);
        structure->CRC_INDICATION_REL8_TAG = crc_flag;

        // Add logging functionality here, if desired
        // For example:
        if (logging_level > 0) {
            printf("Created structure %d: RX_UE_INFORMATION_TAG=0x%x, RNTI=0x%04x, CRC_INDICATION_REL8_TAG=0x%x\n", i, structure->RX_UE_INFORMATION_TAG, structure->RNTI, structure->CRC_INDICATION_REL8_TAG);
        }

        // Add to the list and update pointers
        structures[i] = structure;
    }

    return (void*)structures; // Return a pointer to the list
}
