} LTE_PHY_PDU;

// Function to create and populate a list of LTE_PHY_PDU structures
LTE_PHY_PDU* create_lte_phy_pdu_list(int num_pdu) {
    LTE_PHY_PDU* pdu_list = (LTE_PHY_PDU*)calloc(num_pdu, sizeof(LTE_PHY_PDU));

    for (int i = 0; i < num_pdu; i++) {
        pdu_list[i].L1_TFCI = rand() % 32;
        pdu_list[i].L1_RI = rand() % 4;

        if (rand() % 2) {
            pdu_list[i].L1_HARQ = HARQ_ACK;
        } else {
            pdu_list[i].L1_HARQ = HARQ_NACK;
        }
    }

    return pdu_list;
}

// Function to read integers from standard input or an external file and find the largest
int* read_integers_and_find_largest(int max_size) {
    int num_integers = 0;
    FILE* file = fopen("input.txt", "r");

    if (!file) {
        printf("Error opening file.\n");
        return NULL;
    }

    char buffer[100];
    while (fgets(buffer, sizeof(buffer), file)) {
        int integer = atoi(buffer);

        if (num_integers < max_size) {
            num_integers++;
        } else {
            break;
        }
    }

    fclose(file);

    int* integers = (int*)calloc(num_integers, sizeof(int));

    file = fopen("input.txt", "r");

    if (!file) {
        printf("Error opening file.\n");
        free(integers);
        return NULL;
    }

    num_integers = 0;

    while (fgets(buffer, sizeof(buffer), file)) {
        integer = atoi(buffer);

        if (num_integers < max_size) {
            integers[num_integers++] = integer;
        } else {
            break;
        }
    }

    fclose(file);

    int largest_integer = integers[0];

    for (int i = 1; i < num_integers; i++) {
        if (largest_integer < integers[i]) {
            largest_integer = integers[i];
        }
    }

    free(integers);

    return &largest_integer;
}

int main() {
    // Use the create_lte_phy_pdu_list function
    int num_pdu = 100;
    LTE_PHY_PDU* pdu_list = create_lte_phy_pdu_list(num_pdu);

    for (int i = 0; i < num_pdu; i++) {
        printf("PDU %d: TFCI = %d, RI = %d, HARQ = ", i + 1, pdu_list[i].L1_TFCI, pdu_list[i].L1_RI);

        if (pdu_list[i].L1_HARQ == HARQ_ACK) {
            printf("HARQ_ACK\n");
        } else {
            printf("HARQ_NACK\n");
        }
    }

    // Use the read_integers_and_find_largest function
    int* largest_integer = read_integers_and_find_largest(1000);

    if (largest_integer) {
        printf("Largest integer: %d\n", *largest_integer);
    } else {
        printf("Error occurred.\n");
    }

    return 0;
}
