    .data = NULL,
    .size = 0,
    .capacity = 0,
    .mutex = PTHREAD_MUTEX_INITIALIZER
};

void nfaapi_crc_indication_pdu_array_init() {
    pthread_mutex_lock(&nfaapi_crc_indication_pdu_array.mutex);
    if (!nfaapi_crc_indication_pdu_array.data) {
        nfaapi_crc_indication_pdu_array.data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(MAX_ELEMENTS, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        nfaapi_crc_indication_pdu_array.capacity = MAX_ELEMENTS;
    }
    pthread_mutex_unlock(&nfaapi_crc_indication_pdu_array.mutex);
}

void* nfaapi_crc_indication_pdu_array_allocate(size_t size) {
    void* ptr = NULL;

    pthread_mutex_lock(&nfaapi_crc_indication_pdu_array.mutex);

    if (nfaapi_crc_indication_pdu_array.size + size > nfaapi_crc_indication_pdu_array.capacity) {
        // Dynamically resize the array
        size_t new_capacity = nfaapi_crc_indication_pdu_array.size * 2;
        if (new_capacity < nfaapi_crc_indication_pdu_array.capacity)
            new_capacity = MAX_ELEMENTS;

        NFAPI_CRC_INDICATION_PDU_T* old_data = nfaapi_crc_indication_pdu_array.data;
        nfaapi_crc_indication_pdu_array.data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(old_data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
        nfaapi_crc_indication_pdu_array.capacity = new_capacity;

        if (!nfaapi_crc_indication_pdu_array.data) {
            // Memory allocation failed
            pthread_mutex_unlock(&nfaapi_crc_indication_pdu_array.mutex);
            return NULL;
        }
    }

    ptr = &nfaapi_crc_indication_pdu_array.data[nfaapi_crc_indication_pdu_array.size];
    nfaapi_crc_indication_pdu_array.size += size;

    pthread_mutex_unlock(&nfaapi_crc_indication_pdu_array.mutex);

    return ptr;
}

void nfaapi_crc_indication_pdu_array_compact() {
    NFAPI_CRC_INDICATION_PDU_T* new_data = NULL;
    size_t new_size = 0, i = 0;

    pthread_mutex_lock(&nfaapi_crc_indication_pdu_array.mutex);

    if (nfaapi_crc_indication_pdu_array.size) {
        // Find the first non-null element
        for (; i < nfaapi_crc_indication_pdu_array.size; i++) {
            if (!nfaapi_crc_indication_pdu_array.data[i].RX_UE_INFORMATION_TAG) {
