            new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(nfaapi_crc_indication_pdu_array.data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_size);
            nfaapi_crc_indication_pdu_array.data = new_data;
            nfaapi_crc_indication_pdu_array.capacity = new_size;
        }
    }

