typedef struct {
    char mac[18];
    char ssid[33];
    int signal_strength;
} WiFi_Client;

WiFi_Client **create_wifi_client_list(int initial_size) {
    WiFi_Client **clients = (WiFi_Client **)malloc(initial_size * sizeof(WiFi_Client *));
    return clients;
}

void add_wifi_client(WiFi_Client **clients, int* size, char mac[], char ssid[], int signal_strength) {
    if (*size == 0) {
        *size = 1;
    } else if (*size <= 10) {
        WiFi_Client *new_clients = (WiFi_Client *)realloc(clients, (*size + 10) * sizeof(WiFi_Client *));
        clients = new_clients;
        *size += 10;
    }
    clients[(*size - 1)] = (WiFi_Client *)malloc(sizeof(WiFi_Client));
    strcpy(clients[(*size - 1)->mac], mac);
    strcpy(clients[(*size - 1]->ssid, ssid];
    clients[(*size - 1]->signal_strength = signal_strength;
}

void sort_wifi_client_list(WiFi_Client **clients, int size) {
    for (int i = 0; i < size; i++) {
        for (int j = i + 1; j < size; j++) {
            if (clients[i]->signal_strength < clients[j]->signal_strength) {
                WiFi_Client *temp = clients[i];
                clients[i] = clients[j];
                clients[j] = temp;
            }
        }
    }
}

void print_wifi_client_list(WiFi_Client **clients, int size) {
    for (int i = 0; i < size; i++) {
        printf("MAC: %s\nSSID: %s\nSignal Strength: %d\n", clients[i]->mac, clients[i]->ssid, clients[i]->signal_strength);
    }
}

int main() {
    WiFi_Client **clients = create_wifi_client_list(10);
    int size = 0;
    add_wifi_client(clients, &size, "00:11:22:33:44:55", "My Network", 75);
    add_wifi_client(clients, &size, "66:77:88:99:AA:BB", "Another Network", 90);
    sort_wifi_client_list(clients, size);
    print_wifi_client_list(clients, size);
    return 0;
}
