NFAPI_CRC_INDICATION_PDU_T *create_crc_indication_pdu(int n) {
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = NULL;
    int i, size, total_size;

    // Calculate the required memory
    total_size = sizeof(NFAPI_CRC_INDICATION_PDU_T) * n;
    size = (n / CACHE_SIZE + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T *);

    // Allocate memory for the list and each NFAPI structure
    pdu_list = (NFAPI_CRC_INDICATION_PDU_T **)malloc(size);
    if (!pdu_list) {
        return NULL;
    }

    // Clear any garbage values
    memset(pdu_list, 0, size);

    // Initialize cache
    srand(time(NULL));
    char *cache[UCHAR_MAX + 1];  // Array of pointers to cached UE information

    for (i = 0; i < n; i++) {
        int RNTI = rand() % 256;
        // Use external data source for RX_UE_INFORMATION_TAG and RNTI values
        strcpy(pdu_list[i].RX_UE_INFORMATION_TAG, "RX_UE_INFORMATION_TAG");
        pdu_list[i].RNTI = RNTI;

        // Generate random CRCFLAG value
        pdu_list[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    }

    return pdu_list;
}

void destroy_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T **pdu_list, int size) {
    if (!pdu_list || !(*pdu_list)) {
        return;
    }

    // Free each NFAPI structure
    for (int i = 0; i < size; i++) {
        free((*pdu_list + i));
    }

    // Free the list itself
    free(*pdu_list);
    *pdu_list = NULL;
}

