    uint16_t cell_identity;
    MeasurementReport** measurement_reports;
} NetworkInterfaceStatistics;

// Define structure for MeasurementReport
typedef struct {
    time_t timestamp;
    int signal_strength;
    uint8_t frequency_band;
} MeasurementReport;

NetworkInterfaceStatistics* initialize_network_interface_statistics(int num_measurements) {
    NetworkInterfaceStatistics* network_interface_statistics = (NetworkInterfaceStatistics*)malloc(sizeof(NetworkInterfaceStatistics));
    network_interface_statistics->ue_identifier = 12345; // arbitrary UE identifier
    network_interface_statistics->cell_identity = 789;

    MeasurementReport** measurement_reports = (MeasurementReport**)calloc(num_measurements, sizeof(MeasurementReport*));
    for (int i = 0; i < num_measurements; i++) {
        measurement_reports[i] = (MeasurementReport*)malloc(sizeof(MeasurementReport));
        // populate timestamp, signal strength, and frequency band
        measurement_reports[i]->timestamp = time(NULL);
        measurement_reports[i]->signal_strength = rand() % 100;
        measurement_reports[i]->frequency_band = 1; // arbitrary frequency band

        // ensure timestamps are in ascending order and no two adjacent reports have the same signal strength
        qsort(measurement_reports + i, num_measurements - i, sizeof(MeasurementReport*), sort_by_timestamp);
    }

    network_interface_statistics->measurement_reports = measurement_reports;
    return network_interface_statistics;
}

int compare_measurement_reports(const void* a, const void* b) {
    MeasurementReport** report_a = *(MeasurementReport**)a;
    MeasurementReport** report_b = *(MeasurementReport**)b;
    if ((*report_a)->timestamp < (*report_b)->timestamp)
        return -1;
    else if ((*report_a)->timestamp > (*report_b)->timestamp)
        return 1;
    else
        return (*report_a)->signal_strength - (*report_b)->signal_strength;
}

void sort_by_timestamp(void* base, int nmemb, size_t size, void* result) {
    qsort(base, nmemb, size, compare_measurement_reports);
}
