    if (!(list[n] = (struct NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU_T)))) {
        fprintf(log_file, "Error: Memory allocation failed for structure.\n");
        free(list);
