typedef struct {
    char UE_identifier[17];
    int RNTI;
    int measurement_values[];
} LTE_PHY_MEASUREMENTS_T;

void populate_list(LTE_PHY_MEASUREMENTS_T **list, int *size, int max_size, int num_measurements) {
    srand(time(NULL));

    for (int i = 0; i < num_measurements; i++) {
        if (*size >= max_size) {
            printf("Error: List limit exceeded.\n");
            return;
        }

        LTE_PHY_MEASUREMENTS_T *measurement = (LTE_PHY_MEASUREMENTS_T *)malloc(sizeof(LTE_PHY_MEASUREMENTS_T) + sizeof(int) * num_measurements);
        if (!measurement) {
            printf("Memory allocation failed.\n");
            return;
        }

        measurement->RNTI = rand() % 1000;
        for (int j = 0; j < num_measurements; j++) {
            measurement->measurement_values[j] = rand() % 100;
        }
        sprintf(measurement->UE_identifier, "UE_%d", i);

        if (*size > 0) {
            for (int j = *size - 1; j >= 0; j--) {
                if (strcmp(list[0]->UE_identifier, measurement->UE_identifier) == 0) {
                    printf("Error: Duplicate UE identifier detected.\n");
                    free(measurement);
                    return;
                }
            }
        }

        list[(*size)++] = measurement;
    }
}

void free_list(LTE_PHY_MEASUREMENTS_T **list, int size) {
    for (int i = 0; i < size; i++) {
        free(list[i]);
    }
    free(list);
}

int main() {
    LTE_PHY_MEASUREMENTS_T *measurements = NULL;
    int num_measurements = 1000;
    int max_size = 1000;

    populate_list(&measurements, &max_size, num_measurements);

    // Use the populated list here...

    free_list(&measurements, max_size);

    return 0;
}
