void init_network_interface_statistics(NetworkInterfaceStatistics** interfaces, int num_interfaces, int max_reports_per_interface) {
    for (int i = 0; i < num_interfaces; i++) {
        NetworkInterfaceStatistics* interface = interfaces[i];
        interface->ue_identifier = rand() % 100;
        interface->cell_identity = rand() % 100;

        interface->reports = (struct MeasurementReport*)malloc(sizeof(struct MeasurementReport) * max_reports_per_interface);
        for (int j = 0; j < max_reports_per_interface; j++) {
            MeasurementReport* report = &interface->reports[j];
            report->timestamp = time(NULL) + j;
            report->signal_strength = rand() % 100;
            report->frequency_band = rand() % 3;

            if (j > 0 && report->signal_strength == interface->reports[j - 1].signal_strength) {
                // Duplicate signal strength, adjust the next report's signal strength
                report->signal_strength += 1;
            }
        }

        qsort(interface->reports, max_reports_per_interface, sizeof(struct MeasurementReport), measurement_report_compare);
    }
}

int measurement_report_compare(const void* a, const void* b) {
    MeasurementReport* ra = *(MeasurementReport**)a;
    MeasurementReport* rb = *(MeasurementReport*)b;

    if (ra->timestamp > rb->timestamp)
        return 1;
    else if (ra->timestamp < rb->timestamp)
        return -1;
    else
        return ra->signal_strength - rb->signal_strength;
}

int main() {
    int num_interfaces = 5;
    int max_reports_per_interface = 100;

    NetworkInterfaceStatistics* interfaces = (NetworkInterfaceStatistics*)malloc(num_interfaces * sizeof(NetworkInterfaceStatistics));
    for (int i = 0; i < num_interfaces; i++) {
        interfaces[i].ue_identifier = -1;
        interfaces[i].cell_identity = -1;
        interfaces[i].reports = NULL;
    }

    init_network_interface_statistics(interfaces, num_interfaces, max_reports_per_interface);

    return 0;
}
