public async Task<HttpResponseMessage> UpdatePageSection(int pageSectionID, int elementID, string htmlContent)
{
    if (!ValidateInput(pageSectionID, elementID, htmlContent))
    {
        return new HttpResponseMessage { StatusCode = 400 }; // Bad request
    }

    try
    {
        // Update page section using service class
        var response = await UpdatePageSectionService.UpdatePageSection(pageSectionID, elementID, htmlContent);
        if (response.IsSuccessStatusCode)
        {
            return new HttpResponseMessage { StatusCode = 200 };
        }
        else
        {
            // Log error and retry
            _logger.LogError("Failed to update page section: " + response.StatusCode);
            await Task.Delay(1000); // Wait for a second before retrying
            return await UpdatePageSection(pageSectionID, elementID, htmlContent); // Retry
        }
    }
    catch (Exception ex)
    {
        _logger.LogError("Error updating page section: " + ex.Message);
        return new HttpResponseMessage { StatusCode = 500 }; // Internal server error
    }

    async Task<HttpResponseMessage> UpdatePageSection(int pageSectionID, int elementID, string htmlContent)
    {
        // Fetch metadata from CMS
        var metaData = await GetMetadataFromCMS(elementID);

        if (metaData == null)
        {
            return new HttpResponseMessage { StatusCode = 404 }; // Not found
        }

        // Update cache for frequently accessed elements
        UpdateCache(pageSectionID, elementID, htmlContent);

        return new HttpResponseMessage { StatusCode = 200 };
    }
}
