    for (size_t i = 0; i < count; ++i) {
        floats[i] = (double)rand() / RAND_MAX;
        keys[i] = rand();

        (*vectors)[i] = (vector){(float)rand() / RAND_MAX, (float)rand() / RAND_MAX, (float)rand() / RAND_MAX};
    }
}

void populate_and_serialize(NFAPI_CRC_INDICATION_PDU_T **list_ptr, size_t count) {
