        reports[i] = (LTE_RRC_MEASUREMENT_REPORT_T*)malloc(sizeof(LTE_RRC_MEASUREMENT_REPORT_T));
        if (!reports[i]) {
            for (uint32_t j = 0; j <= i; j++) {
                free(reports[j]);
            }
            free(reports); // Deallocate memory on failure
            return NULL; // Report error
        }
    }

    reports[initial_capacity - 1]->ue_id = 0;
    reports[initial_capacity - 1]->measurement_id = 0;
    reports[initial_capacity - 1]->measurement_value = 0.0f;

    return reports;
