typedef struct {
    uint16_t rnti;
    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

int create_crc_indication_pdu_list(int num_elements, NFAPI_CRC_INDICATION_PDU_T **pudolist) {
    *pudolist = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*pudolist == NULL) {
        return -1; // Memory allocation failed
    }

    for (int i = 0; i < num_elements; i++) {
        (*pudolist)[i].rnti = rand() % 10000;
        (*pudolist)[i].crcflag = rand() % 2 ? 1 : 0;
    }

    return 0;
}

int resolve_dns(const char *hostname, uint8_t **ipaddress) {
    struct addrinfo hints, *res;
    int s;
    const char *nodename = NULL;
    char serv[1024], server[1024];

    bzero(&hints, sizeof(struct addrinfo));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_protocol = IPPROTO_TCP;
    hints.ai_flags = AI_CANONNAME | AI_NUMERICHOST;

    if (getaddrinfo(hostname, NULL, &hints, &res) != 0) {
        return -2; // DNS resolution failed
    }

    // Check for timeouts and cancel DNS resolution if necessary
    usleep(DNS_TIMEOUT * 1000); // Wait for DNS resolution to complete or timeout

    if (res == NULL || res->ai_addrlen > sizeof(struct sockaddr_in)) {
        freeaddrinfo(res);
        return -3; // DNS resolution timed out or failed
    }

    // Resolve IP address
    struct sockaddr_in *ip = (struct sockaddr_in *)res->ai_addr;
    inet_ntop(AF_INET, &ip->sin_addr, server, sizeof(server));

    *ipaddress = (uint8_t *)malloc(res->ai_addrlen);
    memcpy(*ipaddress, ip, res->ai_addrlen);

    freeaddrinfo(res);

    return 0;
}

int main() {
    int num_nfapis = 10; // Number of NFAPIs to create
    NFAPI_CRC_INDICATION_PDU_T *pudolist;
    uint8_t *ipaddress;

    if (create_crc_indication_pdu_list(num_nfapis, &pudolist) != 0) {
        printf("Error creating CRC indication PDU list.\n");
        return -1;
    }

    // Perform DNS resolution
    const char *hostname = "example.com";
    if (resolve_dns(hostname, &ipaddress) != 0) {
        printf("Error resolving DNS for %s.\n", hostname);
        free(pudolist); // Free memory allocated for CRC indication PDU list
        return -2;
    }

    printf("Resolved IP address: ");
    for (int i = 0; i < res->ai_addrlen; i++) {
        printf("%02x ", ((uint8_t *)ipaddress)[i]);
    }
    printf("\n");

    free(pudolist); // Free memory allocated for CRC indication PDU list
    free(ipaddress); // Free memory allocated for IP address

    return 0;
}
