typedef struct {
    int rnti;
    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

int total_crc_indications = 0;

void log_message(const char* format, ...) {
    va_list args;
    va_start(args, format);
    vfprintf(stdout, format, args);
    va_end(args);

    FILE *file = fopen(LOG_FILE, "a");
    if (file) {
        fprintf(file, "%s\n", format);
        fclose(file);
    }
}

NFAPI_CRC_INDICATION_PDU_T* create_crc_indications(int n) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    NFAPI_CRC_INDICATION_PDU_T* crc_indications = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < n; i++) {
        pthread_mutex_lock(&lock);
        crc_indications[i].rnti = rand() % 100;
        crc_indications[i].crcflag = rand() & 0xFF;
        total_crc_indications++;
        log_message("Created CRC indication with RNTI=%d and CRCFLAG=0x%x\n", crc_indications[i].rnti, crc_indications[i].crcflag);
        pthread_mutex_unlock(&lock);
    }

    return crc_indications;
}

int main(int argc, char* argv[]) {
    int n = atoi(argv[1]);
    if (n > MAX_N) {
        printf("Error: N is too large. Maximum allowed value is %d.\n", MAX_N);
        return 1;
    }

    NFAPI_CRC_INDICATION_PDU_T* crc_indications = create_crc_indications(n);

    // free memory and print total count
    log_message("Total CRC indications generated: %d\n", total_crc_indications);
    free(crc_indications);

    return 0;
}
