int main() {
    // Initialize the external data source
    srand(time(NULL));

    // Create an initial list of PDCP structures with 10 UEs
    LTE_PDCP_PDU** pdu_list = create_pdu_list(10);

    for (int i = 0; i < 10; i++) {
        int ue_id = get_ue_id_and_sn_from_external_data_source("UE_ID");
        int snektSN = get_ue_id_and_sn_from_external_data_source("SNEKT_SN");

        add_ue_to_pdu_list(pdu_list, &i, ue_id, snektSN);
    }

    // Periodically update the list
    for (int i = 10; i < 20; i++) {
        int ue_id = get_ue_id_and_sn_from_external_data_source("UE_ID");
        int snektSN = get_ue_id_and_sn_from_external_data_source("SNEKT_SN");

        add_ue_to_pdu_list(pdu_list, &i, ue_id, snektSN);
    }

    // Handle the increased size of the list
    LTE_PDCP_PDU** new_pdu_list = create_pdu_list(i + 10);

    for (int j = 0; j < i; j++) {
        *new_pdu_list++ = pdu_list[j];
    }

    free(pdu_list);
    pdu_list = new_pdu_list;

    // Now the list has been updated and the old memory is freed

    return 0;
}

LTE_PDCP_PDU* create_pdu_list(int initial_size) {
    LTE_PDCP_PDU* pdu_list = (LTE_PDCP_PDU*)malloc(initial_size * sizeof(LTE_PDCP_PDU));

