void add_ue_to_pdu_list(LTE_PDCP_PDU** pdu_list, int* size, const int UE_ID, const int SNektSN) {
    if (*size == 0) {
        *pdu_list = (LTE_PDCP_PDU*)malloc(sizeof(LTE_PDCP_PDU));
        if (!(*pdu_list)) {
            printf("Memory allocation failed.\n");
            return;
        }
    } else {
        LTE_PDCP_PDU* new_pdu_list = (LTE_PDCP_PDU*)realloc(*pdu_list, (*size + 1) * sizeof(LTE_PDCP_PDU));
        if (!new_pdu_list) {
            printf("Memory reallocation failed.\n");
            return;
        }
        *pdu_list = new_pdu_list;
    }

    (*pdu_list)[*size].UE_ID = UE_ID;
    (*pdu_list)[*size].SNektSN = SNektSN;

    for (int j = 0; j < 16; j++) {
        (*pdu_list)[*size].PDCP_STATUS_REL15_TAG[j] = (unsigned char)rand();
    }

    (*size)++;
}

int get_ue_id_and_sn_from_external_data_source(const char* ue_id_key) {
    // Code to fetch UE ID and SNektSN from the external data source
    // For simplicity, it just returns random values
    return rand() % 100 + 1;
}
