void *createNfaPiCrcIndicationPduTList(int n, NfaPiCrcIndicationPduTCallback callback) {
    // Create a linked list to manage the list of structures
    struct ListNode {
        NFAPI_CRC_INDICATION_PDU_T *pData;
        struct ListNode *pNext;
    };
    struct ListNode *head = NULL, *curr = NULL;

    // Fetch UE information from the external data source in real-time
    for (int i = 0; i < n; i++) {
        // Create a new NFAPI_CRC_INDICATION_PDU_T structure
        NFAPI_CRC_INDICATION_PDU_T *pNew = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pNew) {
            return NULL;  // Handle memory allocation failure gracefully
        }

        // Set a valid RX_UE_INFORMATION_TAG and RNTI for the new structure
        pNew->crcFlag = (i % 2 == 0) ? 1 : 0;

        // Add the new structure to the linked list
        curr = head;
        if (!head) {
            head = curr = (struct ListNode *)malloc(sizeof(struct ListNode));
        } else {
            while (curr->pNext) {
                curr = curr->pNext;
            }
            curr->pNext = (struct ListNode *)malloc(sizeof(struct ListNode));
            curr = curr->pNext;
        }
        curr->pData = pNew;

        // Notify the caller of each successfully created structure using the callback mechanism
        if (callback) {
            callback(void *);
        }
    }

    return head;  // Return the head of the linked list
}
