```cypher
CREATE OR REPLACE FUNCTION update_graph_from_csv(N int)
  RETURNS void AS $$
DECLARE
  row RECORD;
BEGIN
  FOR i IN 1..N LOOP
    OPEN csv_file FOR READ AS row;
    LOOP
      FETCH csv_file INTO row;
      IF FOUND THEN
        UPDATE vertices SET prop1 = row.column1, prop2 = row.column2 WHERE id = row.vertex_id;
        DELETE FROM csv_file;
      END IF;
    END LOOP;
  END LOOP;
END;
$$ LANGUAGE plpgsql;
