NFAPI_CRC_INDICATION_PDU_T** create_and_populate_list(int N) {
    NFAPI_CRC_INDICATION_PDU_T** list = (NFAPI_CRC_INDICATION_PDU_T**)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    for (int i = 0; i < N; i++) {
        list[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        list[i]->RX_UE_INFORMATION_TAG = i;
        list[i]->RNTI = rand() % 100 + 1;
        list[i]->CRC_INDICATION_REL8_TAG = rand() % 2;
    }
    return list;
}

// Function to iterate over the list and update RNTI or CRCFLAG
void iterate_and_update(NFAPI_CRC_INDICATION_PDU_T** list, int N) {
    for (int i = 0; i < N; i++) {
        list[i]->RNTI += rand() % 10;
        if (list[i]->CRC_INDICATION_REL8_TAG == 1) {
            list[i]->CRC_INDICATION_REL8_TAG = 0;
        } else {
            list[i]->CRC_INDICATION_REL8_TAG = 1;
        }
    }
}

// Function to dynamically resize the list when it reaches 80% of its capacity
NFAPI_CRC_INDICATION_PDU_T** dynamic_resize(NFAPI_CRC_INDICATION_PDU_T** list, int N) {
    if (N * 1.2 > 1000) {
        return NULL; // Handle out-of-memory condition
    }
    return (NFAPI_CRC_INDICATION_PDU_T**)realloc(list, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * (int)(N * 1.2));
}

// Cleanup function to free all allocated memory when the list is no longer needed
void cleanup(NFAPI_CRC_INDICATION_PDU_T** list, int N) {
    for (int i = 0; i < N; i++) {
        free(list[i]);
    }
    free(list);
}

int main() {
    srand(time(NULL)); // Seed random number generator

    int N = 100;
    NFAPI_CRC_INDICATION_PDU_T** list = create_and_populate_list(N);

    iterate_and_update(list, N);

    NFAPI_CRC_INDICATION_PDU_T** resized_list = dynamic_resize(list, N);
    if (resized_list != NULL) {
        N = *resized_list;
        free(resized_list);
        resized_list = list;
    }

    cleanup(list, N);

    return 0;
}
