#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct Record {
    int value;
    char* key;
} Record;

Record* recordList = NULL;
int recordCount = 0;

void addRecord(char* key) {
    Record* newRecord = (Record*)malloc(sizeof(Record));
    if (!newRecord) {
        printf("Memory allocation failed.\n");
        return;
    }

    int value = rand() % 2001 - 1000; // Generate random integer within the range
    newRecord->value = value;

    newRecord->key = (char*)malloc(strlen(key) + 1);
    strcpy(newRecord->key, key);

    if (recordList == NULL) {
        recordList = newRecord;
    } else {
        Record* temp = recordList;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = newRecord;
    }

    recordCount++;
}

void getRecord(char* key) {
    Record* current = recordList;
    while (current != NULL && strcmp(current->key, key) != 0) {
        current = current->next;
    }
    if (current == NULL) {
        printf("Record not found.\n");
    } else {
        printf("Value: %d, Key: %s\n", current->value, current->key);
    }
}

void removeRecord(char* key) {
    Record* temp = recordList;
    Record* prev = NULL;
    while (temp != NULL && strcmp(temp->key, key) != 0) {
        prev = temp;
        temp = temp->next;
    }

    if (temp == NULL) {
        printf("Record not found.\n");
    } else {
        free(temp->key);
        free(temp);

        if (prev == NULL) {
            recordList = temp->next;
        } else {
            prev->next = temp->next;
        }
        recordCount--;
    }
}

int main() {
    srand(time(NULL)); // Initialize random number generator

    addRecord("record1");
    addRecord("record2");
    getRecord("record1"); // Test retrieve
    removeRecord("record1");
    return 0;
}
