        printf("Can't open database: %s\n", sqlite3_errmsg(db));
        return;
    }

    char *query = "SELECT employee_name, city, address FROM Employees WHERE supervisor_id = ?";

    sqlite3_stmt *stmt;

    // Bind parameters to prevent SQL injection
    sqlite3_prepare_v2(db, query, strlen(query), &stmt, NULL);
    sqlite3_bind_text(stmt, 1, "input_supervisor_id", -1, SQLITE_STATIC);

    int rows = sqlite3_step(stmt);

    // Retrieve and print result if successful
    while (rows == SQLITE_ROW) {
        char *employee_name = (char *)sqlite3_column_text(stmt, 0);
        char *city = (char *)sqlite3_column_text(stmt, 1);
        char *address = (char *)sqlite3_column_text(stmt, 2);

        printf("Employee Name: %s\n", employee_name);
        printf("City: %s\n", city);
        printf("Address: %s\n\n", address);

        sqlite3_finalize(stmt);
    }

    // Release resources
    sqlite3_close(db);
}

void cleanup(NFAPI_CRC_INDICATION_PDU_T *pdu_list, int num_elements) {
    for (int i = 0; i < num_elements; i++) {
        free(pdu_list[i].RX_UE_INFORMATION_TAG);
        free(pdu_list[i].CRC_INDICATION_REL8_TAG);
    }

    free(pdu_list);
}

int main() {
    // Create a list of NFAPI_CRC_INDICATION_PDU_T structures with initial capacity 100
    int num_elements = 100;
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = create_crc_indication_pdu_list(num_elements);

    // Perform SQL query execution and result retrieval
    execute_sql_query("username", "password");

    // Clean up allocated memory when the list is no longer needed
    cleanup(pdu_list, num_elements);

    return 0;
}
