NFAPI_CRC_INDICATION_PDU_T* initialize_data_structures(int num_records) {
    long* offset_values = (long*)malloc(num_records * sizeof(long));
    int* keys = (int*)malloc(num_records * sizeof(int));
    NFAPI_CRC_INDICATION_PDU_T** structs = (NFAPI_CRC_INDICATION_PDU_T**)malloc(num_records * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

