    struct node* head = NULL;
    for (int i = 0; i < num_records; i++) {
        struct node* new_node = (struct node*)malloc(sizeof(struct node));
        new_node->data = *structs[i];
        new_node->next = head;
        head = new_node;
    }

    // Clean up
    for (int i = 0; i < num_records; i++) {
        free(structs[i]);
    }
    free(structs);
    free(keys);
