        clock_gettime(CLOCK_REALTIME, &ts);
        int timestamp = (int)(ts.tv_nsec / 1000);

        printf("Largest GPS fix: %f @ %d\n", gps_fixes[0], timestamp);

        // Deallocate memory
        free(gps_fixes);
    }
}

// Function to generate random timestamp with microsecond component
struct timespec get_random_timestamp() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    int timestamp = (int)(ts.tv_nsec / 1000) + rand() % 1000000;

    return ts;
}
