#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

#define NFAPI_CRC_IND_pdu_T_COUNT 10000
#define THROTTLE_RATE 1000

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_ind;
} NFAPI_CRC_IND_pdu_T;

NFAPI_CRC_IND_pdu_T* create_nfaapi_crc_ind_pdu_t_list(size_t count) {
    pthread_mutex_init(&mutex, NULL);
    rate_limiter = &rate_limiter_service;

    // Initialize the memory pool
    memory_pool = malloc(sizeof(memory_pool));
    memory_pool->head = 0;
    memory_pool->tail = 0;
    memory_pool->size = 1024;
    pthread_mutex_lock(&mutex);

    // Create a list of NFAPI_CRC_IND_pdu_T structures with random CRCFLAG values
    for (int i = 0; i < count; i++) {
        NFAPI_CRC_IND_pdu_T* pdu_t = get_from_memory_pool();
        if (!pdu_t) {
            pthread_mutex_unlock(&mutex);
            return NULL;
        }

        // Fill the NFAPI_CRC_IND_pdu_T structure with random data
        pdu_t->ue_info.tag = rand() % 256;
        pdu_t->rnti = rand() % 1000;
        pdu_t->crc_ind.crcflag = rand() % 2;

        // Add error handling for memory allocation failures
        if (!add_to_memory_pool(pdu_t)) {
            pthread_mutex_unlock(&mutex);
            return NULL;
        }
    }

    pthread_mutex_unlock(&mutex);

    return memory_pool->head;
}

int get_from_memory_pool(NFAPI_CRC_IND_pdu_T** pdu_t) {
    pthread_mutex_lock(&mutex);
    if (memory_pool->tail - memory_pool->head < 1) {
        // Check if the memory pool is empty
        pthread_mutex_unlock(&mutex);
        return 0;
    }

    *pdu_t = &memory_pool->data[memory_pool->head];
    memory_pool->head++;
    pthread_mutex_unlock(&mutex);

    return 1;
}

int add_to_memory_pool(NFAPI_CRC_IND_pdu_T* pdu_t) {
    pthread_mutex_lock(&mutex);
    if (memory_pool->size - (memory_pool->tail - memory_pool->head) < sizeof(NFAPI_CRC_IND_pdu_T)) {
        // Check if there's enough space in the memory pool
        pthread_mutex_unlock(&mutex);
        return 0;
    }

    // Add the NFAPI_CRC_IND_pdu_T structure to the tail of the memory pool
    memcpy(&memory_pool->data[memory_pool->tail], pdu_t, sizeof(NFAPI_CRC_IND_pdu_T));
    memory_pool->tail++;
    pthread_mutex_unlock(&mutex);

    return 1;
}

int main() {
    // Initialize the rate limiter service
    rate_limiter_service = &rate_limiter;

    NFAPI_CRC_IND_pdu_T* list = create_nfaapi_crc_ind_pdu_t_list(NFAPI_CRC_IND_pdu_T_COUNT);
    if (!list) {
        printf("Memory allocation failed.\n");
        return -1;
    }

    // Free the memory pool
    while (memory_pool->head > 0) {
        NFAPI_CRC_IND_pdu_T* pdu_t = get_from_memory_pool(&pdu_t);
        free(pdu_t);
    }
    free(memory_pool);

    return 0;
}
