typedef struct {
    int RNTI;
    int successful_CRC_checks;
    int failed_CRC_checks;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* nfapi_crc_list = NULL;
int list_size = 0;
sem_t sem; // Mutex for thread safety

void cleanup() {
    if (nfapi_crc_list != NULL) {
        for (int i = 0; i < list_size; i++) {
            free(nfapi_crc_list[i].data);
        }
        free(nfapi_crc_list);
        nfapi_crc_list = NULL;
    }
}

void add_element(int RNTI, int successful_CRC_checks, int failed_CRC_checks) {
    NFAPI_CRC_INDICATION_PDU_T* new_element = (NFAPI_CRC_INDATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_element == NULL || 
        find_duplicate_RNTI(RNTI)) { // Check for duplicate RNTI
        free(new_element);
        return;
    }
    new_element->RNTI = RNTI;
    new_element->successful_CRC_checks = successful_CRC_checks;
    new_element->failed_CRC_checks = failed_CRC_checks;

    sem_wait(&sem); // Lock the mutex
    if (list_size >= MAX_LIST_SIZE) {
        printf("Maximum list size reached. Cannot add more elements.\n");
        return;
    }
    nfapi_crc_list = realloc(nfapi_crc_list, (list_size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    nfapi_crc_list[list_size++] = new_element;
    sem_post(&sem); // Unlock the mutex
}

int find_duplicate_RNTI(int RNTI) {
    for (int i = 0; i < list_size; i++) {
        if (nfapi_crc_list[i]->RNTI == RNTI) {
            return 1;
        }
    }
    return 0;
}
