int create_crc_indication_pdu_list(int num_entries, NFAPI_CRC_INDICATION_PDU_T** list) {
    *list = NULL;
    for (int i = 0; i < num_entries; i++) {
        NFAPI_CRC_INDICATION_PDU_T* new_entry = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_entry) return -1; // Memory allocation failed

        new_entry->RX_UE_INFORMATION_TAG = rand() % 1000;
        uint16_t rnti = rand();
        while (1) {
            int found = 0;
            for (int j = 0; j < i; j++) {
                if (*((*list) + j)->RNTI == rnti) {
                    found = 1;
                    break;
                }
            }
            if (!found) break;
            rnti = rand();
        }
        new_entry->RNTI = rnti;

        new_entry->CRC_INDICATION_REL8_TAG = (uint8_t)(rand() % 256);
        new_entry->CRCFLAG = (uint8_t)(rand() % 256);

        *list = realloc(*list, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * (i + 2));
        (*list)[i] = new_entry;
    }
    return 0; // Success
}

