#include <pthread.h>

#define MAX_STRUCTURES 1000
#define MAX_RNTI 500
#define MAX_RX_UE_INFORMATION_TAG 256

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    unsigned char RX_UE_INFORMATION_TAG[MAX_RX_UE_INFORMATION_TAG];
    int RNTI;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_list(int N) {
    if (N < 1 || N > MAX_STRUCTURES) {
        return NULL; // invalid input, return error
    }

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDATION_PDU_T));
    if (!list) {
        return NULL; // memory allocation failed, return error
    }

    srand(time(NULL)); // initialize random number generator

    for (int i = 0; i < N; i++) {
        pthread_mutex_lock(&lock);
        unsigned char rx_ue_tag[MAX_RX_UE_INFORMATION_TAG];
        int rnti;
        do {
            rnti = rand() % MAX_RNTI;
            for (int j = 0; j < MAX_RX_UE_INFORMATION_TAG; j++) {
                rx_ue_tag[j] = (unsigned char)(rand() % MAX_RX_UE_INFORMATION_TAG);
            }
        } while (find_structure(list, i, rnti, rx_ue_tag));
        pthread_mutex_unlock(&lock);

        list[i].RX_UE_INFORMATION_TAG = rx_ue_tag;
        list[i].RNTI = rnti;
        list[i].CRCFLAG = rand() % 2; // random CRCFLAG value
    }

    return list;
}

void cleanup_list(NFAPI_CRC_INDICATION_PDU_T* list, int N) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < N; i++) {
        pthread_mutex_lock(&lock);
        // periodic cleanup process goes here
        pthread_mutex_unlock(&lock);
    }
}

bool find_structure(NFAPI_CRC_INDICATION_PDU_T* list, int index, int rnti, unsigned char rx_ue_tag[]) {
    for (int i = 0; i < index; i++) {
        if (list[i].RNTI == rnti && memcmp(list[i].RX_UE_INFORMATION_TAG, rx_ue_tag, MAX_RX_UE_INFORMATION_TAG) == 0) {
            return true;
        }
    }
    return false;
}

void free_list(NFAPI_CRC_INDICATION_PDU_T* list, int N) {
    for (int i = 0; i < N; i++) {
        free(list[i].RX_UE_INFORMATION_TAG); // deallocate RX_UE_INFORMATION_TAG
    }
    free(list);
}
