    inflateInit2(&stream, Z_DEFAULT_COMPRESSION);

    int buffer_size = 4096;
    char buffer[buffer_size];

    do {
        int read_bytes = fread(buffer, sizeof(char), buffer_size, file);
        if (read_bytes == 0)
            break;

        stream.next_in = (Bytef *)buffer;
        stream.avail_in = read_bytes;

        do {
            stream.next_out = &buffer[0];
            stream.avail_out = buffer_size;

            int compressed_bytes = inflate(&stream, Z_FINISH);
            if (compressed_bytes == 0)
                break;

            fwrite(buffer, sizeof(char), compressed_bytes, file);

            stream.avail_out = buffer_size;
        } while (stream.avail_in > 0);

    } while (1);

    inflateEnd(&stream);
}

