// Custom memory pool structure
typedef struct {
    void* base;
    size_t size;
} MemoryPool;

// Custom memory pool function
MemoryPool* create_memory_pool(size_t initial_size) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    pool->base = malloc(initial_size);
    pool->size = initial_size;
    return pool;
}

// Free memory block from the custom pool
void free_memory_block(MemoryPool* pool, void* ptr) {
    free(ptr);
    if ((uintptr_t)ptr < (uintptr_t)pool->base &&
        (uintptr_t)ptr + pool->size <= (uintptr_t)pool->base + pool->size) {
        pool->size -= (uintptr_t)ptr - (uintptr_t)pool->base;
    } else {
        pool->size = 0;
        free(pool->base);
        free(pool);
    }
}

