#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int key;
} record;

record* createRecords(int n) {
    record* records = (record*)malloc((n+1)*sizeof(record));
    for(int i = 0; i <= n; i++) {
        records[i].key = i;
    }
    return records;
}

long* createOffsets(int n, long* offsets) {
    long* offset = (long*)malloc((n+1)*sizeof(long));
    for(int i = 0; i <= n; i++) {
        offset[i] = i;
    }
    return offset;
}

void largestInteger(record* records, int size, long* offsets) {
    int maxVal = 0;
    for (int i = 0; i < size; i++) {
        if (records[offsets[i]].key > maxVal) {
            maxVal = records[offsets[i]].key;
        }
    }
    printf("Largest integer: %d\n", maxVal);
}

void readAndFindLargest(int* arr, int size) {
    record* records = createRecords(size-1);
    long* offsets = (long*)malloc((size)*sizeof(long));
    for(int i = 0; i < size; i++) {
        offsets[i] = i;
    }
    largestInteger(records, size, offsets);
    free(offsets);
    free(records);
}

int main() {
    int n;
    printf("Enter the number of elements: ");
    scanf("%d", &n);
    int* arr = (int*)malloc((n)*sizeof(int));
    for(int i = 0; i < n; i++) {
        printf("Enter element %d: ", i+1);
        scanf("%d", &arr[i]);
    }
    readAndFindLargest(arr, n);
    free(arr);
    return 0;
}
