#define MAX_STRUCTURES 1000

typedef struct {
    char RX_UE_INFORMATION_TAG[20];
    int RNTI;
} NFAPI_CRC_INDICATION_PDU_T;

void* create_and_populate_list(int num_structures, json_object* config) {
    // Initialize the list
    NFAPI_CRC_INDICATION_PDU_T* structures = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Initialize the list size
    int structure_count = 0;

    for(int i = 0; i < num_structures; i++) {
        NFAPI_CRC_INDICATION_PDU_T* current_structure = &structures[i];

        // Generate a random RNTI
        current_structure->RNTI = rand() % 100 + 1;

        // Generate a valid RX_UE_INFORMATION_TAG
        sprintf(current_structure->RX_UE_INFORMATION_TAG, "RxUEInfoTag_%d", i);

        // Create a CRC_INDICATION_REL8_TAG with a randomly set CRCFLAG
        current_structure->CRCFLAG = rand() % 2;

        // Validate the integrity of the structure
        if(validate_structure(*current_structure)) {
            structure_count++;
        } else {
            free(structures);
            return NULL;  // Return NULL on error
        }
    }

    // Set the configuration option to log detailed information about each structure creation and validation process
    int log_level = json_object_get_int(config, "log_level");
    if(log_level) {
        for(int i = 0; i < structure_count; i++) {
            printf("Structure %d created and validated successfully.\n", i);
        }
    }

    // Free the unused structures
    free(structures + structure_count);

    return (void*)structures;
}

int validate_structure(NFAPI_CRC_INDICATION_PDU_T structure) {
    if(strlen(structure.RX_UE_INFORMATION_TAG) > 20 || strlen(structure.RX_UE_INFORMATION_TAG) < 1) {
        return 0; // Invalid RX_UE_INFORMATION_TAG
    }

    if(structure.RNTI < 1 || structure.RNTI > 100) {
        return 0; // Invalid RNTI
    }

    if(structure.CRCFLAG < 0 || structure.CRCFLAG > 1) {
        return 0; // Invalid CRCFLAG
    }

    return 1; // Structure is valid
}

void track_memory_usage(void* structures, int num_structures) {
    size_t memory_size = sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_structures;
    printf("Peak memory usage: %zu bytes\n", memory_size);

    // Track the current memory usage and number of allocations/deallocations
    static size_t peak_memory_usage = 0;
    static int allocation_count = 0;
    static int deallocation_count = 0;

    if(memory_size > peak_memory_usage) {
        peak_memory_usage = memory_size;
        allocation_count++;
    } else if(memory_size < peak_memory_usage) {
        deallocation_count++;
        peak_memory_usage = memory_size;
    }

    printf("Current memory usage: %zu bytes\n", memory_size);
    printf("Peak memory usage reached at allocation #%d.\n", allocation_count);
    printf("Total deallocations: %d\n", deallocation_count);
}

int main() {
    json_object* config = json_object_from_file("config.json");

    if(config) {
        int max_structures = json_object_get_int(config, "max_structures");

        if(max_structures > 0 && max_structures <= MAX_STRUCTURES) {
            void* structures = create_and_populate_list(max_structures, config);

            if(structures) {
                track_memory_usage(structures, max_structures);

                // Free the list
                free(structures);
            }
        } else {
            printf("Invalid configuration: max_structures must be between 1 and %d.\n", MAX_STRUCTURES);
        }

        json_object_put(config);
    } else {
        printf("Failed to load configuration file.\n");
    }

    return 0;
}
