void populate_crc_indications(int n, NFAPI_CRC_INDICATION_PDU_T **pdu_array) {
    srand(time(NULL));

    *pdu_array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (*pdu_array == NULL) {
        printf("Memory allocation failed for pdu array.\n");
        return;
    }

    for (int i = 0; i < n; i++) {
        (*pdu_array)[i].rx_ue_info_tag = rand() % 100 + 1;
        (*pdu_array)[i].rnti = rand() % 1000;
        (*pdu_array)[i].crc_flag = rand() % 2;
    }
}

void populate_offsets(int size, long **offsets_array) {
    *offsets_array = (long *)malloc(size * sizeof(long));

    if (*offsets_array == NULL) {
        printf("Memory allocation failed for offset array.\n");
        return;
    }

    for (int i = 0; i < size; i++) {
        (*offsets_array)[i] = rand() % 100000 + 1;
    }
}

void populate_keys(int size, int **keys_array) {
    *keys_array = (int *)malloc(size * sizeof(int));

    if (*keys_array == NULL) {
        printf("Memory allocation failed for key array.\n");
        return;
    }

    for (int i = 0; i < size; i++) {
        (*keys_array)[i] = rand() % 10000 + 1;
    }
}

void populate_records(int size, int **records_keys, char ***records_strings) {
    *records_keys = (int *)malloc(size * sizeof(int));

    if (*records_keys == NULL) {
        printf("Memory allocation failed for record key array.\n");
        return;
    }

    *records_strings = (char **)malloc(size * sizeof(char *));

    if (*records_strings == NULL) {
        printf("Memory allocation failed for record string array.\n");
        free(*records_keys);
        return;
    }

    for (int i = 0; i < size; i++) {
        (*records_keys)[i] = rand() % 100 + 1;

        char *record_string = (char *)malloc(1024 * sizeof(char));

        if (record_string == NULL) {
            printf("Memory allocation failed for record string.\n");
            free((*records_keys)[i]);
            for (int j = i - 1; j >= 0; j--) {
                free(((*records_strings))[j]);
            }
            return;
        }

        sprintf(record_string, "%d", (*records_keys)[i]);

        (*records_strings)[i] = record_string;
    }
}

void deallocate_arrays(int size, long *offsets_array, int *keys_array, char **strings) {
    if (offsets_array != NULL) {
        free(offsets_array);
    }

    if (keys_array != NULL) {
        free(keys_array);
    }

    for (int i = 0; i < size; i++) {
        if (strings[i] != NULL) {
            free(strings[i]);
        }
    }

    if (strings != NULL) {
        free(strings);
    }
}

void deallocate_crc_indications(int n, NFAPI_CRC_INDICATION_PDU_T *pdu_array) {
    for (int i = 0; i < n; i++) {
        // Manually freeing the pdu array elements
        free(pdu_array[i].rx_ue_info_tag);
    }

    if (pdu_array != NULL) {
        free(pdu_array);
    }
}

void main_function(int n, int size) {
    NFAPI_CRC_INDICATION_PDU_T *pdu_array;
    populate_crc_indications(n, &pdu_array);

    long *offsets_array;
    populate_offsets(size, &offsets_array);

    int *keys_array;
    populate_keys(size, &keys_array);

    int **records_keys;
    char ***records_strings;
    populate_records(size, &records_keys, &records_strings);

    deallocate_arrays(size, offsets_array, keys_array, records_strings);

    deallocate_crc_indications(n, pdu_array);
}
