        size_t new_capacity = list->capacity + (list->capacity / 2);
        LTE_MAC_ConfigurationRecord *new_records = (LTE_MAC_ConfigurationRecord*) realloc(list->records, new_capacity * sizeof(LTE_MAC_ConfigurationRecord));
        if (new_records == NULL) {
            // Handle memory allocation failure gracefully
            return;
        }
        list->records = new_records;
        list->capacity = new_capacity;
    }

    LTE_MAC_ConfigurationRecord record = { .eNodeB_ID = eNodeB_ID, .MAC_Configuration = MAC_Configuration };

    // Implement efficient copying or assignment to avoid unnecessary memory operations
    memcpy(&list->records[list->count], &record, sizeof(LTE_MAC_ConfigurationRecord));

    list->count++;
}
