        printf("Error: Population failed.\n");
        return -1;
    }

    filter_NFAPI_list(&list, num_entries, 0); // Filter entries with CRC flag 0
    filter_NFAPI_list(&list, num_entries, 255); // Filter entries with CRC flag 255

    for (int i = 0; i < num_entries; i++) {
        free((*list)[i]);
    }
    free(list);

