#include "serialization.h"

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    timestamp_t creation_timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to set CRCFLAG
void set_crcflag(NFAPI_CRC_INDICATION_PDU_T* nfa) {
    if (nfa->crc_indication_rel8_tag.crcflag % 2 == 0)
        nfa->crc_indication_rel8_tag.crcflag = 1;
    else
        nfa->crc_indication_rel8_tag.crcflag = 0;
}

// Function to populate and manage the list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* create_and_populate_list(int N, void (*callback_add)(NFAPI_CRC_INDICATION_PDU_T*), void (*callback_change_size)(int)) {
    // Allocate memory for the list
    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (list == NULL) return NULL;

    int total_crc_indications_received = 0;
    for (int i = 0; i < N; i++) {
        // Generate random RX_UE_INFORMATION_TAG, RNTI and CRCFLAG
        uint32_t rx_ue_info_tag = rand();
        RNTI rnti = (RNTI)(rand() % 10);
        CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
        set_crcflag(&list[i]);

        // Validate RX_UE_INFORMATION_TAG uniqueness
        for (int j = 0; j < i; j++) {
            if (rx_ue_info_tag == list[j].rx_ue_info_tag) {
                // Re-allocate memory and re-populate the structure
                free(list);
                return create_and_populate_list(N, callback_add, callback_change_size);
            }
        }

        // Add timestamp for each structure
        list[i].creation_timestamp = (timestamp_t)time(NULL);

        if ((i + 1) % 10000 == 0) {
            total_crc_indications_received = 0;
        } else {
            total_crc_indications_received++;
        }

        // Notify about new element and size change
        callback_add(&list[i]);
        callback_change_size(N);

    }
    return list;
}

// Serialization function to serialize the entire list to disk
int serialize_list(NFAPI_CRC_INDICATION_PDU_T* list, int N) {
    FILE* f = fopen("serialized_list.bin", "wb");
    if (f == NULL) return 0;

    for (int i = 0; i < N; i++) {
        fwrite(&list[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, f);
    }
    fclose(f);
    return 1;
}

// Deserialization function to deserialize the entire list from disk
NFAPI_CRC_INDICATION_PDU_T* deserialize_list(int* N) {
    FILE* f = fopen("serialized_list.bin", "rb");
    if (f == NULL) return NULL;

    *N = 0;
    NFAPI_CRC_INDICATION_PDU_T* list = NULL;
    while (1) {
        NFAPI_CRC_INDICATION_PDU_T temp;
        if (fread(&temp, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, f) == 1) {
            (*N)++;
            // Allocate memory for the structure
            list = realloc(list, (*N) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (list != NULL)
                memcpy(&list[(*N)-1], &temp, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        } else break;
    }
    fclose(f);
    return list;
}
