#define MAX_PDU 1000
#define UE_INDEX_SOURCE "/path/to/ue/index/source"

typedef struct {
    int ue_index;
    char mac_ce[256];
} PduData;

PduData* generate_pdus(int num_pdus) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    FILE* ue_file = fopen(UE_INDEX_SOURCE, "r");
    if (!ue_file) {
        printf("Error opening UE index file: %s\n", strerror(errno));
        return NULL;
    }

    PduData* pdus = (PduData*)malloc(num_pdus * sizeof(PduData));
    for (int i = 0; i < num_pdus; i++) {
        pthread_mutex_lock(&mutex);
        // Read UE index from file
        int ue_index = fscanf(ue_file, "%d", &ue_index) == 1 ? ue_index : -1;
        if (ue_index == -1) {
            printf("Error reading UE index from file: %s\n", strerror(errno));
            pthread_mutex_unlock(&mutex);
            free(pdus);
            return NULL;
        }

        // Generate MAC CE
        sprintf(pdus[i].mac_ce, "MAC-CE-%d", ue_index);

        pthread_mutex_unlock(&mutex);
    }
    fclose(ue_file);

    return pdus;
}

void free_pdus(PduData* pdus) {
    if (pdus) {
        free(pdus);
    }
}
