typedef struct {
    int p_ri;
    int symbols[8];
    unsigned char bitmask[8];
} PDCCHAggregationLevel;

typedef struct {
    int count;
    PDCCHAggregationLevel *levels;
} PDCCHList;

PDCCHList* init_pdcch_list(int size) {
    PDCCHList *list = (PDCCHList*)malloc(sizeof(PDCCHList));
    list->count = 0;
    list->levels = (PDCCHAggregationLevel*)calloc(size, sizeof(PDCCHAggregationLevel));
    return list;
}

void free_pdcch_list(PDCCHList* list) {
    if(list != NULL) {
        for(int i=0; i<list->count; i++) {
            free(list->levels[i].symbols);
            free(list->levels[i].bitmask);
        }
        free(list->levels);
        free(list);
    }
}

void serialize_pdcch_list(PDCCHList* list, char* filename) {
    FILE *file = fopen(filename, "wb");
    if(file == NULL) {
        printf("Error opening file for writing!\n");
        return;
    }

    // Serialize PDCCH list
    fwrite(&list->count, sizeof(int), 1, file);
    for(int i=0; i<list->count; i++) {
        fwrite(&list->levels[i].p_ri, sizeof(int), 1, file);
        fwrite(list->levels[i].symbols, sizeof(int), 8, file);
        fwrite(list->levels[i].bitmask, sizeof(unsigned char), 8, file);
    }

    fclose(file);
}

PDCCHList* deserialize_pdcch_list(char* filename) {
    PDCCHList *list = NULL;
    FILE *file = fopen(filename, "rb");
    if(file == NULL) {
        printf("Error opening file for reading!\n");
        return list;
    }

