#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

// Define the structure for LTE UE Context
typedef struct {
    int ue_id;
    char* mac_pdu;
} LteUeContext;

// Define the structure to manage a list of LTE UE Contexts
typedef struct {
    pthread_mutex_t lock; // Mutex for thread safety
    LteUeContext** contexts; // Array of context pointers
    size_t capacity; // Current capacity of the array
    size_t size; // Number of allocated context structures
} LteUeContextList;

// Function to create a new LTE UE Context structure
LteUeContext* lte_ue_context_new(int ue_id) {
    LteUeContext* ctx = (LteUeContext*) malloc(sizeof(LteUeContext));
    ctx->ue_id = ue_id;
    ctx->mac_pdu = (char*) malloc(10); // Allocate memory for MAC PDU
    return ctx;
}

// Function to add a new LTE UE Context to the list
int lte_ue_context_list_add(LteUeContextList* list, int ue_id) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= list->capacity) { // Check for array reallocation needed
        size_t new_capacity = list->capacity * 2; // Double the capacity
        LteUeContext** new_contexts = (LteUeContext**) realloc(list->contexts, sizeof(LteUeContext*) * new_capacity);
        if (!new_contexts) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Error: unable to reallocate memory
        }
        list->capacity = new_capacity;
        list->contexts = new_contexts;
    }

    LteUeContext* ctx = lte_ue_context_new(ue_id);
    if (!ctx) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Error: unable to allocate memory for UE context
    }

    list->contexts[list->size] = ctx;
    list->size++;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

// Function to retrieve an LTE UE Context from the list
LteUeContext* lte_ue_context_list_get(LteUeContextList* list, int ue_id) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->size; ++i) {
        if (list->contexts[i]->ue_id == ue_id) {
            LteUeContext* ctx = list->contexts[i];
            pthread_mutex_unlock(&list->lock);
            return ctx;
        }
    }

    pthread_mutex_unlock(&list->lock);
    return NULL; // Not found
}

// Function to initialize and clean up the LTE UE Context List
int lte_ue_context_list_init(LteUeContextList* list) {
    if (!pthread_mutex_init(&list->lock, NULL)) {
        list->capacity = 2;
        list->size = 0;
        list->contexts = (LteUeContext**) malloc(sizeof(LteUeContext*) * list->capacity);
        return 0; // Success
    }

    return -1; // Error: unable to initialize mutex
}

int lte_ue_context_list_free(LteUeContextList* list) {
    pthread_mutex_unlock(&list->lock); // Release the lock

    for (size_t i = 0; i < list->size; ++i) {
        free(list->contexts[i]->mac_pdu);
        free(list->contexts[i]);
    }

    free(list->contexts);
    return 0; // Success
}

int main() {
    LteUeContextList list;
    lte_ue_context_list_init(&list);

    int ue_id = 10;
    if (lte_ue_context_list_add(&list, ue_id) == -1) {
        printf("Error: unable to add UE context.\n");
    }

    // ... Add more UE contexts ...

    LteUeContext* ctx = lte_ue_context_list_get(&list, 10);
    if (ctx != NULL) {
        printf("Found UE Context with ID %d and MAC PDU: %s\n", ctx->ue_id, ctx->mac_pdu);
    }

    lte_ue_context_list_free(&list);
    return 0;
}
