        std::lock_guard<std::mutex> lock(mutex_);
        contexts_.push_back(context);
    }

private:
    std::vector<LTEUEContext> contexts_;
    std::mutex mutex_;
};

void selectAction(LTEContextList& list, LTEUEContext* selectedContext) {
    // Fetch real-time network metrics
    double bandwidthUsage = fetchBandwidthUsage();
    int latency = fetchLatency();
    bool congestionLevel = fetchCongestionLevel();

    if (bandwidthUsage > 0.5 && latency < 100) {
        std::cout << "Initiating data transmission." << std::endl;
        // Perform data transmission
    } else if (congestionLevel) {
        std::cout << "Performing network diagnostics." << std::endl;
        // Perform network diagnostics
    }

    // Store the selected context for future reference
    list.addContext(*selectedContext);
}

double fetchBandwidthUsage() {
    // Simulate fetching bandwidth usage from an external data source
    static random_device rd;
    static mt19937 gen(rd());
    uniform_real_distribution<double> dist(0.0, 1.0);

    return dist(gen);
}

int fetchLatency() {
    // Simulate fetching latency from an external data source
    static random_device rd;
    static mt19937 gen(rd());
    uniform_int_distribution<int> dist(0, 100);

    return dist(gen);
}

bool fetchCongestionLevel() {
    // Simulate fetching congestion level from an external data source
    static random_device rd;
    static mt19937 gen(rd());
    bernoulli_distribution dist(0.2);

    return dist(gen);
}

int main() {
    LTEContextList list;

    std::thread thread1([&list]() {
        selectAction(list, &LTEUEContext{1234, "MAC PDU 1"});
    });

    std::thread thread2([&list]() {
        selectAction(list, &LTEUEContext{5678, "MAC PDU 2"});
    });

    thread1.join();
    thread2.join();

    return 0;
}

