['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_CONNECTIONS 1000
#define CONNECTION_LIST_SIZE sizeof(struct tcp_connection*) * MAX_CONNECTIONS

typedef struct {
    int fd;
    char* ip;
    int port;
} tcp_connection;

void add_connection(tcp_connection* conn);
tcp_connection* remove_connection(int fd);

// Thread-safe connection list with a maximum size of MAX_CONNECTIONS
struct tcp_connection** connections = NULL;
int num_connections = 0;
pthread_mutex_t connection_mutex = PTHREAD_MUTEX_INITIALIZER;

void init_connections() {
    connections = (struct tcp_connection**)malloc(CONNECTION_LIST_SIZE);
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        connections[i] = NULL;
    }
}

void add_connection(tcp_connection* conn) {
    pthread_mutex_lock(&connection_mutex);

    // Check if the list is full
    if (num_connections >= MAX_CONNECTIONS) {
        fprintf(stderr, "Error: Connection list is full. Cannot add more connections.\n");
        pthread_mutex_unlock(&connection_mutex);
        return;
    }

    // Add the new connection to the list
    int i = 0;
    for (; i < num_connections; i++) {
        if (connections[i] == NULL) {
            break;
        }
    }

    if (i >= num_connections) {
        connections[num_connections++] = conn;
    } else {
        // Handle race condition: multiple threads trying to add a connection at the same time
        while (1) {
            int j = 0;
            for (; j < i; j++) {
                if (connections[j] == NULL) {
                    break;
                }
            }

            if (j >= i) {
                connections[i++] = conn;
                num_connections++;
                break;
            }
        }
    }

    pthread_mutex_unlock(&connection_mutex);
}

tcp_connection* remove_connection(int fd) {
    pthread_mutex_lock(&connection_mutex);

    int i = 0;
    for (; i < num_connections; i++) {
        if (connections[i]->fd == fd) {
            connections[i] = NULL;
            tcp_connection* conn = connections[i];
            connections[i] = connections[num_connections - 1];
            num_connections--;
            pthread_mutex_unlock(&connection_mutex);
            return conn;
        }
    }

    pthread_mutex_unlock(&connection_mutex);
    return NULL;
}

void print_connections() {
    pthread_mutex_lock(&connection_mutex);

    for (int i = 0; i < num_connections; i++) {
        if (connections[i] != NULL) {
            printf("Connection %d: FD=%d, IP=%s, Port=%d\n", i, connections[i]->fd, connections[i]->ip, connections[i]->port);
        }
    }

    pthread_mutex_unlock(&connection_mutex);
}

void cleanup_connections() {
    pthread_mutex_lock(&connection_mutex);

    for (int i = 0; i < num_connections; i++) {
        free(connections[i]);
    }

    free(connections);

    pthread_mutex_unlock(&connection_mutex);
}
