    char** str_table = (char**)malloc(100 * sizeof(char*));

    for (int i = 0; i < n; i++) {
        list[i].rnti = rand() % 100;
        list[i].offset = rand() % 100;

        records[i] = (RECORD_T*)malloc(sizeof(RECORD_T));
        if (!records[i]) return NULL; // handle memory allocation failure

        int value = rand() % 10;
        char* str = str_table[rand() % 100];
        records[i]->value = value;
        records[i]->str = str;

        // initialize string table
        for (int j = 0; j < 100; j++) {
            str_table[j] = malloc(32);
            sprintf(str_table[j], "string_%d", j);
        }
    }

    return list;
}

