#include <stdio.h>
#include <time.h>

struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct CRC_INDICATION_REL8_TAG {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
};

int allocateNFAPI_CRC_INDICATION_PDUs(int N) {
    int i;
    int* ptr = NULL;
    size_t num_allocations = 0;

    for (i = 0; i < N; i++) {
        struct NFAPI_CRC_INDICATION_PDU_T* new_pdu = malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
        if (new_pdu == NULL) {
            fprintf(stderr, "Error allocating memory for NFAPI_CRC_INDICATION_PDU_T. Exiting...\n");
            return -1;
        }
        new_pdu->RX_UE_INFORMATION_TAG = i;
        new_pdu->RNTI = rand();
        new_pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() % 2) ? 0 : 1; // Randomly set CRCFLAG
        if (ptr != NULL) {
            free(ptr);
        }
        ptr = new_pdu;
        num_allocations++;
    }

    return num_allocations;
}

int deallocateNFAPI_CRC_INDICATION_PDUs(int N, struct NFAPI_CRC_INDICATION_PDU_T* pdus) {
    int i;

    for (i = 0; i < N; i++) {
        if (pdus[i].RX_UE_INFORMATION_TAG == -1 || pdus[i].RNTI == -1 || pdus[i]->CRC_INDICATION_REL8_TAG.CRCFLAG == -1) continue;
        free(&pdus[i]);
    }

    return 0;
}

int main(int argc, char* argv[]) {
    int N = atoi(argv[1]);
    int num_allocations;

    srand(time(NULL)); // Initialize random seed

    num_allocations = allocateNFAPI_CRC_INDICATION_PDUs(N);

    if (num_allocations < 0) {
        printf("Error allocating memory for NFAPI_CRC_INDICATION_PDU_T. Exiting...\n");
        return -1;
    }

    // Deallocate the allocated memory
    deallocateNFAPI_CRC_INDICATION_PDUs(num_allocations, NULL);

    return 0;
}
