['```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <json-c/json.h>

typedef struct {
    int ue_id;
    int rnti;
    float measurement_results;
} UEContext;

typedef struct {
    int network_element_id;
    char service_type[50];
    int num_ues;
    UEContext* ues;
} NetworkElementContext;

NetworkElementContext* create_network_element_context(int network_element_id, const char* service_type) {
    NetworkElementContext* context = (NetworkElementContext*)malloc(sizeof(NetworkElementContext));
    if (!context) {
        return NULL; // Memory allocation failed
    }

    context->network_element_id = network_element_id;
    strncpy(context->service_type, service_type, sizeof(context->service_type) - 1);

    context->num_ues = 0;

    return context;
}

void add_ue_context(NetworkElementContext* context, int ue_id, int rnti, float measurement_results) {
    if (context == NULL || context->num_ues >= 100) { // Assuming a maximum of 100 UEs per network element
        return; // Error or limit reached
    }

    UEContext* new_ue = (UEContext*)malloc(sizeof(UEContext));
    if (!new_ue) {
        return; // Memory allocation failed
    }

    new_ue->ue_id = ue_id;
    new_ue->rnti = rnti;
    new_ue->measurement_results = measurement_results;

    context->ues = (UEContext*)realloc(context->ues, (context->num_ues + 1) * sizeof(UEContext));
    if (!context->ues) {
        free(new_ue);
        return; // Memory allocation failed
    }

    context->ues[context->num_ues] = new_ue;
    context->num_ues++;
}

NetworkElementContext* create_and_populate_network_elements(const char* json_file_path) {
    json_object *json_obj = json_object_from_file(json_file_path);
    if (!json_obj) {
        return NULL; // JSON file reading failed
    }

    json_object *network_elements_obj = json_object_object_get(json_obj, "NetworkElements");
    int network_element_count = json_object_array_length(network_elements_obj);

    NetworkElementContext* network_elements = (NetworkElementContext*)calloc(network_element_count, sizeof(NetworkElementContext));
    if (!network_elements) {
        return NULL; // Memory allocation failed
    }

    for (int i = 0; i < network_element_count; i++) {
        json_object *network_element_obj = json_object_array_get_idx(network_elements_obj, i);
        int network_element_id = json_object_get_int_value(network_element_obj, "NetworkElementId");
        const char* service_type = json_object_get_string_value(network_element_obj, "ServiceType");

        NetworkElementContext* context = create_network_element_context(network_element_id, service_type);
        if (!context) {
            for (int j = 0; j < i; j++) {
                free((void*)network_elements[j].ues);
            }
            free(network_elements);
            return NULL; // Memory allocation failed
        }

        json_object *ues_obj = json_object_object_get(network_element_obj, "UES");
        int ue_count = json_object_array_length(ues_obj);

        for (int j = 0; j < ue_count; j++) {
            json_object *ue_obj = json_object_array_get_idx(ues_obj, j);
            int ue_id = json_object_get_int_value(ue_obj, "UEId");
            int rnti = json_object_get_int_value(ue_obj, "RNTI");
            float measurement_results = json_object_get_double_value(ue_obj, "MeasurementResults");

            add_ue_context(context, ue_id, rnti, measurement_results);
        }

        network_elements[i] = context;
    }

    json_object_free(json_obj);
    return network_elements;
}

void free_network_elements(NetworkElementContext* network_elements, int count) {
    for (int i = 0; i < count; i++) {
        NetworkElementContext* context = &network_elements[i];
        for (int j = 0; j < context->num_ues; j++) {
            UEContext* ue = &context->ues[j];
            free((void*)ue);
        }
        free(context);
    }
    free(network_elements);
}

int main() {
    NetworkElementContext* network_elements = create_and_populate_network_elements("network_elements.json");
    // Use the populated network elements
    free_network_elements(network_elements, 1000); // Free the allocated memory
    return 0;
}
