// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_list(int num_elements) {
    // Initialize the list with memory allocation for each element
    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Populate each structure with a valid RX_UE_INFORMATION_TAG and RNTI, and a CRC_INDICATION_REL8_TAG with a randomly set CRCFLAG
    for(int i = 0; i < num_elements; i++) {
        sprintf(list[i].RX_UE_INFORMATION_TAG, "RX_UE_INFO_%d", i);
        list[i].RNTI = rand() % 100;
        // Randomly set CRCFLAG in the CRC_INDICATION_REL8_TAG
        if(rand() % 2) list[i].CRC_INDICATION_REL8_TAG[0] = '1';
        else list[i].CRC_INDICATION_REL8_TAG[0] = '0';
    }

    return list;
}

// Function to serialize the list of structures into a file in a specified format
void serialize_crc_indication_list(NFAPI_CRC_INDICATION_PDU_T* list, int num_elements, FILE* file) {
    // Serialize each structure in the list
    for(int i = 0; i < num_elements; i++) {
        fprintf(file, "RX_UE_INFORMATION_TAG: %s\n", list[i].RX_UE_INFORMATION_TAG);
        fprintf(file, "RNTI: %d\n", list[i].RNTI);
        fprintf(file, "CRC_INDICATION_REL8_TAG: %s\n", list[i].CRC_INDICATION_REL8_TAG);
    }
}

// Function to deserialize the file back into memory when needed
