#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    unsigned long RNTI;
    int CRC_INDICATION_REL8_TAG;
    int timestamp;
    int sequence_number;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* prev;
    struct node* next;
} node;

node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    node* new_node = (node*)malloc(sizeof(node));
    if (!new_node) {
        return NULL; // handle error
    }
    new_node->data = data;
    new_node->prev = new_node->next = NULL;
    return new_node;
}

void insert_node(node** head, NFAPI_CRC_INDICATION_PDU_T data) {
    node* new_node = create_node(data);
    if (*head == NULL || new_node->data.RNTI < (*head)->data.RNTI) {
        new_node->next = *head;
        if (*head != NULL)
            (*head)->prev = &new_node->next;
        else
            new_node->prev = new_node->next = NULL;
        *head = new_node;
    } else {
        node* current = *head;
        while (current->next && current->next->data.RNTI > data.RNTI)
            current = current->next;
        new_node->next = current->next;
        if (new_node->next != NULL) 
            new_node->next->prev = &new_node->next;
        else
            current->next = new_node;
        new_node->prev = current;
        current->next = new_node;
    }
}

void free_list(node** head) {
    node* temp = *head;
    while (temp) {
        node* next = temp->next;
        free(temp);
        temp = next;
    }
    *head = NULL;
}

node* get_last_node(node* head) {
    if (!head)
        return NULL;
    while (head->next)
        head = head->next;
    return head;
}

void validate_list(node* head) {
    node* current = head;
    while (current) {
        if (current->data.CRC_INDICATION_REL8_TAG < 0 || 
            current->data.timestamp < 0 || 
            current->data.sequence_number < 0)
            printf("Error: Invalid data in the list\n");
        else if (current->data.RNTI < 0) {
            printf("Error: RNTI value is invalid\n");
        } else if ((current->next != NULL && 
                    current->data.timestamp > current->next->data.timestamp) || 
                   (current->prev != NULL && 
                    current->data.timestamp < current->prev->data.timestamp))
            printf("Error: Timestamp sequence is not consistent\n");
        current = current->next;
    }
}

void free_node(node* node_to_free) {
    if (!node_to_free)
        return;
    free_node(node_to_free->next);
    free(node_to_free);
}

int main() {
    // Initialize the list
    node* head = NULL;

    // Insert nodes into the list
    for (int i = 0; i < 10; ++i) {
        NFAPI_CRC_INDICATION_PDU_T data;
        data.RX_UE_INFORMATION_TAG = i % 100;
        data.RNTI = rand() % 10000;
        data.CRC_INDICATION_REL8_TAG = (rand() % 2 == 0);
        data.timestamp = time(NULL) + rand() % 10;
        data.sequence_number = i;

        insert_node(&head, data);
    }

    // Validate the list
    validate_list(head);

    // Free the list
    free_list(&head);

    return 0;
}
