typedef struct {
    int rnti;
    unsigned char crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

void print_operation(int op_type, const char* message) {
    printf("[%s] %d: %s\n", asctime(localtime(&clock)), op_type, message);
}

int cmp_RNTI(const void *a, const void *b) {
    NFAPI_CRC_INDICATION_PDU_T* x = (NFAPI_CRC_INDICATION_PDU_T*) a;
    NFAPI_CRC_INDICATION_PDU_T* y = (NFAPI_CRC_INDICATION_PDU_T*) b;
    return (x->rnti - y->rnti);
}

int binary_search(NFAPI_CRC_INDICATION_PDU_T** list, int target_rnti) {
    int low = 0;
    int high = (*list)->len - 1;
    while (low <= high) {
        int mid = (low + high) / 2;
        if ((*list)[mid]->rnti == target_rnti)
            return mid;
        else if ((*list)[mid]->rnti < target_rnti)
            low = mid + 1;
        else
            high = mid - 1;
    }
    return -1; // Not found
}

void insert_RNTI(NFAPI_CRC_INDICATION_PDU_T*** list, int rnti) {
    NFAPI_CRC_INDICATION_PDU_T* new_entry = (NFAPI_CRC_INDINATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_entry) {
        print_operation(__LINE__, "Memory allocation failed");
        return;
    }
    new_entry->rnti = rnti; // Randomly set CRCFLAG
    qsort(*list, (*list)->len, sizeof(NFAPI_CRC_INDICATION_PDU_T), cmp_RNTI);
    for (int i = 0; i < (*list)->len; i++) {
        if ((*list)[i]->rnti > rnti) {
            memmove(&((*list)[i]), &((*list)[i + 1]), sizeof(NFAPI_CRC_INDICATION_PDU_T) * ((*list)->len - i));
            break;
        }
    }
    (*list)->len++;
}

void search_RNTI(NFAPI_CRC_INDICATION_PDU_T*** list, int target_rnti) {
    int index = binary_search(*list, target_rnti);
    if (index != -1) {
        print_operation(__LINE__, "RNTI found at index: %d");
    } else {
        print_operation(__LINE__, "RNTI not found in the list");
    }
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T** list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T*) * 10);
    for (int i = 0; i < 10; i++) {
        insert_RNTI(&list, rand());
    }
    search_RNTI(&list, 42); // Search for RNTI 42
    free(list);
}
