NFAPI_UL_CQI_INDICATION_PDU_T* createULCQIList(int n, int* ulCqiListSize) {
    *ulCqiListSize = 0;
    NFAPI_UL_CQI_INDICATION_PDU_T* ulCqiList = NULL;

    for (int i = 0; i < n; i++) {
        RX_UE_INFORMATION_TAG rxUeInfoTag;
