        newULCqi->rxUeInfoTag.rnti = rxUeInfoTag.rnti;
        newULCqi->ulCqiRel15Tag.cqiValue = cqiValue;

        if (*ulCqiListSize == 0) {
            ulCqiList = newULCqi;
