            // Insert the new structure at the correct position to maintain sorted order
            if (newULCqi->rxUeInfoTag.rnti < lastULCqi->rxUeInfoTag.rnti) {
                NFAPI_UL_CQI_INDICATION_PDU_T* temp = ulCqiList;
                for (int j = 0; j < *ulCqiListSize; j++) {
