                (*ulCqiListSize)++;
                ulCqiList = realloc(ulCqiList, sizeof(NFAPI_UL_CQI_INDICATION_PDU_T) * (*ulCqiListSize));
                ulCqiList[*ulCqiListSize - 1] = newULCqi;
            }
        }
    }

    return ulCqiList;
}

