// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T** createCRCIndicationList(int numElements) {
    // Calculate the total number of elements needed (including null pointer)
    int totalElements = numElements + 1;

    // Allocate memory for the array of pointers to NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T** crcIndicationList = malloc(totalElements * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    if (crcIndicationList == NULL) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    // Initialize the first element as null
    crcIndationList[0] = NULL;

    for (int i = 1; i < totalElements; i++) {
        // Allocate memory for each NFAPI_CRC_INDICATION_PDU_T structure
        NFAPI_CRC_INDICATION_PDU_T* crcIndication = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (crcIndication == NULL) {
            printf("Memory allocation failed.\n");
            return NULL;
        }

        // Initialize the RX_UE_INFORMATION_TAG and RNTI
        crcIndication->RX_UE_INFORMATION_TAG = rand() % 1000; 
        crcIndication->RNTI = rand() % 100;

        // Generate a random CRCFLAG for the CRC_INDICATION_REL8_TAG
        char* crcFlag = malloc(32);
        sprintf(crcFlag, "CRCFLAG_%d", rand() % 10000);

        strcpy(crcIndication->CRC_INDICATION_REL8_TAG, crcFlag);
        free(crcFlag);

        // Add the NFAPI_CRC_INDICATION_PDU_T structure to the list
        crcIndicationList[i] = crcIndication;
    }

    return crcIndicationList;
}

// Function to validate the integrity of the CRC indications before adding them to the list
bool validateCRCIndications(NFAPI_CRC_INDICATION_PDU_T* crcIndication) {
    // Validate the RX_UE_INFORMATION_TAG and RNTI
    if (crcIndication->RX_UE_INFORMATION_TAG < 0 || crcIndication->RNTI < 0) {
        return false;
    }

    // Validate the CRC_INDICATION_REL8_TAG
    if (strlen(crcIndication->CRC_INDICATION_REL8_TAG) > 32) {
        return false;
    }

    return true;
}

int main() {
    int numElements = 10; // Number of NFAPI_CRC_INDICATION_PDU_T structures to create

    // Create the list of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T** crcIndicationList = createCRCIndicationList(numElements);

    if (crcIndicationList == NULL) {
        printf("Memory allocation failed.\n");
        return 1;
    }

    // Validate the integrity of the CRC indications before adding them to the list
    for (int i = 1; i < numElements + 1; i++) {
        if (!validateCRCIndications(crcIndicationList[i])) {
            printf("Invalid CRC indication at index %d.\n", i);
            return 2;
        }
    }

    // Free the memory allocated for the list and each NFAPI_CRC_INDICATION_PDU_T structure
    for (int i = numElements; i > 0; i--) {
        free(crcIndicationList[i]);
    }
    free(crcIndicationList);

    return 0;
}
