LTE_UE_Context* merge_ue_context_lists(LTE_UE_Context* list1, int num_ues1, LTE_UE_Context* list2, int num_ues2) {
    int total_ues = num_ues1 + num_ues2;
    LTE_UE_Context* merged_list = (LTE_UE_Context*)malloc(sizeof(LTE_UE_Context)*total_ues);

    // Merge and deduplicate UE contexts based on UE ID
