['```c
#include <stdlib.h>
#include <stdint.h>

typedef struct {
    uint16_t ue_id;
    uint8_t rrc_state;
    struct {
        uint8_t id;
        uint32_t bandwidth;
        uint8_t subcarrier_spacing;
        float center_frequency;
    } bwp[8];
} LTE_UERadioContext;

int create_ue_contexts(uint32_t max_contexts) {
    if (max_contexts > 500) {
        return -1; // Exceeds maximum limit
    }
    LTE_UERadioContext *contexts = (LTE_UERadioContext *)malloc(max_contexts * sizeof(LTE_UERadioContext));
    if (!contexts) {
        return -2; // Memory allocation failed
    }

    for (int i = 0; i < max_contexts; i++) {
        contexts[i].ue_id = 0;
        contexts[i].rrc_state = 0;

        for (int j = 0; j < 8; j++) {
            contexts[i].bwp[j].id = j + 1;
            contexts[i].bwp[j].bandwidth = 0;
            contexts[i].bwp[j].subcarrier_spacing = 0;
            contexts[i].bwp[j].center_frequency = 0.0f;
        }
    }

    return 0; // Success
}

int free_ue_contexts(LTE_UERadioContext *contexts, uint32_t num_contexts) {
    if (num_contexts > max_contexts || !contexts) {
        return -1; // Invalid context or number of contexts
    }

    free(contexts);

    return 0; // Success
}

int main() {
    uint32_t max_contexts = 10;
    LTE_UERadioContext *contexts = create_ue_contexts(max_contexts);
    if (contexts == NULL) {
        printf("Error creating UE contexts.\n");
    } else {
        for (int i = 0; i < max_contexts; i++) {
            printf("UE ID: %d, RRC State: %d\n", contexts[i].ue_id, contexts[i].rrc_state);
        }

        free_ue_contexts(contexts, max_contexts);
    }

    return 0;
}
