#define MAX_ELEMENTS 1000
#define MAX_CONCURRENT_REQUESTS 50

typedef struct {
    int RNTI;
    char RX_UE_INFORMATION_TAG[32];
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *create_crc_indication_pdu(int n) {
    if (n > MAX_ELEMENTS) {
        printf("Error: Requested %d elements, but maximum is %d.\n", n, MAX_ELEMENTS);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        printf("Error: Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < n; i++) {
        pdu_list[i].RNTI = rand() % 10000;
        strcpy(pdu_list[i].RX_UE_INFORMATION_TAG, "RX_UE_INFORMATION_TAG_");
        int crcflag = (rand() % 2 == 0) ? CRCFLAG_VALID : CRCFLAG_INVALID;

        // Fetch UE information from external data source
        char *ue_info = fetch_ue_info(pdu_list[i].RNTI);
        if (!ue_info) {
            printf("Error: Failed to fetch UE information for RNTI %d.\n", pdu_list[i].RNTI);
            continue;
        }

        // Validate fetched UE information
        if (!validate_ue_info(ue_info)) {
            printf("Warning: Invalid or missing UE information for RNTI %d. Skipping this entry.\n", pdu_list[i].RNTI);
            free(ue_info);
            continue;
        }

        // Add validated UE information to the list
        strcpy(pdu_list[i].RX_UE_INFORMATION_TAG, ue_info);
