typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8;
} NFAPI_CRC_INDICATION_PDU_T;

void *malloc_sized(size_t size) {
    void *ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed!\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

int create_crc_indications(int N) {
    FILE *log_file = fopen("crc_indication_log.txt", "a+");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file!\n");
        return 1;
    }

    // Initialize error counter
    int error_count = 0;

    // Initialize RNTI counter and cache
    int rnti_counter = 1;
    int *rnti_cache = malloc_sized(sizeof(int) * N);
    for (int i = 0; i < N; i++) {
        rnti_cache[i] = -1; // Initialize as invalid
    }

    // Create and populate list of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = malloc_sized(sizeof(NFAPI_CRC_INDICATION_PDU_T) * N);
    for (int i = 0; i < N; i++) {
        pdu_list[i].rx_ue_info = // Initialize RX_UE_INFORMATION_TAG
        pdu_list[i].rnti = (RNTI)rnti_counter++;
        pdu_list[i].crc_indication_rel8 = // Initialize CRC_INDICATION_REL8_TAG

        // Randomly set CRCFLAG
        srand(time(NULL) + i);
        int crcflag = rand() % 2;
        pdu_list[i].crc_indication_rel8.crcflag = (CRCFLAG)crcflag;

        if (pdu_list[i].rnti == -1) {
            error_count++;
            continue; // RNTI not available, skip this structure
        }

        // Log execution time and any errors
        struct timespec start_time, end_time;
        clock_gettime(CLOCK_REALTIME, &start_time);
        int time_taken = (int)(end_time.tv_sec - start_time.tv_sec) * 1000 + (int)(end_time.tv_nsec / 1e6);
        fprintf(log_file, "Structure %d created in %d ms. RNTI: %d. CRCFLAG: %s.\n", i, time_taken, pdu_list[i].rnti, crcflag ? "Set" : "Not set");
    }

    // Free memory
    free(rnti_cache);
    for (int i = 0; i < N; i++) {
        if (pdu_list[i].rnti != -1) {
            // Only deallocate valid structures to prevent data corruption
            free(pdu_list[i]);
        }
    }
    free(pdu_list);

    fclose(log_file);
    return error_count;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <N>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    int N = atoi(argv[1]);

    // Create CRC indications
    int error_count = create_crc_indications(N);

    if (error_count > 0) {
        fprintf(stderr, "%d errors occurred. See 'crc_indication_log.txt' for details.\n", error_count);
        exit(EXIT_FAILURE);
    }

    printf("CRC indications created successfully! %d structures created.\n", N);
    return EXIT_SUCCESS;
}
