#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    // Your RX_UE_INFORMATION_TAG definition here
} RX_UE_INFORMATION_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu_list(int max_size, int* list_size) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    NFAPI_CRC_INDICATION_PDU_T* list = NULL;
    *list_size = 0;

    while (1) {
        pthread_mutex_lock(&lock);
        if (*list_size >= max_size) break;
        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pdu->rx_ue_info.tag = 0; // Initialize with a valid RX_UE_INFORMATION_TAG value
        pdu->RNTI = rand();
        pdu->CRCFLAG = rand() % 2;
        list = realloc(list, (*list_size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        memcpy(&list[(*list_size)], pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        (*list_size)++;
        pthread_mutex_unlock(&lock);
    }

    qsort(list, *list_size, sizeof(NFAPI_CRC_INDICATION_PDU_T), compare_rnti);

    return list;
}

int compare_rnti(const void* a, const void* b) {
    NFAPI_CRC_INDICATION_PDU_T* pdu_a = (NFAPI_CRC_INDICATION_PDU_T*)a;
    NFAPI_CRC_INDICATION_PDU_T* pdu_b = (NFAPI_CRC_INDICATION_PDU_T*)b;

    return pdu_a->RNTI - pdu_b->RNTI;
}

void free_crc_indication_pdu_list(NFAPI_CRC_INDICATION_PDU_T** list, int* list_size) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < *list_size; i++) free(list[i]);
    free(*list);
    *list_size = 0;
    pthread_mutex_unlock(&lock);
}
