int create_ue_context_list(int num_contexts, LTE_UERadioContext_t **context_list) {
    *context_list = NULL;

    for (int i = 0; i < num_contexts; i++) {
        LTE_UERadioContext_t* context = (LTE_UERadioContext_t*)malloc(sizeof(LTE_UERadioContext_t));

        if (context == NULL) {
            return -1;
        }

        srand(time(NULL));
        context->ue_id = rand() % 1000000;
        context->rnti = rand() % 10000;

        // Simulate MAC PDU generation
        for (int j = 0; j < sizeof(context->mac_pdu); j++) {
            if (rand() % 2) {
                context->mac_pdu[j] = 'A' + rand() % 26;
