        // Randomly set CRC flag
        context->crc_flag = (unsigned char)(rand() % 2);

        if (*context_list == NULL) {
            *context_list = context;
        } else {
            LTE_UERadioContext_t* current = *context_list;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = context;
        }
    }

    return 0;
}
