} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

int validate_and_create_list(const char* json_file, int* list, int* error_code) {
    json_object *json_obj = NULL;
    FILE *file = fopen(json_file, "r");
    if (!file) return 1; // Error opening file

    json_obj = json_object_from_file(file);
    fclose(file);

    if (!json_obj) return 2; // Error parsing JSON

    int num_entries = json_object_array_length(json_obj);
    *list = malloc((num_entries + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < num_entries; i++) {
        NFAPI_CRC_INDICATION_PDU_T* nfa_pi = &(*list)[i];
        json_object *entry_obj = json_object_array_get(json_obj, i);
        if (!entry_obj) continue;

        RX_UE_INFORMATION_TAG* rx_ue_info = &nfa_pi->rx_ue_info;
        json_object *tag_obj = json_object_object_get(entry_obj, "RX_UE_INFORMATION_TAG");
        if (tag_obj) {
            int tag = json_object_get_int(tag_obj);
            rx_ue_info->tag = tag;
        }

        json_object *rnti_obj = json_object_object_get(entry_obj, "RNTI");
        if (rnti_obj) {
            int rnti = json_object_get_int(rnti_obj);
            nfa_pi->rx_ue_info.rnti = rnti;
        } else return 3; // Error parsing RNTI

        CRC_INDICATION_REL8_TAG* crc_ind_rel8_tag = &nfa_pi->crc_indication_rel8_tag;
        int crc_flag = rand() % 2;
        crc_ind_rel8_tag->CRCFLAG = (crc_flag == 0) ? CRCFLAG_CLEAR : CRCFLAG_SET;

        for (int j = i - 1; j >= 0; j--) {
            if (!(*list)[j].rx_ue_info.rnti && !(*list)[j].rx_ue_info.tag) break;
            if ((*list)[j].rx_ue_info.rnti == rx_ue_info->rnti || (*list)[j].rx_ue_info.tag == tag) return 4; // Duplicate found
        }
    }

    json_object_free(json_obj);
    return 0;
}

int sort_list(NFAPI_CRC_INDICATION_PDU_T* list, int size) {
    for (int i = 0; i < size - 1; i++) {
        for (int j = i + 1; j > 0; j--) {
            if ((*list)[j - 1].rx_ue_info.rnti > (*list)[j].rx_ue_info.rnti) {
                NFAPI_CRC_INDICATION_PDU_T temp = *list;
                *list = list[j];
                list[j] = temp;
            }
        }
    }
    return 0;
}

int free_list(NFAPI_CRC_INDICATION_PDU_T* list, int size) {
    for (int i = 0; i < size; i++) {
        // Free the contents of each NFAPI_CRC_INDICATION_PDU_T
        free(&((*list)[i]).rx_ue_info);
    }
    free(list);
    return 0;
}']

