    if (*capacity <= *(size_t*)configs) {
        *(size_t*)configs = (size_t)*capacity * 2;
        void* new_ptr = allocate_array(*capacity * sizeof(LTE_PHY_Layer_Config));
        memcpy(new_ptr, *configs, (*capacity - 1) * sizeof(LTE_PHY_Layer_Config));
        free(*configs);
        *configs = new_ptr;
    }
    ((LTE_PHY_Layer_Config*)*configs)[(*capacity - 1)++] = config;
}

void lte_phy_layer_configs_free(void** configs, size_t capacity) {
    for (size_t i = 0; i < capacity; i++) {
        lte_phy_layer_config_free((LTE_PHY_Layer_Config*)*(configs + i));
