function reduce(numbers, initial, callback) {
    let accumulator = initial;
    numbers.forEach((number, index) => {
        const currentNumber = number;
        try {
            accumulator = callback(accumulator, currentNumber);
        } catch (error) {
            console.error("Error in reduction callback:", error);
            throw error;
        }
    });
    return accumulator;
}

