#include <iostream>
#include <fstream>
#include <sstream>
#include <string>
#include <vector>
#include <algorithm>
#include <cstdlib>

struct NFAPI_CRC_INDICATION_PDU_T {
    std::string RX_UE_INFORMATION_TAG;
    int RNTI;
    bool CRCFLAG;
};

std::vector<NFAPI_CRC_INDICATION_PDU_T> populateList(int N) {
    std::ifstream file("RXUEInformationTag.json");
    if (!file.is_open()) {
        return {};
    }

    std::vector<std::string> RX_UE_INFORMATION_TAG_array;
    std::vector<int> RNTI_array;

    std::string line;
    while (std::getline(file, line)) {
        std::stringstream ss(line);
        std::string tag;
        int rnti;
        if ((ss >> tag) && (ss >> rnti)) {
            RX_UE_INFORMATION_TAG_array.push_back(tag);
            RNTI_array.push_back(rnti);
        }
    }

    file.close();

    std::vector<NFAPI_CRC_INDICATION_PDU_T> result;

    for (int i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG_array[i % RX_UE_INFORMATION_TAG_array.size()];
        pdu.RNTI = RNTI_array[i % RNTI_array.size()];
        pdu.CRCFLAG = (rand() % 2);
        result.push_back(pdu);
    }

    std::sort(result.begin(), result.end(),
              [](const NFAPI_CRC_INDICATION_PDU_T& a, const NFAPI_CRC_INDICATION_PDU_T& b) {
                  return a.RNTI < b.RNTI;
              });

    for (int i = 1; i < result.size(); ++i) {
        if (result[i].RX_UE_INFORMATION_TAG == result[i - 1].RX_UE_INFORMATION_TAG ||
            result[i].RNTI == result[i - 1].RNTI) {
            return {};
        }
    }

    return result;
}

void selectAttack(int level, int& attackCount1, int& attackCount2) {
    if (attackCount1 + attackCount2 >= 1000) {
        std::cout << "No further attacks can be used until the session is reset." << std::endl;
        return;
    }

    double cooldown = 9.0;
    cooldown -= (level - 10);

    int attackNumber = rand() % 2;

    if (attackCount1 >= 500 && attackCount2 >= 500) {
        attackNumber = 3 - attackNumber; // switch between attacks
    }

    std::cout << "Selected attack: " << attackNumber << std::endl;

    attackCount[attackNumber]++;
}

int main() {
    int N = 10;
    auto result = populateList(N);

    if (result.empty()) {
        return 1;
    }

    for (const auto& pdu : result) {
        std::cout << "RX_UE_INFORMATION_TAG: " << pdu.RX_UE_INFORMATION_TAG
                  << ", RNTI: " << pdu.RNTI << ", CRCFLAG: " << (pdu.CRCFLAG ? "TRUE" : "FALSE")
                  << std::endl;
    }

