    profile->qci = rand();
    profile->ecf = rand();
    profile->ecfu = rand();
    return profile;
}

void populate_ue_context(LTEUEContext* ue) {
    for (size_t i = 0; i < ue->num_bearers; i++) {
        QoSProfile* qos = generate_qos_profile();
        ue->bearers[i] = (struct BearerContext){qos, NULL};
    }
}

void free_ue_context(LTEUEContext* ue) {
