NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu_list(const char* config_file_path, int* num_structures, int* rnti_range_start, int* rnti_range_end, float* crc_flag_prob) {
    FILE* config_file = fopen(config_file_path, "r");
    if (!config_file) {
        // Handle error
        fprintf(stderr, "Failed to open configuration file: %s\n", config_file_path);
        return NULL;
    }

    int num_structures_val = 0;
    fscanf(config_file, "%d", &num_structures_val);

    *num_structures = num_structures_val;

    int rnti_range_start_val = 0;
    int rnti_range_end_val = 0;
    fscanf(config_file, "%d %d", &rnti_range_start_val, &rnti_range_end_val);
    *rnti_range_start = rnti_range_start_val;
    *rnti_range_end = rnti_range_end_val;

    float crc_flag_prob_val = 0.0f;
    fscanf(config_file, "%f", &crc_flag_prob_val);
    *crc_flag_prob = crc_flag_prob_val;

    fclose(config_file);

    NFAPI_CRC_INDICATION_PDU_T* result = (NFAPI_CRC_INDICATION_PDU_T*)malloc(*num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!result) {
        // Handle error
        fprintf(stderr, "Memory allocation failed for creating list of structures.\n");
        return NULL;
    }

    srand(time(NULL)); // seed random number generator

    for (int i = 0; i < *num_structures; i++) {
        result[i].RX_UE_INFORMATION_TAG = rand() % 10000;
        result[i].RNTI = rand() % (*rnti_range_end - *rnti_range_start + 1) + *rnti_range_start;
        if (rand() / (float)RAND_MAX < *crc_flag_prob) {
            result[i].CRC_INDICATION_REL8_TAG = 0x12345678; // random CRCFLAG value
        } else {
            result[i].CRC_INDICATION_REL8_TAG = 0;
        }
    }

    return result;
}
