        }

        // Update memory usage and CPU usage counters
        total_structures++;
        max_memory_usage = (max_memory_usage > (total_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T))) ? max_memory_usage : total_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T);
        cpu_usage += 10; // Simulate CPU usage

