    if (resource_pool == NULL || pool_size < num_structures) {
        // Replenish the resource pool if it's empty or too small
        int new_pool_size = 0;
        while (new_pool_size < num_structures && new_pool_size <= 5000) { // Limit to avoid excessive memory usage
            void* new_resource = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            resource_pool = realloc(resource_pool, (pool_size + new_pool_size) * sizeof(void*));
            resource_pool[pool_head] = new_resource;
