#include <stdlib.h>
#include <string.h>

// Structure for RRC Connection Reconfiguration message
typedef struct {
    int srb1_config;
    int num_dedicated_bearers;
    int measurement_controls;
} RRCMessage;

// Structure for LTE UE Context
typedef struct {
    int ue_id;
    int cell_id;
    RRCMessage* rrc_messages; // Array of RRC Connection Reconfiguration messages
    struct UEContext* next; // Pointer to the next UE Context in the list
} UEContext;

// Custom memory pool structure
typedef struct {
    UEContext** pool; // Array of pointers to UE Contexts
    int size; // Current size of the memory pool
    int capacity; // Maximum capacity of the memory pool
} MemoryPool;

// Function to create a new memory pool with initial capacity 1000
MemoryPool* create_memory_pool(int initial_capacity) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    pool->pool = (UEContext**)malloc(initial_capacity * sizeof(UEContext*));
    pool->size = 0;
    pool->capacity = initial_capacity;
    return pool;
}

// Function to insert a new UE Context into the list
void insert_ue_context(MemoryPool* memory_pool, int ue_id, int cell_id) {
    // Check if there is enough space in the memory pool
    if (memory_pool->size >= memory_pool->capacity / 2) {
        // If not, double the capacity of the memory pool and reallocate
        memory_pool->pool = (UEContext**)realloc(memory_pool->pool, memory_pool->capacity * 2 * sizeof(UEContext*));
        memory_pool->capacity *= 2;
    }

    // Allocate a new UE Context structure
    UEContext* new_ue_context = (UEContext*)malloc(sizeof(UEContext));
    new_ue_context->ue_id = ue_id;
    new_ue_context->cell_id = cell_id;
    new_ue_context->rrc_messages = NULL; // Initialize RRC messages array

    // Add the new UE Context to the list
    new_ue_context->next = memory_pool->pool[memory_pool->size];
    memory_pool->pool[memory_pool->size] = new_ue_context;
    memory_pool->size++;
}

// Function to delete an existing UE Context from the list
void delete_ue_context(MemoryPool* memory_pool, int ue_id) {
    // Find the UE Context with the given ID
    for (int i = 0; i < memory_pool->size; i++) {
        if (memory_pool->pool[i]->ue_id == ue_id) {
            // Remove the UE Context from the list
            memory_pool->pool[i] = memory_pool->pool[memory_pool->size - 1];
            memory_pool->size--;
            break;
        }
    }
}

// Function to retrieve an existing UE Context from the list
UEContext* get_ue_context(MemoryPool* memory_pool, int ue_id) {
    // Find the UE Context with the given ID
    for (int i = 0; i < memory_pool->size; i++) {
        if (memory_pool->pool[i]->ue_id == ue_id) {
            return memory_pool->pool[i];
        }
    }
    return NULL;
}

// Function to update RRC Connection Reconfiguration messages for a given UE Context
void update_rrc_messages(UEContext* ue_context, int srb1_config, int num_dedicated_bearers, int measurement_controls) {
    // Allocate memory for the new RRC message structure
    RRCMessage* new_rrc_message = (RRCMessage*)malloc(sizeof(RRCMessage));
    new_rrc_message->srb1_config = srb1_config;
    new_rrc_message->num_dedicated_bearers = num_dedicated_bearers;
    new_rrc_message->measurement_controls = measurement_controls;

    // Add the new RRC message to the UE Context's list
    if (ue_context->rrc_messages == NULL) {
        ue_context->rrc_messages = new_rrc_message;
    } else {
        // Reallocate memory for the RRC messages array and add the new message
        int i = 0;
        while (ue_context->rrc_messages != NULL && i < 100) {
            i++;
            ue_context->rrc_messages = (RRCMessage*)realloc(ue_context->rrc_messages, sizeof(RRCMessage));
        }
        ue_context->rrc_messages[i] = new_rrc_message;
    }
}
