    .head = NULL,
    .size = 0,
    .capacity = INITIAL_POOL_SIZE
};

NFAPI_CRC_INDICATION_PDU_T* create_pdu(int rnti, int crc_flag) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) return NULL;

    pdu->rx_ue_info_tag = malloc(16);
    pdu->crc_ind_rel8_tag = malloc(32);

    if (!pdu->rx_ue_info_tag || !pdu->crc_ind_rel8_tag) {
        free(pdu);
        return NULL;
    }

    pdu->rnti = rnti;
    pdu->crc_flag = crc_flag;

    return pdu;
}

void destroy_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!pdu) return;

    free(pdu->rx_ue_info_tag);
    free(pdu->crc_ind_rel8_tag);

    free(pdu);
}

int create_crc_ind_puds(int n, pthread_mutex_t* lock, struct List* list) {
    int i;
    for (i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = create_pdu(i % 2 + 1, rand() % 2);

        if (!pdu) return -ENOMEM;

        pthread_mutex_lock(lock);
        if (list->size >= list->capacity) {
            // List needs to be resized
            int new_capacity = list->capacity * 2;
            NFAPI_CRC_INDICATION_PDU_T** new_list = (NFAPI_CRC_INDICATION_PDU_T**)malloc(new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
            memcpy(new_list, list->head, list->size * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

            free(list->head);
            list->head = new_list;
            list->capacity = new_capacity;
        }

        pdu->next = list->head;
        list->head = pdu;

        pthread_mutex_unlock(lock);

        if (rand() % 2) {
            // Free the pdu
            destroy_pdu(pdu);
        } else {
            // Add to the list
            list->size++;
        }
    }

    return 0;
}

int main() {
    int n = 10;

    create_crc_ind_puds(n, &pool_lock, &list);

    return 0;
}
