        list[i].RX_UE_INFORMATION_TAG = malloc(10); // Allocate memory for RX_UE_INFORMATION_TAG
        list[i].CRC_INDICATION_REL8_TAG = malloc(5); // Allocate memory for CRC_INDICATION_REL8_TAG

        if (list[i].RX_UE_INFORMATION_TAG == NULL || list[i].CRC_INDICATION_REL8_TAG == NULL) {
            free_list(&list, i + 1);
            return NULL;
        }
    }

    return list;
}

void free_list(NFAPI_CRC_INDICATION_PDU_T **list, int n) {
    for (int i = 0; i < n; i++) {
        if ((*list)[i].RX_UE_INFORMATION_TAG != NULL) {
            free((*list)[i].RX_UE_INFORMATION_TAG);
        }
        if ((*list)[i].CRC_INDICATION_REL8_TAG != NULL) {
            free((*list)[i].CRC_INDICATION_REL8_TAG);
        }
    }

    free(*list);
}

int add_element(NFAPI_CRC_INDICATION_PDU_T **list, int n, int RNTI) {
    // Create a new element with the given RNTI value
    NFAPI_CRC_INDICATION_PDU_T *new_element = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (new_element == NULL) {
        return -1; // Out of memory
    }

    new_element->RNTI = RNTI;
    new_element->RX_UE_INFORMATION_TAG = malloc(10);
    new_element->CRC_INDICATION_REL8_TAG = malloc(5);

    if (new_element->RX_UE_INFORMATION_TAG == NULL || new_element->CRC_INDICATION_REL8_TAG == NULL) {
        free(new_element);
        return -1; // Out of memory
    }

    // Add the new element to the list
    NFAPI_CRC_INDICATION_PDU_T *temp = realloc(*list, (n + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (temp == NULL) {
        free(new_element);
        return -1; // Out of memory
    }

    *list = temp;
    (*list)[n] = new_element;

    return n + 1;
}

NFAPI_CRC_INDICATION_PDU_T *get_element_by_RNTI(NFAPI_CRC_INDICATION_PDU_T **list, int n, int target_RNTI) {
    for (int i = 0; i < n; i++) {
        if ((*list)[i].RNTI == target_RNTI) {
            return &((*list)[i]);
        }
    }

    return NULL;
}

void remove_element_by_index(NFAPI_CRC_INDICATION_PDU_T **list, int n, int index) {
    // Create a new list with the elements before and after the specified index
    NFAPI_CRC_INDICATION_PDU_T *new_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc((n - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (new_list == NULL) {
        return; // Out of memory
    }

    for (int i = 0, j = 0; i < n; i++) {
        if (i != index) {
            new_list[j] = (*list)[i];
            j++;
        }
    }

    free(*list);
    *list = new_list;
}
