        if ((crc_list == NULL && (crc_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T))) 
            == NULL || (new_list != NULL && (new_list = (NFAPI_CRC_INDICATION_PDU_T*)realloc(new_list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (i + 1))) == NULL)) {
            free(crc_list);
            crc_list = new_list;
            allocated = i;

            // Adjust the size of the list based on the number of active UEs
            int new_num_ue = (int)(allocated * 1.5f);
            if (new_num_ue < num_ue) {
                return NULL; // Memory allocation failed
            } else {
                crc_list = new_list;
                break;
            }
        }

        crc_list[i].rx_UE_INFORMATION_TAG = i % 256;
        crc_list[i].RNTI = i % 65536;
        crc_list[i].CRC_INDICATION_REL8_TAG = (uint16_t)(i ^ (i >> 8));
        crc_list[i].CRCFLAG = rand() & 1;

        if (new_list != NULL) {
            new_list[i - 1] = crc_list[i];
        }
    }

    *p_num_allocated = allocated;
    return crc_list;
}

