#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} NFAPI_CRC_INDICATION_PDU_T;

int compare(const void *a, const void *b) {
    return (*(int*)a - *(int*)b);
}

void populateNFAPIList(int n, int *list, int maxRnti) {
    srand(time(NULL));
    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand() % maxRnti + 1;
        pdu.RNTI = rand() % maxRnti + 1;
        list[i] = pdu.RX_UE_INFORMATION_TAG * maxRnti + pdu.RNTI;
    }
}

void cleanupList(int *list, int n) {
    qsort(list, n, sizeof(int), compare);
    for (int i = 0; i < n; i++) {
        if (i > (n / 2)) {
            list[i] = -1; // Mark as deleted
        }
    }
}

void printList(int *list, int n) {
    printf("List: [");
    for (int i = 0; i < n; i++) {
        printf("%d", list[i]);
        if (i < n - 1)
            printf(", ");
    }
    printf("]\n");
}

void manageNFAPIList(int *list, int *n) {
    // Database fetching and management
    // ... (omitted for brevity)

    // Periodic cleanup
    while (*n > 1000) { // Optimal threshold
        cleanupList(list, *n);
        *n -= *n / 10; // Reduce the list size by 10%
    }
}

int main() {
    int n = 50;
    int maxRnti = 256;
    int *list = (int*)malloc(n * sizeof(int));
    populateNFAPIList(n, list, maxRnti);
    printList(list, n);
    manageNFAPIList(&n, &list);
    free(list);
    return 0;
}

