NFAPI_CRC_INDICATION_PDU_T* generate_list(int n) {
    if (n <= 0) return NULL; // edge case: invalid input size

    NFAPI_CRC_INDICATION_PDU_T* list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * 10); // initial allocation
    int current_size = 10;
    int last_index = -1;

    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* new_element = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (i % 2 == 0) { // set CRCFLAG to 1 every second element
            new_element->CRCFLAG = 1;
        } else {
            new_element->CRCFLAG = 0;
        }

        // populate RX_UE_INFORMATION_TAG and RNTI with unique values
        new_element->RX_UE_INFORMATION_TAG = i % current_size + 1;
        new_element->RNTI = (new_element->RX_UE_INFORMATION_TAG) * 2;

        if (i % 10 == 0 && i > 0) { // every 10th element has extended metadata
            time_t timestamp = time(NULL);
            int status_code = i % 100;
            new_element->timestamp = (int*) &timestamp;
            new_element->status_code = status_code;
        }

        if (i >= current_size) {
            // resize list when necessary
            NFAPI_CRC_INDICATION_PDU_T* old_list = realloc(list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (current_size * 2));
            if (!old_list) return NULL; // error: out of memory

            list = old_list;
            current_size *= 2;
        }

        if (i > last_index) {
            // maintain list integrity by copying elements
            for (int j = i - 1; j >= last_index; j--) {
                list[j] = list[j-1];
            }
            last_index = i;
        }

        list[i] = *new_element;

        free(new_element);
    }

    return list;
}
