#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_UES 100000
#define MAX_PDU_SIZE 1024

typedef struct {
    uint32_t ue_id;
    uint16_t mac_entity_id;
    pthread_mutex_t lock;
    int pdu_count;
    struct rlc_pdu *pdus;
} lte_ue_context;

typedef struct {
    uint8_t data[MAX_PDU_SIZE];
    size_t length;
} rlc_pdu;

lte_ue_context* create_lte_ue_context(uint32_t ue_id, uint16_t mac_entity_id) {
    lte_ue_context* context = (lte_ue_context*)malloc(sizeof(lte_ue_context));
    if (!context) return NULL;

    context->ue_id = ue_id;
    context->mac_entity_id = mac_entity_id;
    pthread_mutex_init(&context->lock, NULL);
    context->pdu_count = 0;
    context->pdus = NULL;

    return context;
}

void add_rlc_pdu(lte_ue_context* context, rlc_pdu pdu) {
    if (!context) return;

    pthread_mutex_lock(&context->lock);
    {
        int i = 0;
        struct rlc_pdu** pdus_array = &context->pdus;
        while (*pdus_array && i < MAX_PDU_SIZE) {
            i++;
            pdus_array = &(*pdus_array)->next;
        }

        if (i >= MAX_PDU_SIZE) {
            // RLC PDU array full, should handle this situation
            pthread_mutex_unlock(&context->lock);
            return;
        }

        *pdus_array = malloc(sizeof(struct rlc_pdu));
        if (!*pdus_array) {
            pthread_mutex_unlock(&context->lock);
            return;
        }

        (*pdus_array)->data = pdu.data;
        (*pdus_array)->length = pdu.length;
    }

    context->pdu_count++;
    pthread_mutex_unlock(&context->lock);
}

void free_lte_ue_context(lte_ue_context* context) {
    if (!context) return;

    pthread_mutex_lock(&context->lock);
    {
        struct rlc_pdu* current = context->pdus;
        while (current) {
            struct rlc_pdu* next = current->next;
            free(current);
            current = next;
        }

        context->pdu_count = 0;
        context->pdus = NULL;
    }

    pthread_mutex_unlock(&context->lock);

    free(context);
}
