prompt:
Write a C function that creates and populates a list of LTE_PHY_RX_TDD_FRAME structures, each containing a valid UE_ID and a set of LTE_PHY_RX_SYMBOL structures. Each symbol should have a valid antenna port, modulation scheme, and a signal strength value within a specified range. Use standard library functions for random number generation and memory allocation. Additionally, the function must handle dynamic changes in the number of frames and symbols, ensuring efficient memory management and minimal overhead. The function should also integrate with an external data source for UE_IDs and validate the generated signal strengths against predefined thresholds to ensure realistic simulation conditions.

```c
#include <stdlib.h>
#include <time.h>

typedef struct {
    int antenna_port;
    int modulation_scheme;
    int signal_strength;
} LTE_PHY_RX_SYMBOL;

typedef struct {
    int ue_id;
    LTE_PHY_RX_SYMBOL* symbols;
} LTE_PHY_RX_TDD_FRAME;

void create_and_populate_frames(int num_frames, int num_symbols, int min_strength, int max_strength, const char* ue_ids_file, LTE_PHY_RX_TDD_FRAME** frames) {
    // Read UE_IDs from an external file
    FILE* file = fopen(ue_ids_file, "r");
    if (file == NULL) {
        // Handle file opening failure
        return;
    }

    for (int i = 0; i < num_frames; i++) {
        frames[i] = (LTE_PHY_RX_TDD_FRAME*)malloc(sizeof(LTE_PHY_RX_TDD_FRAME));
        if (frames[i] == NULL) {
            // Handle allocation failure
            fclose(file);
            return;
        }
        fscanf(file, "%d", &frames[i]->ue_id);

        frames[i]->symbols = (LTE_PHY_RX_SYMBOL*)malloc(num_symbols * sizeof(LTE_PHY_RX_SYMBOL));
        if (frames[i]->symbols == NULL) {
            // Handle allocation failure
            free(frames[i]);
            fclose(file);
            return;
        }

        for (int j = 0; j < num_symbols; j++) {
            frames[i]->symbols[j].antenna_port = rand() % 4 + 1;
            frames[i]->symbols[j].modulation_scheme = rand() % 4 + 1;

