#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

typedef struct LTE_PHY_RACH_PDU_T {
    int PreambleIndex;
    LTE_PHY_RACH_TAG tag;
    LTE_PHY_RACH_INFO_REL15_TAG info;
} LTE_PHY_RACH_PDU_T;

typedef enum {
    SUCCESS,
    MAX_SIZE_EXCEEDED,
    DUPLICATE_TRANS_ID,
    INVALID_INPUT
} error_code_t;

error_code_t add_pdu_to_list(LTE_PHY_RACH_PDU_T **list, size_t *size, int max_size, const LTE_PHY_RACH_TAG tag, int preamble_index);
void clear_list(LTE_PHY_RACH_PDU_T **list, size_t *size);

int main() {
    // Initialize the list
    LTE_PHY_RACH_PDU_T *list = NULL;
    size_t list_size = 0;

    // Add PDUs to the list
    for (int i = 0; i < 10; i++) {
        int ret = add_pdu_to_list(&list, &list_size, 100, (LTE_PHY_RACH_TAG)i, i);
        if (ret != SUCCESS) {
            printf("Error adding PDU: %d\n", ret);
            break;
        }
    }

    // Clear the list
    clear_list(&list, &list_size);

    return 0;
}

error_code_t add_pdu_to_list(LTE_PHY_RACH_PDU_T **list, size_t *size, int max_size, const LTE_PHY_RACH_TAG tag, int preamble_index) {
    if (*size >= max_size) {
        return MAX_SIZE_EXCEEDED;
    }

    // Allocate memory for the new PDU
    LTE_PHY_RACH_PDU_T *new_pdu = (LTE_PHY_RACH_PDU_T *)malloc(sizeof(LTE_PHY_RACH_PDU_T));
    if (new_pdu == NULL) {
        return INVALID_INPUT;
    }

    // Generate a random trans ID
    int trans_id = rand();

    new_pdu->PreambleIndex = preamble_index;
    new_pdu->tag = tag;
    new_pdu->info.preamble_trans_id = trans_id;

    // Add the PDU to the list and update the size
    *list = (LTE_PHY_RACH_PDU_T *)realloc(*list, (*size + 1) * sizeof(LTE_PHY_RACH_PDU_T));
    if (*list == NULL) {
        free(new_pdu);
        return INVALID_INPUT;
    }
    (*list)[*size] = *new_pdu;

    *size += 1;

    // Check for duplicate trans ID
    for (int i = 0; i < *size; i++) {
        if ((*list)[i].info.preamble_trans_id == trans_id) {
            free(new_pdu);
            free(*list);
            *list = NULL;
            *size = 0;
            return DUPLICATE_TRANS_ID;
        }
    }

    // Free the temporary PDU memory
    free(new_pdu);

    return SUCCESS;
}

void clear_list(LTE_PHY_RACH_PDU_T **list, size_t *size) {
    if (*list == NULL || *size == 0) {
        return;
    }

    for (int i = 0; i < *size; i++) {
        free((*list + i));
    }

    free(*list);
    *list = NULL;
    *size = 0;
}
