    if (rnti_index >= 1000) {
        fprintf(stderr, "Request exceeded maximum capacity of 1000 elements.\n");
        exit(EXIT_FAILURE);
    }

    int random_rnti = rand();
    for (int i = 0; i < rnti_index; i++) {
        if (rntis[i] == random_rnti) {
            random_rnti = rand();
            i = -1;
        }
    }

    rntis[rnti_index++] = random_rnti;

    return random_rnti;
