            free(new_ue_context);
            return NULL;
        }

        new_ue_context->rscp = (double)rscp_value / 10.0; // Normalize RSCP value
        new_ue_context->snr = snr_value;

        if (*p_num_allocated == 0) {
            ue_contexts = new_ue_context;
            *p_num_allocated = 1;
        } else {
            LteUeContext** tail = &ue_contexts;
            while (*tail && (*tail)->next) {
                tail = &((*tail)->next);
            }
            (*tail)->next = new_ue_context;
            tail = &new_ue_context;
            *p_num_allocated += 1;
        }
    }

    return ue_contexts;
}

int main() {
    int num_ue = 1000; // Adjust as needed
    int allocated;

    LteUeContext* ue_contexts = generate_ue_contexts(num_ue, &allocated);

    if (ue_contexts) {
        for (int i = 0; i < allocated; i++) {
            printf("UE ID: %d, Cell ID: %d, RSCP: %.2f dBm, SNR: %.1f dB\n",
                   ue_contexts[i].ue_id, ue_contexts[i].cell_id,
                   ue_contexts[i].rscp, ue_contexts[i].snr);
        }
    }

    return 0;
}
