void readFloats(int* size, float** arr) {
    int i = 0;
    while (1) {
        float val;
        scanf("%f", &val);
        if (feof(stdin)) break;
        (*arr) = realloc((*arr), sizeof(float) * ++i);
        if (!(*arr)) {
            printf("Error: unable to allocate memory.\n");
            exit(EXIT_FAILURE);
        }
        (*arr)[i - 1] = val;
    }
    *size = i;
}

float findMax(float* arr, int size) {
    float max = arr[0];
    for (int i = 1; i < size; ++i) {
        if (arr[i] > max) max = arr[i];
    }
    return max;
}

void generateTemperatureData(int* size, TemperatureSensorData** arr) {
    int i = 0;
    while (1) {
        int timestamp;
        float temperature;
        scanf("%d %f", &timestamp, &temperature);
        if (feof(stdin)) break;
        (*arr) = realloc((*arr), sizeof(TemperatureSensorData) * ++i);
        if (!(*arr)) {
            printf("Error: unable to allocate memory.\n");
            exit(EXIT_FAILURE);
        }
        (*arr)[i - 1].timestamp = timestamp;
        (*arr)[i - 1].temperature = temperature;
    }
    *size = i;
}

int main() {
    int size;
    float* floatsArr;
    TemperatureSensorData* dataArr;

    readFloats(&size, &floatsArr);
    printf("Maximum value: %f\n", findMax(floatsArr, size));

    generateTemperatureData(&size, &dataArr);

    for (int i = 0; i < size; ++i) {
        printf("Timestamp: %d, Temperature: %.2f\n", dataArr[i].timestamp, dataArr[i].temperature);
    }

    free(floatsArr);
    free(dataArr);
    return 0;
}
