    // Initialize return value
    NFAPI_CRC_INDICATION_PDU_T **list = NULL;

    // Check if input parameter is valid
    if (n <= 0) {
        printf("Error: Invalid number of entries.\n");
        return list; // Return immediately to avoid memory leaks
    }

    // Allocate memory for the list and its elements
    list = (NFAPI_CRC_INDICATION_PDU_T **)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    if (!list) {
        printf("Error: Unable to allocate memory.\n");
        return NULL; // Return immediately to avoid memory leaks
