    long file_size = ftell(fp);
    rewind(fp);
    char *json_data = (char *)malloc((file_size + 1) * sizeof(char));
    fread(json_data, file_size, 1, fp);
    fclose(fp);
    json_data[file_size] = '\0';

    // Parse JSON data
    json_obj = json_object_from_string(json_data);
    if (!json_obj) {
        printf("Error: Unable to parse JSON.\n");
        free(json_data);
        return list; // Return immediately to avoid memory leaks
    }

    // Create and populate the list of NFAPI_CRC_INDICATION_PDU_T structures
    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            printf("Error: Unable to allocate memory.\n");
            return list; // Return immediately to avoid memory leaks
        }

        // Populate the RX_UE_INFORMATION_TAG and RNTI fields based on parsed JSON data
        strcpy(pdu->RX_UE_INFORMATION_TAG, json_object_get_string(json_obj, "RX_UE_INFORMATION_TAG"));
        pdu->RNTI = atoi(json_object_get_string(json_obj, "RNTI"));

        // Generate random CRCFLAG value
        srand(time(NULL));
        int crcflag = rand() % 2;

        // Populate the CRC_INDICATION_REL8_TAG field with generated CRCFLAG value
        sprintf(pdu->CRC_INDICATION_REL8_TAG, "%s", (crcflag ? "CRC_FLAG_SET" : "CRC_FLAG_NOT_SET"));

        // Add pdu to the list
        list[i] = pdu;
    }

    // Clean up after parsing JSON data and freeing allocated memory
    free(json_data);
    json_object_free(json_obj);

    return list; // Return the populated list of NFAPI_CRC_INDICATION_PDU_T structures
}

int main() {
    int n = 10; // Number of entries in the list
    const char* json_file = "ue_info.json"; // File containing JSON data

