typedef struct {
    int value;
    char name[32];
} record;

record* initRecords(int count) {
    if (count <= 0) {
        printf("Invalid number of records. Exiting.\n");
        return NULL;
    }

    long* offsets = malloc(count * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Memory allocation failed for offset array.\n");
        free(NULL);
        return NULL;
    }
    int i;
    for (i = 0; i < count; i++) {
        offsets[i] = i;
    }

    int* keys = malloc(count * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Memory allocation failed for key array.\n");
        free(offsets);
        return NULL;
    }
    for (i = 1; i < count; i++) {
        keys[i] = i;
    }

    record* records = malloc(count * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for record array.\n");
        free(keys);
        free(offsets);
        return NULL;
    }
    srand(time(NULL)); // seed random number generator
    for (i = 0; i < count; i++) {
        records[i].value = rand() % 100; // generate a random integer between 0 and 99
        sprintf(records[i].name, "Record_%d", i); // derive the name from the index
    }

    return records;
}

void freeRecords(record* records) {
    if (records) {
        free((void*)records);
    }
}
