#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

typedef struct {
    unsigned char tag;
    unsigned short rnti;
} RX_UE_INFORMATION_TAG;

typedef struct {
    enum { CRCFLAG_UNKNOWN, CRCFLAG_VALID, CRCFLAG_INVALID } flag;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    CRC_INDICATION_REL8_TAG crc_indication_rel8;
} NFAPI_CRC_INDICATION_PDU_T;

int create_and_populate_list(int n) {
    int failed_allocations = 0, successful_allocations = 0;
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = NULL;

    // Initialize logging and error handling
    set_log_level(LOG_INFO);
    set_error_handling(ERR_CONTINUE);

    // Allocate memory for the list
    pdu_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        log_error("Memory allocation failed");
        return -1;
    }

    srand(time(NULL));  // Initialize random number generator

    for (int i = 0; i < n; i++) {
        RX_UE_INFORMATION_TAG rx_ue_info;
        rx_ue_info.tag = (unsigned char)(rand() % 256);
        unsigned short rnti = (unsigned short)(rand() % 65536) + 1;

        if (!validate_rnti(rnti)) {
            log_warning("Invalid RNTI");
            continue;
        }

        CRC_INDICATION_REL8_TAG crc_indication_rel8;
        crc_indication_rel8.flag = CRCFLAG_VALID;

        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.rx_ue_info = rx_ue_info;
        pdu.crc_indication_rel8 = crc_indication_rel8;

        // Add the structure to the list
        if (!add_to_list(&pdu, &pdu_list)) {
            failed_allocations++;
            continue;
        }

        successful_allocations++;

        log_debug("Created NFAPI_CRC_INDICATION_PDU_T");
    }

    // Log statistics
    log_info("Total allocations: %d", successful_allocations);
    log_info("Failed allocations: %d", failed_allocations);

    free(pdu_list);
    return 0;
}

int validate_rnti(unsigned short rnti) {
