// Define structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define structure for the list of NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    int size;
    int capacity;
    pthread_mutex_t lock;
    sqlite3* db;
} NFAPI_CRC_INDICATION_PDU_T_List;

// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
int create_list(int N, NFAPI_CRC_INDICATION_PDU_T_List** list) {
    // Initialize the list
    *list = (NFAPI_CRC_INDICATION_PDU_T_List*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T_List));
    (*list)->data = NULL;
    (*list)->size = 0;
    (*list)->capacity = 2; // Start with a small capacity and resize as needed
    pthread_mutex_init(&((*list)->lock), NULL);
    sqlite3_open("nfacrc_indication_pdu_t.db", &((*list)->db));

    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T* p = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        p->RX_UE_INFORMATION_TAG = rand() % 100;
        p->RNTI = rand() % 256;
        p->CRCFLAG = rand() % 2;

        // Resize the list if necessary
        if ((*list)->size >= (*list)->capacity) {
            (*list)->data = (NFAPI_CRC_INDICATION_PDU_T*)realloc((*list)->data, sizeof(NFAPI_CRC_INDICATION_PDU_T)*(*list)->capacity*2);
            (*list)->capacity *= 2;
        }

        // Add the new element to the list
        if ((*list)->size == 0) {
            (*list)->data = p;
        } else {
            NFAPI_CRC_INDICATION_PDU_T* last = (*list)->data + (*list)->size - 1;
            p->RX_UE_INFORMATION_TAG = last->RX_UE_INFORMATION_TAG;
            p->RNTI = last->RNTI;
            p->CRCFLAG = last->CRCFLAG;
        }

        (*list)->size++;

        // Insert into database
        sqlite3_stmt* stmt;
