    public void Serialize(NFAPI_CRC_INDICATION_PDU_T[] list, string filename) {
        using (FileStream stream = new FileStream(filename, FileMode.Create)) {
            BinaryWriter writer = new BinaryWriter(stream);
            foreach (NFAPI_CRC_INDICATION_PDU_T pdu in list) {
                writer.Write(pdu.RX_UE_INFORMATION_TAG);
                writer.Write(pdu.RNTI);
                writer.Write(pdu.CRCFLAG);
            }
        }
    }

    public NFAPI_CRC_INDICATION_PDU_T[] Deserialize(string filename) {
        NFAPI_CRC_INDICATION_PDU_T[] list = null;
        using (FileStream stream = new FileStream(filename, FileMode.Open)) {
            BinaryReader reader = new BinaryReader(stream);
            int count = reader.ReadInt32();
            list = new NFAPI_CRC_INDICATION_PDU_T[count];
            for (int i = 0; i < count; i++) {
                NFAPI_CRC_INDICATION_PDU_T pdu = new NFAPI_CRC_INDICATION_PDU_T();
                pdu.RX_UE_INFORMATION_TAG = reader.ReadInt32();
                pdu.RNTI = reader.ReadInt32();
                pdu.CRCFLAG = reader.ReadInt32();
                list[i] = pdu;
            }
        }
