// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* create_list(int n, int* rntis, FILE* log_file) {
    // Initialize variables
    NFAPI_CRC_INDICATION_PDU_T* list = NULL;
    int num_created = 0;
    int max_rnti = -1;

    // Loop until we have created 'n' structures or run out of memory
    for (int i = 0; i < n && (list == NULL || num_created < n); i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        // If memory allocation fails, exit the loop and free any allocated structures
        if (pdu == NULL) {
            for (int j = 0; j < num_created; j++) {
                free(&list[j]);
            }
            free(list);
            return NULL;
        }

        // Randomly generate a valid RX_UE_INFORMATION_TAG
        int tag = rand() % 100 + 1;

        // Check if the generated tag is within the valid range (0-100)
        if (tag < 0 || tag > 100) {
            fprintf(log_file, "Warning: Invalid RX_UE_INFORMATION_TAG '%d'\n", tag);
            free(pdu);
            continue;
        }

        // Randomly generate a unique RNTI
        int rnti = rand() % 256 + 1;
        while (rntis != NULL && strchr(rntis, '\0') == NULL) {
            for (int j = 0; j < num_created; j++) {
                if (strcmp(&list[j].RX_UE_INFORMATION_TAG, &pdu->RX_UE_INFORMATION_TAG) == 0 &&
                    list[j].RNTI == rnti) {
                    // If a duplicate RNTI is found, generate another one
                    rnti = rand() % 256 + 1;
                }
            }
        }

        if (rntis != NULL && strchr(rntis, '\0') == NULL) {
            fprintf(log_file, "Warning: Duplicate RNTI '%d'\n", rnti);
            free(pdu);
            continue;
        }

        // Randomly set CRCFLAG
        int crcflag = rand() % 2;

        pdu->RX_UE_INFORMATION_TAG = tag;
        pdu->RNTI = rnti;
        pdu->CRC_INDICATION_REL8_TAG.crcflag = crcflag;

        if (list == NULL) {
            list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T*) * n);
            list[num_created] = pdu;
        } else {
            list = realloc(list, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * (num_created + 1));
            list[num_created] = pdu;
        }

        num_created++;
    }

    return list;
}

int main() {
    // Example usage
    int n = 10;
    FILE* log_file = fopen("log.txt", "w");
    int rntis[] = {"0x01", "0x02", "0x03", ...};
    NFAPI_CRC_INDICATION_PDU_T* list = create_list(n, rntis, log_file);

    // Handle the list
    for (int i = 0; i < n; i++) {
        printf("%s RNTI: %d CRCFLAG: %d\n", &list[i].RX_UE_INFORMATION_TAG, list[i].RNTI, list[i].CRC_INDICATION_REL8_TAG.crcflag);
    }

    fclose(log_file);

    return 0;
}
