typedef struct Node {
    NFAPI_CRC_INDATION_PDU_T data;
    struct Node* next;
} Node;

Node* createList(int n) {
    if (n > 1000) {
        printf("Error: Maximum capacity of 1000 exceeded.\n");
        return NULL;
    }

    srand(time(NULL)); // seed for random number generation

    Node* head = NULL;
    for (int i = 0; i < n; i++) {
        Node* newNode = (Node*)malloc(sizeof(Node));
        if (!newNode) {
            printf("Error: Memory allocation failed.\n");
            return head;
        }

        NFAPI_CRC_INDICATION_PDU_T data;
        data.RNTI = rand() % 1000; // generate a random RNTI
        data.RX_UE_INFORMATION_TAG = rand() % 1000; // generate a random RX_UE_INFORMATION_TAG
        if (rand() % 2) { // randomly set CRCFLAG to 1 or 0
            data.CRCFLAG = 1;
        } else {
            data.CRCFLAG = 0;
        }

        newNode->data = data;
        newNode->next = head;
        head = newNode;
    }

    return head;
}

void freeList(Node* head) {
    while (head) {
        Node* temp = head;
        head = head->next;
        free(temp);
    }
}
