```c
#include <stdlib.h>
#include <time.h>

typedef struct UplinkTb {
    int tb_size;
    int harq_initiated;
} UplinkTb;

typedef struct LteUeContext {
    int ue_id;
    UplinkTb *tbs;
    struct LteUeContext *next;
} LteUeContext;

void free_ue_context_list(LteUeContext **ue_contexts) {
    LteUeContext *temp = *ue_contexts;
    LteUeContext *curr = temp;

    while (curr != NULL) {
        LteUeContext *next = curr->next;
        for (int i = 0; i < curr->tbs; i++) {
            free(&curr->tbs[i]);
        }
        free(curr);
        curr = next;
    }

    *ue_contexts = NULL;
}

void populate_ue_context_list(int num_contexts, LteUeContext **ue_contexts) {
    srand(time(NULL));

    for (int i = 0; i < num_contexts; i++) {
        LteUeContext *ue_ctx = (LteUeContext *)malloc(sizeof(LteUeContext));
        if (ue_ctx == NULL) continue;

        ue_ctx->ue_id = i + 1;

        int num_tbs = rand() % 5 + 1;
        ue_ctx->tbs = (UplinkTb *)malloc(num_tbs * sizeof(UplinkTb));
        if (ue_ctx->tbs == NULL) {
            free(ue_ctx);
            continue;
        }

        for (int j = 0; j < num_tbs; j++) {
            UplinkTb *tb = &ue_ctx->tbs[j];
            tb->tb_size = rand() % 1024 + 1;
            tb->harq_initiated = rand() % 2;
        }

        if (*ue_contexts == NULL) {
            *ue_contexts = ue_ctx;
        } else {
            LteUeContext *curr = *ue_contexts;
            while (curr->next != NULL) {
                curr = curr->next;
            }
            curr->next = ue_ctx;
        }
    }
}
