void create_crc_indication_pdu_list(int n, FILE* log_file) {
    srand(time(NULL)); // seed random number generator

    // initialize list and its size
    NFAPI_CRC_INDICATION_PDU_T** list = NULL;
    int list_size = 0;

    // function to dynamically resize the list
    void* resize_list(int new_size) {
        void* old_list = list;
        list = realloc(list, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        if (!list) {
            free(old_list);
            return NULL; // memory allocation failed
        }
        memset(&((NFAPI_CRC_INDICATION_PDU_T**)list)[new_size - 1], 0,
               (new_size - list_size) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        return list;
    }

    // main loop to create and populate the list
    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            fprintf(log_file, "Error allocating memory at iteration %d.\n", i);
            continue;
