        // generate random RNTI and CRC FLAG values
        pdu->rnti = rand() % 1000; // adjust the range as needed
        pdu->crcflag = (rand() & 1) ? 1 : 0; // toggle bit

        // add the new pdu to the list, resizing if necessary
        int new_size = list_size + 1;
        if (!list || new_size > list_size) {
            list = resize_list(new_size);
            list_size = new_size;
        }
        ((NFAPI_CRC_INDICATION_PDU_T**)list)[i] = pdu;

        // log relevant information for debugging
        fprintf(log_file, "PDU %d: RNTI=%d, CRCFLAG=%d\n", i, pdu->rnti, pdu->crcflag);
