typedef struct {
    int ue_id;
    int cell_id;
    int mac_pdu;
    int crc_flag;
    time_t access_time;
    int access_count;
} LTEUEContext;

typedef struct node {
    LTEUEContext context;
    struct node* prev;
    struct node* next;
} Node;

Node* head = NULL;
Node* tail = NULL;
int max_size = 1000;
int current_size = 0;

LTEUEContext* create_ue_context(int ue_id, int cell_id) {
    LTEUEContext* context = (LTEUEContext*)malloc(sizeof(LTEUEContext));
    context->ue_id = ue_id;
    context->cell_id = cell_id;
    context->mac_pdu = rand() % 1000000;
    context->crc_flag = rand() % 2;
    time(&context->access_time);
    context->access_count = 1;
    return context;
}

void remove_ue_context(Node* node) {
    if (node->prev != NULL)
        node->prev->next = node->next;
    else
        head = node->next;

    if (node->next != NULL)
        node->next->prev = node->prev;
    else
        tail = node->prev;

    free(node);
}

void add_ue_context(int ue_id, int cell_id) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->context = create_ue_context(ue_id, cell_id);

    if (current_size >= max_size) {
        remove_ue_context(head);
        head = head->next;
        current_size--;
    }

    if (head == NULL) {
        head = new_node;
        tail = new_node;
    } else {
        new_node->prev = tail;
        tail->next = new_node;
        tail = new_node;
    }
    current_size++;
}

void free_ue_contexts() {
    Node* node = head;
    while (node != NULL) {
        remove_ue_context(node);
        node = node->next;
    }
}
