struct record {
    int key;
    int value;
};

void generateRecords(int n, struct record **records) {
    srand(time(NULL)); // seed random number generator

    *records = (struct record *)malloc(n * sizeof(struct record));
    if (*records == NULL) {
        printf("Memory allocation failed\n");
        return;
    }

    for (int i = 0; i < n; i++) {
        (*records)[i].key = rand() % 100; // random key
        (*records)[i].value = rand() % 50 + 1; // random value within range [1, 50]
    }
}

void sortRecords(int n, struct record *records) {
    int i, j;
    for (i = 0; i < n - 1; i++) {
        for (j = 0; j < n - i - 1; j++) {
            if (records[j].key > records[j + 1].key) {
                struct record temp = records[j];
                records[j] = records[j + 1];
                records[j + 1] = temp;
            }
        }
    }
}

int main() {
    int n = 10; // number of records to generate
    struct record *records;

    generateRecords(n, &records);
    sortRecords(n, records);

    for (int i = 0; i < n; i++) {
        printf("Key: %d, Value: %d\n", records[i].key, records[i].value);
    }

    free(records); // deallocate memory

    return 0;
}
