void create_and_populate_nfa_pi_crc_indication_pdu_list(int num_entries, NFAPI_CRC_INDICATION_PDU_T** list) {
    // Initialize the list with a default capacity
    *list = (NFAPI_CRC_INDICATION_PDU_T**)malloc(num_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (*list == NULL) {
        printf("Memory allocation failed\n");
        return;
    }

    for (int i = 0; i < num_entries; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (pdu == NULL) {
            printf("Memory allocation failed\n");
            return;
