        pdu->rnti = rand() % 65536;  // Replace with actual implementation

        // Generate a random CRCFLAG
        uint16_t crcflag;
        do {
            crcflag = (uint16_t)rand();
        } while (crcflag == 0);  // Ensure non-zero value for the CRC flag

        pdu->crc_indication_rel8_tag.crcflag = crcflag;

        // Validate the generated CRCFLAG using the external CRC calculation function
        uint16_t calculated_crc;
        int retry_count = 0;
        do {
            calculated_crc = crc_calc((const uint8_t*)&pdu->rx_ue_info_tag, sizeof(pdu->rx_ue_info_tag) + sizeof(pdu->rnti) + sizeof(pdu->crc_indication_rel8_tag));
            if (calculated_crc != pdu->crc_indication_rel8_tag.crcflag) {
                // CRC calculation failed; retry with a new random value for the CRC flag
                crcflag = (uint16_t)rand();
                pdu->crc_indication_rel8_tag.crcflag = crcflag;
                retry_count++;
                if (retry_count > 10) {  // Set a maximum number of retries
                    printf("CRC calculation failed after %d retries\n", retry_count);
                    return;
                }
            }
        } while (calculated_crc != pdu->crc_indication_rel8_tag.crcflag);

        (*list)[i] = pdu;
    }
}

// Thread-safe wrapper for reallocation and assignment of the list
void nfa_pi_crc_indication_pdu_list_realloc(int new_capacity, NFAPI_CRC_INDICATION_PDU_T** list) {
    void* temp = realloc(*list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (temp == NULL) {
        printf("Memory reallocation failed\n");
        return;
    }
    *list = temp;
}

// Helper function to expand the list capacity
void nfa_pi_crc_indication_pdu_list_expand(int new_capacity, NFAPI_CRC_INDICATION_PDU_T** list) {
    while (new_capacity > (int)sqrt((size_t)new_capacity)) {
        nfa_pi_crc_indication_pdu_list_realloc(new_capacity + 1, list);
        new_capacity++;
    }
}
