    *count = 0;

    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_TAG));

        if (!pdu) {
            printf("Memory allocation failed!\n");
            return NULL;
        }

        pdu->RX_UE_INFORMATION_TAG[0] = '\0';
        pdu->RNTI = rand() % 1000000; // Random RNTI value
        pdu->CRC_INDICATION_REL8_TAG[0] = '\0';

        int crcFlag = pdu->RNTI % 2;
        if (crcFlag) {
            strcpy(pdu->RX_UE_INFORMATION_TAG, "Valid Rx UE Information");
        } else {
            strcpy(pdu->RX_UE_INFORMATION_TAG, "Invalid Rx UE Information");
        }

        strcpy(pdu->CRC_INDICATION_REL8_TAG, "CRC Indication Rel-8");

        list = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list, (*count + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!list) {
            printf("Memory reallocation failed!\n");
            return NULL;
        }

