#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int ue_id;
    int cell_id;
    char* srb1_config;
} RRCConnectionReconfig;

typedef struct {
    int ue_id;
    int cell_id;
    int num_reconfigs;
    RRCConnectionReconfig** reconfigs;
} LTEUEContext;

LTEUEContext* create_ue_context(int ue_id, int cell_id) {
    LTEUEContext* ctx = (LTEUEContext*)malloc(sizeof(LTEUEContext));
    if (!ctx) return NULL; // Error: unable to allocate memory

    ctx->ue_id = ue_id;
    ctx->cell_id = cell_id;
    ctx->num_reconfigs = 0;

    return ctx;
}

RRCConnectionReconfig* create_reconfig(int srb1_config, int num_dedicated_bearers) {
    RRCConnectionReconfig* reconfig = (RRCConnectionReconfig*)malloc(sizeof(RRCConnectionReconfig));
    if (!reconfig) return NULL; // Error: unable to allocate memory

    reconfig->srb1_config = malloc(strlen("SRB1 Config") + 1);
    strcpy(reconfig->srb1_config, "SRB1 Config");
    reconfig->num_dedicated_bearers = num_dedicated_bearers;

    return reconfig;
}

void add_reconfig(LTEUEContext* ctx, RRCConnectionReconfig* reconfig) {
    RRCConnectionReconfig** new_reconfigs = (RRCConnectionReconfig**)realloc(ctx->reconfigs, (ctx->num_reconfigs + 1) * sizeof(RRCConnectionReconfig*));
    if (!new_reconfigs) return; // Error: unable to reallocate memory

    ctx->reconfigs = new_reconfigs;
    ctx->reconfigs[ctx->num_reconfigs] = reconfig;

    ctx->num_reconfigs++;
}

void free_ue_context(LTEUEContext* ctx) {
    for (int i = 0; i < ctx->num_reconfigs; i++) {
        free(ctx->reconfigs[i]->srb1_config);
        free(ctx->reconfigs[i]);
    }
    free(ctx->reconfigs);
    free(ctx);
}

void serialize_ue_context(LTEUEContext* ctx, FILE* file) {
    fwrite(&ctx->ue_id, sizeof(int), 1, file);
    fwrite(&ctx->cell_id, sizeof(int), 1, file);
    fwrite(&ctx->num_reconfigs, sizeof(int), 1, file);

    for (int i = 0; i < ctx->num_reconfigs; i++) {
        RRCConnectionReconfig* reconfig = ctx->reconfigs[i];
        fwrite(&reconfig->srb1_config, strlen(reconfig->srb1_config) + 1, 1, file);
        fwrite(&reconfig->num_dedicated_bearers, sizeof(int), 1, file);
    }
}

LTEUEContext* deserialize_ue_context(FILE* file) {
    LTEUEContext* ctx = (LTEUEContext*)malloc(sizeof(LTEUEContext));
    if (!ctx) return NULL; // Error: unable to allocate memory

    fread(&ctx->ue_id, sizeof(int), 1, file);
    fread(&ctx->cell_id, sizeof(int), 1, file);
    fread(&ctx->num_reconfigs, sizeof(int), 1, file);

    ctx->reconfigs = (RRCConnectionReconfig**)malloc(ctx->num_reconfigs * sizeof(RRCConnectionReconfig*));
    for (int i = 0; i < ctx->num_reconfigs; i++) {
        RRCConnectionReconfig* reconfig = (RRCConnectionReconfig*)malloc(sizeof(RRCConnectionReconfig));
        if (!reconfig) return NULL; // Error: unable to allocate memory

        fread(reconfig->srb1_config, strlen("SRB1 Config") + 1, 1, file);
        fread(&reconfig->num_dedicated_bearers, sizeof(int), 1, file);

        ctx->reconfigs[i] = reconfig;
    }

    return ctx;
}
