function traverseDOMTree(rootNode, selector) {
    const allowedChars = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-';
    const sizeLimit = 50;

    function recursiveTraverse(node) {
        let matchingElements = [];

        if (node.nodeName === selector) {
            node.className.forEach(className => {
                if (testElementClassOrId(node, className)) {
                    matchingElements.push(node);
                }
            });
        }

        Array.from(node.children).forEach(recursiveTraverse);

        return matchingElements;
    }

    function testElementClassOrId(element, className) {
        let matches = false;

        for (let i = 0; i < element.className.length; i++) {
            if (element.className[i] === className) {
                matches = true;
                break;
