    int *used_rntis = (int *)malloc(rnti_range * sizeof(int));
    if (!used_rntis) {
        fprintf(log_file, "Error: Memory allocation failed for used RNTIs.\n");
        free(*crc_indication_list);
        fclose(log_file);
        return -1; // error allocating memory
    }

    for (int i = 0; i < num_pdus; i++) {
        int rnti = rand() % rnti_range + 1;
        while (used_rntis[rnti] == 1) {
            rnti = rand() % rnti_range + 1;
        }
        used_rntis[rnti] = 1;

        (*crc_indication_list)[i].RX_UE_INFORMATION_TAG = i;
        (*crc_indication_list)[i].RNTI = rnti;
        (*crc_indication_list)[i].CRC_INDICATION_REL8_TAG = rand() % 2; // random CRCFLAG

        if (fputs("Warning: Potential delay in receiving external data source.\n", log_file) == EOF) {
            fprintf(log_file, "Error: Failed to write to log file.\n");
            free(used_rntis);
            free(*crc_indication_list);
            fclose(log_file);
