int populate_crc_indication_list(int num_pdus, NFAPI_CRC_INDICATION_PDU_T **crc_indication_list) {
    NFAPI_CRC_INDATION_PDU_T *pdus = NULL;
    int rnti = 0, i = 0;

    // Allocate memory for the list
    pdus = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        return -1;  // Memory allocation failed
    }

    // Initialize random number generator
    srand(time(NULL));

    for (i = 0; i < num_pdus; i++) {
        pdus[i].RX_UE_INFORMATION_TAG = i;
        do {
            rnti = rand() % (65535 - 1 + 1) + 1;  // Generate random RNTI within valid range
        } while (rnti <= 0 || find_rnti(pdus, num_pdus, rnti));  // Ensure unique RNTI

        pdus[i].RNTI = rnti;
        pdus[i].CRC_INDICATION_REL8_TAG = i;
        pdus[i].CRCFLAG = rand() % 2;  // Randomly set CRCFLAG to either 0 or 1
    }

    qsort(pdus, num_pdus, sizeof(NFAPI_CRC_INDICATION_PDU_T), compare_rnti);

    *crc_indication_list = pdus;

    return 0;
}

int find_rnti(NFAPI_CRC_INDICATION_PDU_T *pdus, int num_pdus, int rnti) {
    for (int i = 0; i < num_pdus; i++) {
        if (pdus[i].RNTI == rnti) {
            return 1;  // RNTI found
        }
    }
    return 0;  // RNTI not found
}

int compare_rnti(const void *a, const void *b) {
    NFAPI_CRC_INDICATION_PDU_T *pdu_a = (NFAPI_CRC_INDICATION_PDU_T *)a;
    NFAPI_CRC_INDICATION_PDU_T *pdu_b = (NFAPI_CRC_INDICATION_PDU_T *)b;

    if (pdu_a->RNTI < pdu_b->RNTI) {
        return -1;  // a comes before b
    } else if (pdu_a->RNTI > pdu_b->RNTI) {
        return 1;   // a comes after b
    } else {
        return 0;  // a and b have the same RNTI
    }
}
