AP** createAPList(int initialSize) {
    // Initialize the list with the given initial size.
    AP** apList = (AP**) malloc(initialSize * sizeof(AP*));

    if (!apList) return NULL;  // Handle memory allocation error

    for (int i = 0; i < initialSize; i++) {
        apList[i] = (AP*) malloc(sizeof(struct AP));

        if (!apList[i]) return NULL;  // Handle memory allocation error

        // Initialize AP structure with random values
        apList[i]->id = rand();
        apList[i]->channel = rand() % 14;
        apList[i]->signalStrength = (float) rand() / RAND_MAX;
    }

    return apList;
}

// Function to dynamically resize the list of Wi-Fi Access Point (AP) structures.
void resizeAPList(AP** apList, int newSize) {
    // Calculate the difference in size
    int diff = newSize - sizeof(apList[0]);

    // Resize the array using realloc
    apList = (AP**) realloc(apList, newSize * sizeof(AP*));

    if (!apList) return;  // Handle memory allocation error

    for (int i = newSize - diff; i < newSize; i++) {
        apList[i] = (AP*) malloc(sizeof(struct AP));

        if (!apList[i]) return;  // Handle memory allocation error

        // Initialize AP structure with random values
        apList[i]->id = rand();
        apList[i]->channel = rand() % 14;
        apList[i]->signalStrength = (float) rand() / RAND_MAX;
    }
}

// Function to free the list of Wi-Fi Access Point (AP) structures.
void freeAPList(AP** apList, int size) {
    for (int i = 0; i < size; i++) {
        if (apList[i]) free(apList[i]);
    }

    // Free the array itself
    free(apList);
}
