#define INITIAL_CAPACITY 10
#define REALLOCATION_FACTOR 1.5

typedef struct {
    uint8_t RX_UE_INFORMATION_TAG;
    int RNTI;
} NFAPI_CRC_INDICATION_PDU_T;

void log_info(const char *format, ...) {
    // implement logging mechanism here
