int create_crc_indication_pdu_list(int num_puds) {
    NFAPI_CRC_INDICATION_PDU_T **pud_list = NULL;
    int list_size = 0;
    int capacity = INITIAL_CAPACITY;

    pud_list = (NFAPI_CRC_INDATION_PDU_T **)malloc(sizeof(NFAPI_CRC_INDATION_PDU_T *) * capacity);
    if (!pud_list) {
        log_error("Memory allocation failed");
        return -1;
    }

    for (int i = 0; i < num_puds && i < capacity; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pud = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!pud) {
            log_error("Memory allocation failed");
            free_pud_list(pud_list, list_size);
            return -1;
        }

        pud->RX_UE_INFORMATION_TAG = rand() % 256;
        pud->RNTI = rand();

        // generate random CRCFLAG
        int crcflag = rand() % 2; // assuming only two possible values

        CRC_INDICATION_REL8_TAG *crc_tag = (CRC_INDICATION_REL8_TAG *)malloc(sizeof(CRC_INDICATION_REL8_TAG));
        if (!crc_tag) {
            log_error("Memory allocation failed");
            free_pud(pud);
            return -1;
        }

        crc_tag->CRCFLAG = crcflag;

        // timestamp and log the creation of each structure
        struct timeval tv;
        gettimeofday(&tv, NULL);
        log_info("Created PDU %d at time %.6f", i + 1, (double)tv.tv_sec + tv.tv_usec / 1000000.0);

        pud->crc_tag = crc_tag;

        if (list_size == capacity) {
            capacity *= REALLOCATION_FACTOR;
            pud_list = (NFAPI_CRC_INDICATION_PDU_T **)realloc(pud_list, sizeof(NFAPI_CRC_INDATION_PDU_T *) * capacity);
            if (!pud_list) {
                log_error("Memory reallocation failed");
                free_pud(pud);
                return -1;
            }
        }

        pud_list[list_size++] = pud;
    }

    // handle cases where the initial capacity is exceeded
    while (list_size >= capacity / 2 && capacity < 1024 * 1024) { // adjust threshold as needed
        capacity *= REALLOCATION_FACTOR;
        pud_list = (NFAPI_CRC_INDICATION_PDU_T **)realloc(pud_list, sizeof(NFAPI_CRC_INDATION_PDU_T *) * capacity);
        if (!pud_list) {
            log_error("Memory reallocation failed");
            free_pud_list(pud_list, list_size);
            return -1;
        }
    }

    return 0;
}

void free_pud_list(NFAPI_CRC_INDICATION_PDU_T **pud_list, int size) {
    for (int i = 0; i < size; i++) {
        if (pud_list[i]->crc_tag) {
            free(pud_list[i]->crc_tag);
        }
        free(pud_list[i]);
    }
    free(pud_list);
}

void free_pud(NFAPI_CRC_INDICATION_PDU_T *pud) {
    if (pud->crc_tag) {
        free(pud->crc_tag);
    }
    free(pud);
}
