#include <string.h>
#include <pthread.h>

// Define the maximum number of PDUs
#define MAX_PDU 1000

// Structure to represent a NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_ind_rel8_tag;
} PDU;

// Structure to hold the list of PDUs and its operations
typedef struct {
    PDU *pdus; // dynamically resizable array
    int size; // current number of PDUs
    int max_size; // maximum allowed number of PDUs
    pthread_mutex_t lock; // mutex for thread safety
} PDU_List;

// Function to create a list of NFAPI_CRC_INDICATION_PDU_T structures
PDU_List *create_pdu_list(int initial_max_size) {
    PDU_List *list = (PDU_List *)malloc(sizeof(PDU_List));
    if (!list) return NULL;

    // Set the initial maximum size and allocate memory for the first PDUs
    list->max_size = initial_max_size;
    list->size = 0;
    list->pdus = (PDU *)calloc(list->max_size, sizeof(PDU));
    if (!list->pdus) {
        free(list);
        return NULL;
    }

    // Initialize the mutex for thread safety
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

// Function to add a new PDU to the list
int add_pdu(PDU_List *list, PDU *pdu) {
    int i = 0;
    int free_index = -1; // index of the first empty slot

    pthread_mutex_lock(&list->lock);

    for (i = 0; i < list->size; i++) {
        if (!list->pdus[i].rx_ue_info.tag) { // found an empty slot
            free_index = i;
            break;
        }
    }

    if (free_index == -1) { // need to grow the array
        int new_size = list->max_size * 2; // double the current size

        PDU *new_pdus = (PDU *)realloc(list->pdus, new_size * sizeof(PDU));
        if (!new_pdus) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }

        list->max_size = new_size;
        list->pdus = new_pdus;
    } else { // found an empty slot
        free_index++;
    }

    // copy the pdu to the first available position
    if (free_index >= 0) {
        memcpy(&list->pdus[free_index], pdu, sizeof(PDU));
        list->size = free_index + 1;
    } else { // unable to allocate memory for the new PDU
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    pthread_mutex_unlock(&list->lock);
    return 0; // successful addition of a new PDU
}

// Function to remove a PDU from the list
int remove_pdu(PDU_List *list, int index) {
    if (index < 0 || index >= list->size) { // out-of-range request
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    memmove(&list->pdus[index], &list->pdus[index + 1], (list->size - index - 1) * sizeof(PDU));

    list->size--;

    pthread_mutex_unlock(&list->lock);
    return 0; // successful removal of a PDU
}

// Function to log the number of PDUs added and removed
void log_pdu_operations(int num_added, int num_removed) {
    printf("Added %d PDUs and removed %d PDUs.\n", num_added, num_removed);
}
