```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_MESSAGES 1000
#define MESSAGE_SIZE sizeof(struct RrcMessage)

typedef struct RrcMessage {
    int ueIdentity;
    int sequenceNumber;
} RrcMessage;

RrcMessage *messages = NULL;
int messageCount = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void insertMessage(RrcMessage *msg) {
    pthread_mutex_lock(&mutex);

    if (messageCount >= MAX_MESSAGES) {
        printf("Error: Maximum number of messages reached.\n");
    } else {
        msg->next = NULL;
        if (messages == NULL || messageCount == 0) {
            messages = msg;
        } else {
            RrcMessage *tail = messages;
            while (tail->next != NULL) {
                tail = tail->next;
            }
            tail->next = msg;
        }
        messageCount++;
    }

    pthread_mutex_unlock(&mutex);
}

void removeMessage(int sequenceNumber) {
    pthread_mutex_lock(&mutex);

    RrcMessage *prev = NULL;
    RrcMessage *curr = messages;

    while (curr != NULL && curr->sequenceNumber != sequenceNumber) {
        prev = curr;
        curr = curr->next;
    }

    if (curr == NULL) {
        printf("Error: Message not found.\n");
    } else {
        if (prev == NULL) {
            messages = messages->next;
        } else {
            prev->next = curr->next;
        }
        messageCount--;

        free(curr);
    }

    pthread_mutex_unlock(&mutex);
}

void printMessages() {
    pthread_mutex_lock(&mutex);

    RrcMessage *curr = messages;

    printf("RRC Messages: \n");
    while (curr != NULL) {
        printf("UE Identity: %d, Sequence Number: %d\n", curr->ueIdentity, curr->sequenceNumber);
        curr = curr->next;
    }

    pthread_mutex_unlock(&mutex);
}

