#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    // ... (other fields)
} RX_UE_INFORMATION_TAG;

typedef struct {
    // ... (other fields)
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    int rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

int create_crc_indications(NFAPI_CRC_INDICATION_PDU_T **crc_list, int n, int seed) {
    if (n < 1 || n > 1000) return -1; // error code for invalid input

    *crc_list = NULL;
    srand(seed); // initialize random seed with provided value
    int total_crc_indications = 0;

    struct timespec start, end;
    clock_gettime(CLOCK_REALTIME, &start);

    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* crc_pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!crc_pdu) return -2; // error code for memory allocation failure

        crc_pdu->rx_ue_info.rnti = rand() % 1000; // random RNTI
        crc_pdu->rnti = rand() % 1000; // random RNTI
        crc_pdu->crc_indication.crcflag = (rand() & 1) ? CRCFLAG_SET : CRCFLAG_CLEAR; // random CRC flag

        if (*crc_list == NULL) *crc_list = crc_pdu;
        else {
            NFAPI_CRC_INDICATION_PDU_T* current = *crc_list;
            while (current->next != NULL) current = current->next;
            current->next = crc_pdu;
        }

        total_crc_indications++;
    }

    clock_gettime(CLOCK_REALTIME, &end);
    if ((end.tv_sec - start.tv_sec) > 5 || (end.tv_nsec / 1000000) > 5000000) return -3; // error code for timeout

    FILE* file = fopen("crc_indications.log", "a"); // append to log file
    if (!file) return -4; // error code for file operation failure

    for (NFAPI_CRC_INDICATION_PDU_T* crc_pdu = *crc_list; crc_pdu != NULL; crc_pdu = crc_pdu->next) {
        fprintf(file, "RX UE Information: rnti=%d\n", crc_pdu->rx_ue_info.rnti);
        fprintf(file, "RNTI: %d\n", crc_pdu->rnti);
        fprintf(file, "CRC Indication: crcflag=%s\n", crc_pdu->crc_indication.crcflag ? "SET" : "CLEAR");
        fprintf(file, "\n");
    }
    fclose(file);

    return 0;
}
