    NFAPI_CRC_INDICATION_PDU_T* result = NULL;
    int count = 0;

    // Set the seed for random number generation
    srand(time(NULL));

    while (count < n) {
        NFAPI_CRC_INDICATION_PDU_T* new_element = new NFAPI_CRC_INDICATION_PDU_T();

        if (new_element != NULL) {
            int rnti = rand();
            if (rnti > 0) {
                // Validate RNTI
                if (/* validate RNTI */) { // implement your validation logic here
                    new_element->RX_UE_INFORMATION_TAG = rand() % 100;
                    new_element->RNTI = rnti;
                    int crcflag = rand() & 1; // set CRCFLAG randomly
                    new_element->CRC_INDICATION_REL8_TAG = crcflag;

                    if (cpu_usage > CPU_USAGE_THRESHOLD) {
                        int capacity = static_cast<int>(CAPACITY_THRESHOLD);
                        if (result != NULL && count >= capacity) {
                            result = static_cast<NFAPI_CRC_INDICATION_PDU_T*>(realloc(result, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * capacity));
                            if (result == NULL) {
                                printf("Memory allocation failed!\n");
                            }
                        }
                    }

                    // Add the element to the list
                    if (result != NULL && count < capacity) {
                        result[count++] = *new_element;
                        delete new_element;
                    } else {
                        delete new_element;
                    }
                } else {
                    printf("Error: Invalid RNTI value!\n");
                    delete new_element;
                }
            } else {
                printf("Error: Memory allocation failed!\n");
                delete new_element;
            }
        } else {
            printf("Memory allocation failed!\n");
        }
    }

    if (result == NULL) {
        result = static_cast<NFAPI_CRC_INDICATION_PDU_T*>(malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T*) * n));
        if (result != NULL) {
            for (int i = 0; i < n; i++) {
                delete new NFAPI_CRC_INDICATION_PDU_T();
            }
        } else {
            printf("Memory allocation failed!\n");
        }
    }

    return result;
}
