**C Function (LTE_PHY_PDU Allocation)**
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    uint8_t L1_TFCI;
    uint8_t L1_RI;
    enum { HARQ_ACK, HARQ_NACK } L1_HARQ;
} LTE_PHY_PDU;

// Function to allocate and populate a list of LTE_PHY_PDU structures
int allocLTE_PHY_PDUs(int maxNumPDUs, int* numAllocations) {
    *numAllocations = 0;
    LTE_PHY_PDU** pduList = NULL;
    int allocatedCount = 0;

    // Allocate memory for the PDU list (handle failures)
    if ((pduList = (LTE_PHY_PDU**)malloc(maxNumPDUs * sizeof(LTE_PHY_PDU*))) == NULL) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        return -1;
    }

    // Populate each PDU structure with valid TFCI/RI and HARQ values
    for (int i = 0; i < maxNumPDUs; i++) {
        pduList[i] = (LTE_PHY_PDU*)malloc(sizeof(LTE_PHY_PDU));
        if (pduList[i] == NULL) {
            fprintf(stderr, "Error: Memory allocation failed\n");
            return -1;
        }
        pduList[i]->L1_TFCI = rand() % 256;
        pduList[i]->L1_RI = rand() % 4;
        if (rand() % 2) {
            pduList[i]->L1_HARQ = HARQ_ACK;
        } else {
            pduList[i]->L1_HARQ = HARQ_NACK;
        }
        allocatedCount++;
    }

    *numAllocations = allocatedCount;

    return 0;
}

void deallocLTE_PHY_PDUs(LTE_PHY_PDU** pduList, int maxNumPDUs) {
    for (int i = 0; i < maxNumPDUs; i++) {
        if (pduList[i] != NULL) {
            free(pduList[i]);
        }
    }
    free(pduList);
}
