    if (!(*ue_ctx_list = realloc(*ue_ctx_list, sizeof(LTE_Ue_Context*) * (*list_size)))) {
        ERROR_LOG("Memory allocation failed for UE context list.");
        return;
    }

    LTE_Ue_Context* new_ue_ctx = malloc(sizeof(LTE_Ue_Context));
    if (!new_ue_ctx) {
