    new_ue_ctx->ue_id = random(); // Replace with actual ID generation mechanism
    new_ue_ctx->rnti = random(); // Replace with actual RNTI generation mechanism
    memset(new_ue_ctx->srb1_config, 0, sizeof(new_ue_ctx->srb1_config));

    // Add the UE context to the list and log its addition
    if (NMS_API_add_ue_context(new_ue_ctx) != NMS_API_SUCCESS) {
        ERROR_LOG("Failed to add UE context to NMS.");
        free(new_ue_ctx);
        return;
    }

    INFO_LOG("Added new UE context with ID %u and RNTI %u.", new_ue_ctx->ue_id, new_ue_ctx->rnti);

    // Periodically clean up unused entries based on TTL
    if (*list_size > 1) {
        for (int i = *list_size - 2; i >= 0; --i) {
            if (get_time() - new_ue_ctx_list[i]->added_timestamp > ttl) {
                NMS_API_remove_ue_context(new_ue_ctx_list[i]);
                free(new_ue_ctx_list[i]);
                memmove(new_ue_ctx_list + i, new_ue_ctx_list + i + 1, sizeof(LTE_Ue_Context*) * (*list_size - i - 1));
                (*list_size)--;
            }
        }
    }

    return;
}
