#include "log.h"
#include "nfa_api_crc_indication_pdu_t.h"

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdu;
    pthread_mutex_t mutex;
} PduList;

PduList* pdu_list_create(size_t initial_capacity) {
    PduList* list = (PduList*)malloc(sizeof(PduList));
    list->pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void pdu_list_destroy(PduList* list) {
    if (!list) return;
    for (size_t i = 0; i < list->pdu_count; i++) {
        free(list->pdu[i].rx_ue_info_tag.rx_ue_info_bytes);
        free(list->pdu[i].crc_indication_rel8_tag.crc_flag_bits);
    }
    free(list->pdu);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int pdu_list_reserve(PduList* list, size_t new_capacity) {
    if (!list) return -1;
    NFAPI_CRC_INDICATION_PDU_T* new_pdu = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->pdu, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_pdu) return -2;
    list->pdu = new_pdu;
    return 0;
}

int pdu_list_append(PduList* list) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) return -1;
    pthread_mutex_lock(&list->mutex);
    pdu->rx_ue_info_tag.rx_ue_info_bytes = strdup("RX_UE_INFORMATION_TAG");
    pdu->rnti = rand();
    pdu->crc_indication_rel8_tag.crc_flag_bits = (char*)malloc(8);
    for (int i = 0; i < 8; i++) {
        pdu->crc_indication_rel8_tag.crc_flag_bits[i] = (char)(rand() & 1);
    }
    list->pdu[list->pdu_count++] = *pdu;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int main() {
    PduList* list = pdu_list_create(10);
    for (size_t i = 0; i < 10000; i++) {
        if (pdu_list_append(list)) break;
    }
    pdu_list_destroy(list);
    return 0;
}
