typedef struct LTE_PHY_UE_MEASUREMENTS {
    int UE_ID;
    int CELL_ID;
    float RSRP;
    float RSRQ;
    float SINR;
} LTE_PHY_UE_MEASUREMENT;

LTE_PHY_UE_MEASUREMENT* createMeasurementsList(int numMeasurements) {
    LTE_PHY_UE_MEASUREMENT* measurements = (LTE_PHY_UE_MEASUREMENT*)malloc(numMeasurements * sizeof(LTE_PHY_UE_MEASUREMENT));

    for (int i = 0; i < numMeasurements; i++) {
        measurements[i].UE_ID = rand() % 1000;
        measurements[i].CELL_ID = rand() % 500;

        measurements[i].RSRP = (float)(rand() % 100) / 10.0;
        measurements[i].RSRQ = (float)(rand() % 20) - 10.0;
        measurements[i].SINR = (float)(rand() % 30) + 5.0;

        printf("Measurement %d: UE_ID=%d, CELL_ID=%d, RSRP=%.2f, RSRQ=%.2f, SINR=%.2f\n", i + 1, measurements[i].UE_ID, measurements[i].CELL_ID, measurements[i].RSRP, measurements[i].RSRQ, measurements[i].SINR);
    }

    return measurements;
}

int validateMeasurementsList(LTE_PHY_UE_MEASUREMENT* measurements, int numMeasurements) {
    for (int i = 0; i < numMeasurements; i++) {
        if ((measurements[i].UE_ID <= 0 || measurements[i].CELL_ID <= 0) ||
            (measurements[i].RSRP < -20.0 || measurements[i].RSRQ < -10.0 || measurements[i].SINR < 0.0)) {
            printf("Invalid measurement at index %d: UE_ID=%d, CELL_ID=%d, RSRP=%.2f, RSRQ=%.2f, SINR=%.2f\n", i + 1, measurements[i].UE_ID, measurements[i].CELL_ID, measurements[i].RSRP, measurements[i].RSRQ, measurements[i].SINR);
            return -1;
        }
    }

    return 0;
}

int main() {
    srand(time(NULL));

    int numMeasurements = 10;
    LTE_PHY_UE_MEASUREMENT* measurements = createMeasurementsList(numMeasurements);

    if (validateMeasurementsList(measurements, numMeasurements) != 0) {
        printf("Invalid measurement list. Aborting.\n");
        free(measurements);
        return -1;
    }

    printf("Measurement list validated successfully.\n");

    free(measurements);

    return 0;
}
