typedef struct {
    int int_field;
} record_t;

int error_code = 0;
record_t* allocate_memory(int offset_count, int key_count, int min_value, int max_value) {
    if ((offset_count <= 0) || (key_count <= 0)) {
        printf("Invalid count values\n");
        return NULL;
    }

    // Allocate memory for and initialize arrays
    long* offsets = (long*)malloc(offset_count * sizeof(long));
    int* keys = (int*)malloc(key_count * sizeof(int));

    if (!offsets || !keys) {
        error_code = 1;
        printf("Memory allocation failed\n");
        return NULL;
    }

    // Initialize arrays
    for (int i = 0; i < offset_count; i++) {
        offsets[i] = (long)i;
    }
    for (int i = 0; i < key_count; i++) {
        keys[i] = i % 10; // Replace with actual initialization logic if needed
    }

    // Allocate memory for and initialize record array
    record_t* records = (record_t*)malloc((offset_count + key_count) * sizeof(record_t));

    if (!records) {
        error_code = 1;
        printf("Memory allocation failed\n");
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize record array
    srand(time(NULL)); // Seed random number generator
    for (int i = 0; i < offset_count + key_count; i++) {
        records[i].int_field = rand() % (max_value - min_value) + min_value;
    }

    return records;
}

void deallocate_memory(record_t* records, long* offsets, int* keys) {
    if (!records || !offsets || !keys) {
        printf("Invalid memory to deallocate\n");
        return;
    }

    free(records);
    free(offsets);
    free(keys);
}

int validate_records(record_t* records, int offset_count, int key_count) {
    for (int i = 0; i < offset_count + key_count; i++) {
        if (records[i].int_field < 0 || records[i].int_field > (max_value - min_value)) {
            return 1;
        }
    }
    return 0;
}

int main() {
    int offset_count = 10;
    int key_count = 20;
    int min_value = 0;
    int max_value = 100;

    record_t* records = allocate_memory(offset_count, key_count, min_value, max_value);

    if (records) {
        // Validate the integrity of the allocated structures
        if (validate_records(records, offset_count, key_count)) {
            printf("Error: Invalid records\n");
            deallocate_memory(records, NULL, NULL);
            return 1;
        }

        // Log any errors related to memory allocation or deallocation
        printf("Memory allocated successfully\n");

        // Deallocate the memory when it is no longer needed
        deallocate_memory(records, NULL, NULL);

    } else {
        printf("Error: Memory allocation failed\n");
    }
    return 0;
}
